insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:aquarius', 'fr', '1', '{"keywords":["cordialité","indépendance","originalité","égalité","distance amicale"],"essence":"L’Ascendant en Verseau, signe fixe d’air, donne une manière d’aborder le monde amicale, indépendante et décalée. La première impression est celle d’une cordialité égale pour tous, teintée de distance.","light":["Camaraderie immédiate, sans hiérarchie","Originalité assumée dans la façon d’être","Ouverture d’esprit devant ce qui sort de l’ordinaire"],"shadow":["Cordialité qui garde tout le monde à la même distance","Goût de surprendre, parfois au mauvais moment","Résistance aux codes, y compris aux plus utiles"],"behaviors":["Parler à la direction et aux stagiaires exactement de la même façon","Lancer un sujet inattendu au milieu du repas","Ignorer le code d’une soirée sans même y penser","Quitter une fête sans prévenir, par simple besoin d’air","Poser la question que personne n’osait poser"],"summary":{"soft":"Tu abordes chacun en camarade, sans jamais te soucier des rangs. Ton originalité libère : près de toi, on ose un peu plus facilement sortir du cadre.","cash":"Tu parles au grand patron comme au livreur, ce qui amuse beaucoup le livreur. Tu quittes les soirées sans prévenir, par la méthode du fantôme.","expert":"L’Ascendant en Verseau, signe fixe d’air, donne un abord cordial, égalitaire et singulier. Vous engagez le contact par l’idée plutôt que par l’affect ; une distance amicale structure vos premiers échanges."},"roastAngles":{"soft":["Tu arrives avec une idée neuve et un sourire libre : on ne sait jamais d’où tu viens, et tant mieux."],"cash":["Au dîner, tu as lancé “et si on supprimait les lundis ?”, et le plat a refroidi pendant une heure.","Tout le monde t’adore, personne n’a ton adresse, et ça te convient parfaitement comme ça."],"expert":["Ascendant en Verseau : abord fixe, d’air. Vous accueillez tout le monde, à égale et prudente distance."]},"roastWeight":2,"avoid":["Décrire l’apparence ou le style vestimentaire","Réduire le placement à la provocation"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:aries', 'fr', '1', '{"keywords":["abord direct","rapidité","initiative","impatience","franchise"],"essence":"L’Ascendant en Bélier, signe cardinal de feu, donne une manière d’aborder le monde directe, rapide et combative. La première impression est celle de quelqu’un qui va droit au but.","light":["Abord franc, qui met vite les choses au clair","Réactivité devant l’imprévu","Goût de prendre les devants"],"shadow":["Entrée en matière brusque","Impatience visible dans les files d’attente et les réunions","Tendance à vivre chaque échange comme un bras de fer"],"behaviors":["Traverser une pièce au pas de course","Tendre la main avant que l’autre ait fini d’arriver","Dire « bon, on y va ? » après deux minutes","Appuyer plusieurs fois sur le bouton de l’ascenseur","Répondre du tac au tac, puis nuancer"],"summary":{"soft":"Tu abordes la vie de face, le regard franc et le pas décidé. On sait tout de suite à qui on a affaire, et cette clarté met en confiance.","cash":"Tu entres dans une pièce comme si tu avais un train à prendre. La première impression que tu donnes : “bon, on commence ?”","expert":"L’Ascendant en Bélier, signe cardinal de feu, imprime à l’abord du monde un style direct et pionnier. Vous prenez l’initiative du contact ; la spontanéité prime chez vous sur la diplomatie."},"roastAngles":{"soft":["Tu arrives comme un matin de printemps : d’un coup, avec de l’élan et l’envie que ça démarre."],"cash":["Tu appuies quatre fois sur le bouton de l’ascenseur, au cas où il n’aurait pas saisi l’urgence.","Dans une file d’attente, tu soupires si fort que trois personnes se retournent pour demander pardon."],"expert":["Ascendant en Bélier : abord cardinal, de feu. Vous en venez au fait sans préambule, ni précaution."]},"roastWeight":3,"avoid":["Décrire l’apparence ou le corps","Présenter la franchise comme de l’agressivité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:cancer', 'fr', '1', '{"keywords":["réserve","prudence","douceur","réceptivité","protection"],"essence":"L’Ascendant en Cancer, signe cardinal d’eau, donne une manière d’aborder le monde prudente, douce et protectrice. La première impression est celle d’une réserve attentive, qui s’ouvre une fois la confiance installée.","light":["Accueil chaleureux pour qui a passé la première barrière","Sensibilité immédiate à l’ambiance d’un lieu","Attention spontanée au confort des autres"],"shadow":["Carapace levée devant les inconnus","Humeur qui se devine au premier coup d’œil","Repli rapide quand l’accueil est froid"],"behaviors":["Rester près de la porte en arrivant dans une soirée","Proposer un verre d’eau, un coussin ou un gilet","Approcher les gens de biais, par petites touches","Sentir l’ambiance d’une pièce avant de dire bonjour","Partir sans dire au revoir quand l’atmosphère se tend"],"summary":{"soft":"Tu approches le monde à pas doux, en prenant la température avant d’entrer. Une fois la confiance là, on découvre un accueil d’une grande tendresse.","cash":"En soirée, tu restes près de la sortie le temps de vérifier les gens. Une heure plus tard, tu demandes à chacun s’il a assez mangé.","expert":"L’Ascendant en Cancer, signe cardinal d’eau, donne un abord réservé et réceptif. Vous captez le climat d’un lieu avant de vous y exposer ; la confiance conditionne chez vous toute ouverture."},"roastAngles":{"soft":["Tu entres sur la pointe des pieds, et tu finis par border tout le monde : c’est ta signature."],"cash":["Tu n’as pas encore dit bonjour que tu sais déjà qui ne t’aime pas, sur la foi d’un sourcil.","Tu arrives chez les gens avec un gâteau, un gilet de secours et un plan pour repartir tôt."],"expert":["Ascendant en Cancer : abord cardinal, d’eau. Vous avancez latéralement, et jamais sans abri à portée."]},"roastWeight":2,"avoid":["Décrire l’apparence ou le corps","Présenter la réserve comme de la timidité excessive"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:capricorn', 'fr', '1', '{"keywords":["sérieux","retenue","maîtrise","fiabilité","humour sec"],"essence":"L’Ascendant en Capricorne, signe cardinal de terre, donne une manière d’aborder le monde sérieuse, réservée et maîtrisée. La première impression est celle d’une maturité qui inspire le respect avant la familiarité.","light":["Fiabilité perceptible dès la première rencontre","Sang-froid en public","Sens des convenances et de la mesure"],"shadow":["Abord austère, qui tient à distance","Difficulté à se détendre devant des inconnus","Tendance à se présenter par sa fonction"],"behaviors":["Tendre une main très officielle à une fête d’anniversaire","Parler de travail dès la deuxième phrase","Arriver à l’heure exacte, ni avant ni après","Garder son manteau la première demi-heure","Lâcher une blague pince-sans-rire que personne n’attendait"],"summary":{"soft":"Tu abordes le monde avec retenue, comme quelqu’un qui sait ce que valent les choses. Ta réserve fond avec le temps, et laisse voir un humour très tendre.","cash":"Tu as l’air de passer un entretien d’embauche, même à un barbecue. Tu te détends vers la troisième rencontre, sur réservation.","expert":"L’Ascendant en Capricorne, signe cardinal de terre, donne un abord sobre, contrôlé et responsable. Vous donnez d’abord une impression de sérieux ; la chaleur se révèle avec le temps et la confiance."},"roastAngles":{"soft":["Tu ne te livres pas au premier venu, et ceux qui attendent découvrent quelqu’un de très drôle."],"cash":["À la question “tu fais quoi dans la vie ?”, tu réponds avec un organigramme et des échéances.","Tu gardes ton manteau pendant l’apéritif, au cas où la soirée manquerait de sérieux."],"expert":["Ascendant en Capricorne : abord cardinal, de terre. Vous faites d’abord bonne impression, puis seulement connaissance."]},"roastWeight":2,"avoid":["Décrire l’apparence, l’âge apparent ou le corps","Présenter la réserve comme de l’arrogance"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:gemini', 'fr', '1', '{"keywords":["vivacité","curiosité","conversation","mobilité","nervosité"],"essence":"L’Ascendant en Gémeaux, signe mutable d’air, donne une manière d’aborder le monde vive, curieuse et bavarde. La première impression est celle d’un esprit en mouvement, qui engage la conversation sans effort.","light":["Aisance à lier connaissance","Curiosité sincère pour chaque personne croisée","Humour rapide qui brise la glace"],"shadow":["Attention qui papillonne en pleine conversation","Nervosité dans les moments d’attente","Difficulté à supporter le silence"],"behaviors":["Parler avec les mains","Engager la conversation avec un inconnu dans une file","Consulter son téléphone tout en posant une question","Passer d’un groupe à l’autre dans une soirée","Connaître le prénom du serveur avant l’entrée"],"summary":{"soft":"Tu abordes le monde avec une question au bord des lèvres. Ta curiosité met les gens à l’aise : avec toi, la conversation démarre toute seule.","cash":"Tu connais la vie du chauffeur de taxi avant le premier feu rouge. Tu poses une question, et tu regardes ailleurs pendant la réponse.","expert":"L’Ascendant en Gémeaux, signe mutable d’air, donne un abord mobile, verbal et adaptable. Vous engagez le contact par la parole et la question ; l’attention se déplace vite d’un objet à l’autre."},"roastAngles":{"soft":["Tu fais connaissance comme on ouvre un livre : avec gourmandise, et déjà l’envie du suivant."],"cash":["En soirée, tu parles à tout le monde, et tu repars sans avoir fini une seule conversation.","Tu dis “non mais raconte”, et tu coupes au bout de quatre mots avec une anecdote à toi."],"expert":["Ascendant en Gémeaux : abord mutable, d’air. Vous questionnez beaucoup, et écoutez la moitié des réponses."]},"roastWeight":2,"avoid":["Décrire l’apparence ou le corps","Parler de double visage"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:leo', 'fr', '1', '{"keywords":["présence","assurance","chaleur","expressivité","fierté"],"essence":"L’Ascendant en Lion, signe fixe de feu, donne une manière d’aborder le monde chaleureuse, assurée et expressive. La première impression est celle d’une présence qui occupe naturellement le centre.","light":["Assurance qui inspire confiance","Chaleur immédiate dans le contact","Sens de la mise en scène et de la fête"],"shadow":["Difficulté à rester en retrait, même quand il le faudrait","Fierté piquée par un accueil tiède","Tendance à occuper tout l’espace de parole"],"behaviors":["Faire une entrée remarquée, même en retard","Parler assez fort pour que la table voisine suive","Saluer toute la salle, une personne après l’autre","Raconter une histoire debout","Remarquer qui n’a pas levé les yeux"],"summary":{"soft":"Tu entres et la pièce gagne quelques degrés. Ta présence est généreuse : tu donnes de la chaleur à chacun, et chacun se sent à sa place.","cash":"Tu ne passes pas une porte, tu fais une entrée. Même pour aller chercher du pain, il y a une intention de mise en scène.","expert":"L’Ascendant en Lion, signe fixe de feu, donne un abord affirmé, chaleureux et démonstratif. Vous occupez spontanément le premier plan ; l’image donnée engage votre fierté."},"roastAngles":{"soft":["Tu arrives avec du soleil plein les poches, et tu en distribues à toute la tablée."],"cash":["Tu racontes ton week-end à voix haute dans le train, et le wagon entier attend la suite.","Tu arrives en retard exprès : une entrée sans public, pour toi, c’est juste une porte."],"expert":["Ascendant en Lion : abord fixe, de feu. Vous ne cherchez pas la scène ; vous la supposez acquise."]},"roastWeight":3,"avoid":["Décrire l’apparence, la chevelure ou le corps","Réduire le placement à la vantardise"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:libra', 'fr', '1', '{"keywords":["courtoisie","conciliation","charme relationnel","souci de plaire","médiation"],"essence":"L’Ascendant en Balance, signe cardinal d’air, donne une manière d’aborder le monde aimable, conciliante et soignée. La première impression est celle d’une courtoisie qui cherche à plaire à chacun.","light":["Charme relationnel et sens de l’accueil","Art de mettre deux personnes en relation","Courtoisie constante, même sous tension"],"shadow":["Difficulté à dire non en face","Opinion ajustée à l’interlocuteur","Souci constant de l’impression produite"],"behaviors":["Sourire à quelqu’un qui vient de doubler dans la file","Complimenter l’hôte dès le pas de la porte","Dire « avec plaisir » à une invitation qui n’enchante pas","Demander l’avis de la tablée avant de commander","Présenter les gens les uns aux autres toute la soirée"],"summary":{"soft":"Tu abordes chacun avec une grâce qui met tout de suite à l’aise. Près de toi, les rencontres se font en douceur et personne ne reste dans son coin.","cash":"Tu dis “avec grand plaisir” à des invitations qui te donnent envie de changer de pays. Et tu y vas, avec un cadeau.","expert":"L’Ascendant en Balance, signe cardinal d’air, donne un abord courtois, conciliant et attentif à la forme. Vous abordez l’autre par la médiation ; plaire est chez vous une stratégie d’équilibre."},"roastAngles":{"soft":["Tu arrondis les angles rien qu’en disant bonjour : c’est un talent, et il fait du bien."],"cash":["Quelqu’un te marche sur le pied, et c’est toi qui demandes pardon, avec un sourire sincère.","Tu approuves la personne en face, puis sa voisine. Elles ne sont pas d’accord entre elles."],"expert":["Ascendant en Balance : abord cardinal, d’air. Vous séduisez par principe, et tranchez par exception."]},"roastWeight":2,"avoid":["Décrire l’apparence, l’élégance vestimentaire ou le corps","Assimiler la courtoisie à de la fausseté"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:pisces', 'fr', '1', '{"keywords":["douceur","réceptivité","rêverie","adaptation","flou"],"essence":"L’Ascendant en Poissons, signe mutable d’eau, donne une manière d’aborder le monde douce, flottante et réceptive. La première impression est celle d’une présence rêveuse, qui épouse l’ambiance plus qu’elle ne s’impose.","light":["Douceur qui désarme les plus méfiants","Adaptation intuitive à chaque interlocuteur","Écoute enveloppante, sans jugement"],"shadow":["Contours flous, difficiles à saisir pour les autres","Tendance à se fondre dans le décor","Retards et oublis mis sur le compte de la rêverie"],"behaviors":["Arriver en retard sans avoir vu l’heure","Dire oui d’un air vague, puis demander de répéter","Se perdre sur un trajet pourtant connu","Prendre l’accent de la personne en face","Recevoir les confidences d’un inconnu dans le train"],"summary":{"soft":"Tu abordes le monde comme on entre dans l’eau : doucement, en te laissant porter. Les gens se confient à toi sans savoir pourquoi.","cash":"Tu arrives en retard avec l’air de sortir d’un rêve, et on te pardonne. Tu as dit “oui oui” à une question qui commençait par “où”.","expert":"L’Ascendant en Poissons, signe mutable d’eau, donne un abord souple, perméable et peu défini. Vous vous ajustez à l’ambiance plus que vous ne l’orientez ; la présence est réelle, mais diffuse."},"roastAngles":{"soft":["Tu flottes un peu au-dessus du quotidien, et ta douceur fait baisser la voix de tout le monde."],"cash":["Des inconnus te racontent leur vie dans le train. Tu voulais juste lire, mais tu connais déjà le chat.","Tu as réussi à te perdre sur le chemin de chez toi, celui que tu prends depuis des années."],"expert":["Ascendant en Poissons : abord mutable, d’eau. Votre présence est réelle, mais réglée sur un fuseau horaire personnel."]},"roastWeight":2,"avoid":["Décrire l’apparence ou le regard comme un trait corporel","Présenter la rêverie comme de l’incompétence"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:sagittarius', 'fr', '1', '{"keywords":["enthousiasme","ouverture","jovialité","aventure","familiarité"],"essence":"L’Ascendant en Sagittaire, signe mutable de feu, donne une manière d’aborder le monde enthousiaste, ouverte et sans façons. La première impression est celle d’une bonne humeur franche, toujours prête à partir.","light":["Jovialité qui met tout le monde à l’aise","Confiance spontanée envers les inconnus","Goût de l’aventure dès qu’une porte s’entrouvre"],"shadow":["Familiarité trop rapide","Gestes et paroles plus larges que la pièce","Engagements lancés dans l’élan de la rencontre"],"behaviors":["Rire fort dans un endroit silencieux","Tutoyer tout le monde au bout de deux phrases","Renverser un verre en racontant une histoire","Inviter un inconnu à un projet de voyage","Dire « on s’appelle » avec une sincérité totale et sans suite"],"summary":{"soft":"Tu arrives avec le sourire large et l’envie de tout découvrir. Ta confiance en la vie ouvre les portes, et les gens te suivent sans trop savoir où.","cash":"Tu tutoies tout le monde au bout de deux phrases, y compris la directrice. Tu racontes avec les bras, et les verres le savent.","expert":"L’Ascendant en Sagittaire, signe mutable de feu, donne un abord expansif, confiant et direct. Vous abordez l’inconnu avec optimisme ; la retenue et le détail passent au second plan."},"roastAngles":{"soft":["Tu abordes chaque rencontre comme un départ en voyage : sac léger, cœur grand ouvert."],"cash":["Tu as invité à ton anniversaire quelqu’un croisé il y a dix minutes à l’arrêt de bus.","Tu ris si fort à la bibliothèque que même les livres te demandent de baisser d’un ton."],"expert":["Ascendant en Sagittaire : abord mutable, de feu. Vous vous engagez large, avec une bonne foi entière."]},"roastWeight":2,"avoid":["Décrire l’apparence ou le corps","Présenter la spontanéité comme un manque de sérieux"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:scorpio', 'fr', '1', '{"keywords":["réserve","intensité","vigilance","perspicacité","mystère"],"essence":"L’Ascendant en Scorpion, signe fixe d’eau, donne une manière d’aborder le monde réservée, intense et scrutatrice. La première impression est celle d’une présence magnétique, qui observe plus qu’elle ne se livre.","light":["Perspicacité immédiate sur les gens","Présence forte sans effort de parole","Discrétion à toute épreuve sur ce qui est confié"],"shadow":["Abord impénétrable, qui intimide","Méfiance de principe devant les nouvelles têtes","Réticence à livrer la moindre information personnelle"],"behaviors":["S’asseoir dos au mur, face à la porte","Fixer l’interlocuteur sans ciller","Répondre à une question par une autre question","Laisser un silence s’installer sans le combler","Retenir un détail lâché par mégarde trois mois plus tôt"],"summary":{"soft":"Tu abordes le monde en silence, avec une attention entière. Ce mystère n’a rien d’un mur : c’est une porte qui s’ouvre lentement, pour ceux qui le méritent.","cash":"Tu réponds “et toi ?” à toutes les questions personnelles. Au bout d’une heure, tu sais tout des gens, et eux connaissent ton prénom, à peu près.","expert":"L’Ascendant en Scorpion, signe fixe d’eau, donne un abord réservé, intense et vigilant. Vous sondez l’interlocuteur avant de vous découvrir ; la maîtrise de votre image est une protection."},"roastAngles":{"soft":["Tu regardes les gens comme on lit entre les lignes, et tu gardes leurs secrets comme les tiens."],"cash":["Au restaurant, tu prends la chaise face à la porte, comme si le dessert pouvait mal tourner.","On te demande “ça va ?” et tu plisses les yeux, le temps de comprendre ce qu’on veut vraiment."],"expert":["Ascendant en Scorpion : abord fixe, d’eau. Vous laissez parler autrui ; c’est une méthode d’enquête."]},"roastWeight":3,"avoid":["Décrire le regard ou l’apparence comme un trait corporel","Faire du placement une figure inquiétante"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:taurus', 'fr', '1', '{"keywords":["calme","patience","abord posé","prudence","constance"],"essence":"L’Ascendant en Taureau, signe fixe de terre, donne une manière d’aborder le monde posée, patiente et rassurante. La première impression est celle d’un calme que rien ne presse.","light":["Présence tranquille, qui met à l’aise","Constance dans la façon d’être, quel que soit le public","Sens pratique dès le premier contact"],"shadow":["Lenteur à s’ouvrir aux nouvelles têtes","Refus de se laisser bousculer, même pour de bonnes raisons","Méfiance devant tout ce qui change les habitudes"],"behaviors":["Arriver à son rythme, sans courir","Choisir la chaise la plus confortable de la pièce","Écouter longuement avant de donner un avis","Répondre « rien ne presse » à quelqu’un de pressé","Observer le buffet avant les invités"],"summary":{"soft":"Tu arrives dans la vie des gens comme une après-midi tranquille. Ton calme rassure d’emblée, et l’on sent que tu ne joues aucun rôle.","cash":"Tu ne cours jamais, même sous la pluie, même pour le bus. À une soirée, tu repères d’abord le canapé, ensuite le buffet, enfin les gens.","expert":"L’Ascendant en Taureau, signe fixe de terre, confère un abord stable, mesuré et concret. Vous prenez le temps d’évaluer avant de vous lier ; votre réserve initiale relève de la prudence."},"roastAngles":{"soft":["Tu prends le temps d’arriver, et dès que tu t’installes, tout le monde se détend d’un cran."],"cash":["Le bus part sans toi et tu le regardes s’éloigner avec dignité : courir, ce n’est pas ton projet.","Il te faut six mois pour tutoyer la boulangère, mais après, c’est pour la vie entière."],"expert":["Ascendant en Taureau : abord fixe, de terre. Vous vous laissez approcher lentement, et à vos conditions."]},"roastWeight":2,"avoid":["Décrire l’apparence ou le corps","Assimiler le calme à de la mollesse"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('asc_sign:virgo', 'fr', '1', '{"keywords":["discrétion","observation","méthode","serviabilité","réserve"],"essence":"L’Ascendant en Vierge, signe mutable de terre, donne une manière d’aborder le monde discrète, observatrice et méthodique. La première impression est celle d’une réserve polie, attentive au moindre détail.","light":["Sens de l’observation dès les premières minutes","Politesse sobre, sans effet de manche","Disponibilité pour rendre service"],"shadow":["Réserve qui passe pour de la distance","Regard critique difficile à mettre en veille","Gêne dès que l’attention se porte sur soi"],"behaviors":["Arriver dix minutes en avance et attendre dehors","Remarquer la tache sur la nappe avant de s’asseoir","Proposer de débarrasser chez des gens rencontrés une heure plus tôt","Demander pardon en entrant dans une pièce","Préparer ses phrases avant un appel téléphonique"],"summary":{"soft":"Tu abordes le monde avec délicatesse, en observant avant de parler. Rien ne t’échappe, et ta discrétion cache une vraie envie d’aider.","cash":"Tu arrives en avance, tu attends dehors pour ne pas déranger, et tu sonnes pile à l’heure. Puis tu proposes de faire la vaisselle.","expert":"L’Ascendant en Vierge, signe mutable de terre, donne un abord réservé, analytique et serviable. Vous observez avant de vous exposer ; le souci de bien faire règle votre présentation."},"roastAngles":{"soft":["Tu entres sans bruit et tu remarques tout : avec toi, personne ne se sent jamais oublié."],"cash":["Tu répètes ta commande dans ta tête avant le serveur, et tu dis quand même “euh, pardon”.","Chez les autres depuis dix minutes, tu as déjà repéré le cadre de travers et tu souffres en silence."],"expert":["Ascendant en Vierge : abord mutable, de terre. Vous évaluez d’abord la situation, puis sa marge d’erreur."]},"roastWeight":2,"avoid":["Décrire l’apparence ou le corps","Présenter la réserve comme de la froideur"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:aquarius', 'fr', '1', '{"keywords":["originalité","indépendance","innovation","collectif","singularité"],"essence":"Le Milieu du Ciel en Verseau donne une image publique singulière : ce qui se remarque, c’est l’indépendance d’esprit, le goût d’innover et une ambition tournée vers le collectif.","light":["Réputation d’originalité","Capacité à proposer ce que personne n’avait envisagé","Esprit d’équipe sans esprit de clan"],"shadow":["Image de distance","Refus des cadres par principe","Parcours difficile à suivre de l’extérieur"],"behaviors":["Proposer une méthode différente de celle prévue","Décrire son activité par ce qu’elle n’est pas","Travailler à des horaires inhabituels","Défendre l’intérêt du groupe face à la hiérarchie"],"summary":{"soft":"Le monde te voit comme une voix à part, et c’est une chance. Ton ambition regarde vers l’avenir : tu veux inventer, et que cela serve à plusieurs.","cash":"Ta réputation : la personne qui lance « et si on faisait autrement ? » à cinq minutes de la fin. Ton ambition refuse les cases, sauf celle qu’elle a dessinée.","expert":"Le Milieu du Ciel en Verseau oriente la vocation vers l’innovation et le collectif : image publique indépendante, atypique, tournée vers l’avenir. L’ambition privilégie la liberté sur le statut."},"roastAngles":{"soft":["Tu ne ressembles à personne, sans même essayer, et c’est ce qui retient l’attention."],"cash":["Tu expliques ton métier en commençant par « c’est un peu difficile à expliquer ».","Tu refuses l’organigramme, puis tu en proposes un nouveau, en forme de cercle."],"expert":["Le Milieu du Ciel en Verseau fait de la singularité une signature : la réputation y naît de l’écart."]},"roastWeight":2,"avoid":["Évoquer un engagement militant précis","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:aries', 'fr', '1', '{"keywords":["esprit pionnier","initiative","compétition","visibilité directe","indépendance"],"essence":"Le Milieu du Ciel en Bélier donne une image publique de pionnier : ce qui se voit d’abord, c’est l’initiative, l’énergie et le goût d’ouvrir la voie.","light":["Réputation de courage et de franchise","Capacité à prendre la tête sans invitation","Ambition qui s’assume ouvertement"],"shadow":["Image d’impatience face aux lenteurs collectives","Besoin d’arriver en premier","Lassitude une fois le sommet atteint"],"behaviors":["Lever la main avant la fin de la question","Lancer un projet sans attendre le feu vert","Transformer un objectif en course","Préférer mener une petite équipe plutôt que suivre une grande"],"summary":{"soft":"Aux yeux du monde, tu avances en tête, flamme à la main. Ton ambition est franche : tu veux ouvrir des chemins, et les autres suivent parce que tu y vas.","cash":"Ta réputation : la personne qui a déjà commencé pendant que les autres lisent l’ordre du jour. Ton ambition ne supporte ni la deuxième place ni la file d’attente.","expert":"Le Milieu du Ciel en Bélier oriente la vocation vers l’initiative et la conquête : image publique directe, combative, autonome. L’ambition s’exprime par le défi plus que par la durée."},"roastAngles":{"soft":["Ton arrivée se remarque de loin, et chacun sent que quelque chose commence."],"cash":["Tu annonces « je m’en occupe » avant de savoir de quoi il s’agit exactement.","Tu transformes une réunion d’équipe en ligne de départ, chronomètre compris."],"expert":["Le Milieu du Ciel en Bélier associe la réussite à la première place : l’image est celle du précurseur."]},"roastWeight":2,"avoid":["Donner un conseil de carrière","Annoncer une réussite","Citer des métiers comme une prescription"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:cancer', 'fr', '1', '{"keywords":["protection","proximité","sensibilité publique","attachement","bienveillance"],"essence":"Le Milieu du Ciel en Cancer donne une image publique protectrice : ce qui se perçoit, c’est le soin, la proximité et une ambition liée au besoin de se rendre utile aux siens.","light":["Réputation de bienveillance","Capacité à créer une ambiance de famille autour d’un projet","Mémoire des personnes et des histoires"],"shadow":["Humeur visible de l’extérieur","Difficulté à séparer l’affectif du rôle public","Ambition freinée par la peur de déplaire"],"behaviors":["Se souvenir des anniversaires de toute l’équipe","Prendre les nouveaux sous son aile","Vivre une critique de son travail comme une affaire personnelle","Décorer son bureau comme un salon"],"summary":{"soft":"Le monde voit en toi un refuge. Ton ambition ressemble à une maison à agrandir : tu veux réussir pour abriter, entourer, faire tenir ensemble.","cash":"Ta réputation : la personne qui a des mouchoirs, des gâteaux et un avis sur la vie de chacun. Une remarque sur ton travail, et la semaine entière en prend un coup.","expert":"Le Milieu du Ciel en Cancer lie la vocation au soin et à l’appartenance : image publique sensible, protectrice, fluctuante. L’ambition répond à un besoin de sécurité et d’ancrage."},"roastAngles":{"soft":["Les gens viennent vers toi comme vers une fenêtre éclairée : parce qu’il y fait bon."],"cash":["Tu connais le prénom des enfants, du chien et de la grand-mère de chaque collègue.","Tu relis un retour un peu sec et tu y penses jusqu’au dimanche soir."],"expert":["Le Milieu du Ciel en Cancer donne à l’image publique une tonalité protectrice et changeante."]},"roastWeight":2,"avoid":["Assigner un rôle maternel","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:capricorn', 'fr', '1', '{"keywords":["autorité","sérieux","persévérance","statut","responsabilité"],"essence":"Le Milieu du Ciel en Capricorne donne une image publique sérieuse et structurée : ce qui se perçoit, c’est l’autorité, la persévérance et une ambition de long terme.","light":["Réputation de solidité","Sens des responsabilités reconnu","Patience devant les ascensions lentes"],"shadow":["Image de froideur","Identité trop confondue avec la fonction","Difficulté à déléguer"],"behaviors":["Arriver avant tout le monde et partir après","Parler de son travail dès la deuxième phrase d’une présentation","Garder un registre professionnel même dans un message amical","Se fixer des objectifs sur plusieurs années"],"summary":{"soft":"Le monde te voit comme une montagne : stable, haute, digne de confiance. Ton ambition est patiente, et tu sais que les sommets se gagnent pas à pas.","cash":"Tu as l’air responsable même en pyjama. Tu te présentes par ton métier, y compris à un mariage, et ton ambition a un calendrier, des jalons et un comité de suivi.","expert":"Le Milieu du Ciel en Capricorne place la vocation sous le signe de la construction et du statut : image publique sobre, compétente, autoritaire. L’ambition s’inscrit dans le temps long."},"roastAngles":{"soft":["Les clés te sont confiées sans hésiter, et tu les rends toujours à l’heure."],"cash":["Tu signes un message d’anniversaire avec « bien cordialement ».","Tu réponds « quels sont les objectifs ? » à une invitation à pique-niquer."],"expert":["Le Milieu du Ciel en Capricorne lie la réputation à l’endurance : l’autorité s’y acquiert par paliers."]},"roastWeight":2,"avoid":["Annoncer une réussite sociale","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:gemini', 'fr', '1', '{"keywords":["polyvalence","parole","curiosité","réseau","mobilité"],"essence":"Le Milieu du Ciel en Gémeaux donne une image publique mobile et bavarde : ce qui se retient, c’est la vivacité d’esprit, la polyvalence et le goût de transmettre.","light":["Aisance à l’oral reconnue","Capacité à mener plusieurs rôles de front","Curiosité qui rend les sujets accessibles"],"shadow":["Image d’éparpillement","Ambitions changeantes","Difficulté à tenir dans une seule étiquette"],"behaviors":["Avoir deux activités et une troisième en projet","Connaître quelqu’un dans chaque service","Raconter son parcours en plusieurs versions","Répondre aux messages pendant une présentation"],"summary":{"soft":"Le monde te voit comme une voix vive, curieuse de tout. Ton ambition n’a pas une seule route : elle aime les carrefours, les mots et les rencontres.","cash":"Personne ne sait exactement ce que tu fais, mais tout le monde en a déjà entendu parler. Ton ambition change de sujet plus vite que toi.","expert":"Le Milieu du Ciel en Gémeaux place la vocation sous le signe de l’échange : image publique mobile, polyvalente, verbale. L’ambition se déploie en plusieurs directions simultanées."},"roastAngles":{"soft":["Ta voix se reconnaît entre toutes : elle relie les gens et donne envie d’en savoir plus."],"cash":["Tu résumes ton parcours en cinq versions selon la personne qui pose la question.","Tu as trois titres dans ta signature et un quatrième en cours de rédaction."],"expert":["Le Milieu du Ciel en Gémeaux diversifie la vocation : la réputation y repose sur la parole."]},"roastWeight":2,"avoid":["Parler d’instabilité comme d’un défaut de sérieux","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:leo', 'fr', '1', '{"keywords":["rayonnement","prestige","autorité","créativité","fierté"],"essence":"Le Milieu du Ciel en Lion donne une image publique rayonnante : ce qui se remarque, c’est la présence, le sens du prestige et une ambition qui tient à se montrer.","light":["Charisme reconnu","Générosité dans la mise en valeur des autres","Fierté du travail signé"],"shadow":["Besoin de reconnaissance visible","Difficulté à rester au second plan","Susceptibilité quand le mérite est attribué à d’autres"],"behaviors":["Signer son travail de façon reconnaissable","Prendre naturellement la parole au nom du groupe","Soigner l’entrée en matière d’une présentation","Se souvenir de qui a oublié de dire merci"],"summary":{"soft":"Le monde te voit dans la lumière, et tu la portes bien. Ton ambition a du cœur : tu veux réussir avec éclat, et faire briller ceux qui t’entourent.","cash":"Tu ne cherches pas l’attention, elle te trouve, et tu lui avais gardé une chaise. Ton ambition accepte tous les rôles, à condition que ce soit le premier.","expert":"Le Milieu du Ciel en Lion associe la vocation au rayonnement : image publique affirmée, goût de l’autorité et de la création. L’ambition recherche la reconnaissance autant que l’accomplissement."},"roastAngles":{"soft":["Ton passage laisse une trace : la salle s’en souvient longtemps après s’être vidée."],"cash":["Tu dis « je déteste me mettre en avant » depuis le centre exact de la photo.","Tu remercies toute l’équipe dans un discours où ton nom revient souvent."],"expert":["Le Milieu du Ciel en Lion fait du prestige un moteur : la réussite s’y conçoit sous le regard d’autrui."]},"roastWeight":2,"avoid":["Parler d’apparence","Annoncer la célébrité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:libra', 'fr', '1', '{"keywords":["diplomatie","élégance","médiation","partenariat","équité"],"essence":"Le Milieu du Ciel en Balance donne une image publique harmonieuse : ce qui se retient, c’est le tact, le sens de l’équité et une ambition qui se construit avec les autres.","light":["Réputation de courtoisie","Art de la médiation","Goût du travail soigné dans la forme"],"shadow":["Image trop lisse","Dépendance à l’approbation","Hésitation devant les choix qui fâchent"],"behaviors":["Chercher le consensus avant de trancher","Soigner la mise en page autant que le contenu","Servir d’intermédiaire entre deux personnes en froid","Reporter une décision qui risque de déplaire"],"summary":{"soft":"Le monde te voit comme une présence qui apaise. Ton ambition aime la justesse et l’accord : tu veux réussir sans abîmer personne en chemin.","cash":"Tout le monde t’apprécie, et c’est exactement ce qui t’empêche de trancher. Ton ambition avance en demandant poliment si elle ne dérange pas.","expert":"Le Milieu du Ciel en Balance place la vocation sous le signe du lien : image publique diplomate, esthétique, conciliante. L’ambition s’accomplit par l’alliance plutôt que par la rivalité."},"roastAngles":{"soft":["Ton avis est recherché, parce que tu sais le donner sans blesser personne."],"cash":["Tu passes une heure sur la formule de politesse et deux minutes sur le fond.","Tu arbitres un conflit de bureau qui ne te concernait pas, avec le sourire."],"expert":["Le Milieu du Ciel en Balance fait de l’entente une méthode : l’image publique y repose sur la mesure."]},"roastWeight":2,"avoid":["Parler d’apparence","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:pisces', 'fr', '1', '{"keywords":["inspiration","sensibilité","imagination","dévouement","flou"],"essence":"Le Milieu du Ciel en Poissons donne une image publique sensible et insaisissable : ce qui se perçoit, c’est l’imagination, l’empathie et une ambition qui suit l’inspiration plus que le plan.","light":["Réputation de douceur","Créativité reconnue","Capacité à sentir ce dont un public a besoin"],"shadow":["Image floue ou changeante","Objectifs difficiles à formuler","Tendance à s’effacer derrière les besoins des autres"],"behaviors":["Répondre de façon vague à la question du métier rêvé","Suivre une intuition plutôt qu’un plan établi","Accepter une tâche de plus par gentillesse","Rêver à voix haute en pleine réunion"],"summary":{"soft":"Le monde te voit comme une présence douce, un peu ailleurs. Ton ambition ne suit pas une ligne droite : elle suit ce qui t’inspire, et c’est sa vérité.","cash":"Personne ne connaît ta destination, toi non plus, et pourtant ça avance. Ton ambition n’a pas de plan, elle a une ambiance et une playlist.","expert":"Le Milieu du Ciel en Poissons associe la vocation à l’inspiration et au dévouement : image publique sensible, mouvante, difficile à cerner. L’ambition procède par intuition plus que par stratégie."},"roastAngles":{"soft":["Tu laisses derrière toi une impression plus qu’un titre, et elle fait du bien."],"cash":["Tu réponds « je me laisse porter » à toute question sur tes projets d’avenir.","Tu arrives en réunion sans notes, avec une intuition, et parfois c’est la bonne."],"expert":["Le Milieu du Ciel en Poissons dissout les contours de l’image publique : la vocation s’y devine."]},"roastWeight":2,"avoid":["Parler de sacrifice ou de vocation religieuse","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:sagittarius', 'fr', '1', '{"keywords":["vision","transmission","horizons","conviction","liberté"],"essence":"Le Milieu du Ciel en Sagittaire donne une image publique enthousiaste et ouverte : ce qui se retient, c’est la vision large, le goût de transmettre et une ambition qui vise loin.","light":["Réputation d’optimisme","Capacité à donner du sens à un projet","Curiosité pour les horizons lointains"],"shadow":["Objectifs plus grands que les moyens","Franchise qui déborde","Impatience devant les tâches de routine"],"behaviors":["Présenter une idée en parlant de sa portée mondiale","Accepter une mission pour le voyage qu’elle suppose","Donner un avis de principe dans une réunion pratique","Changer de cap quand l’horizon se rétrécit"],"summary":{"soft":"Le monde te voit comme quelqu’un qui montre le large. Ton ambition a besoin d’espace et de sens : tu veux aller loin, et emmener du monde avec toi.","cash":"Tu vises très haut, tu l’annonces, et tu regardes ensuite s’il existe une échelle. Ta réputation : de grandes idées, et un tableur que personne n’a jamais vu.","expert":"Le Milieu du Ciel en Sagittaire oriente la vocation vers la transmission et l’élargissement : image publique confiante, idéaliste, indépendante. L’ambition se nourrit de sens et de lointain."},"roastAngles":{"soft":["Les autres te suivent volontiers : tu parles de l’avenir comme d’un pays à visiter."],"cash":["Tu présentes un projet de trois pages en commençant par l’histoire de l’humanité.","Tu exposes « une vision à dix ans » et tu oublies la réunion de jeudi."],"expert":["Le Milieu du Ciel en Sagittaire donne à l’ambition une visée lointaine : le but compte plus que l’étape."]},"roastWeight":2,"avoid":["Parler de croyances précises","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:scorpio', 'fr', '1', '{"keywords":["intensité","stratégie","pouvoir","discrétion","détermination"],"essence":"Le Milieu du Ciel en Scorpion donne une image publique intense et réservée : ce qui se devine, c’est la détermination, le sens stratégique et une ambition qui ne se dévoile pas.","light":["Réputation de ténacité","Sang-froid dans les crises","Capacité à aller au fond d’un dossier"],"shadow":["Image intimidante","Goût du contrôle","Méfiance envers ceux qui approchent ses objectifs"],"behaviors":["Avancer ses projets sans en parler avant leur aboutissement","Observer une réunion entière avant de prendre la parole","Savoir qui décide vraiment dans une organisation","Recommencer à zéro plutôt que d’accepter un demi-résultat"],"summary":{"soft":"Le monde sent en toi une force calme et profonde. Ton ambition ne fait pas de bruit : elle creuse, elle transforme, et elle va jusqu’au bout.","cash":"Personne ne sait ce que tu prépares, et c’est très exactement le plan. Tu entres dans une pièce, tu ne dis rien, et trois personnes vérifient leur dossier.","expert":"Le Milieu du Ciel en Scorpion associe la vocation à la maîtrise et à la transformation : image publique magnétique, secrète, résolue. L’ambition procède par stratégie et engagement total."},"roastAngles":{"soft":["Personne ne sait tout de toi, et c’est ce qui donne envie de te faire confiance."],"cash":["Tu réponds « ça avance » à propos d’un projet dont personne ne connaît l’existence.","Tu écoutes toute la réunion en silence, puis tu poses la seule question qui fâche."],"expert":["Le Milieu du Ciel en Scorpion fait du secret un levier : l’influence s’y exerce sans démonstration."]},"roastWeight":2,"avoid":["Parler de manipulation","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:taurus', 'fr', '1', '{"keywords":["fiabilité","constance","sens du concret","patience","réputation solide"],"essence":"Le Milieu du Ciel en Taureau donne une image publique de solidité : ce qui se perçoit, c’est la constance, le goût du concret et une ambition qui prend son temps.","light":["Réputation de fiabilité","Persévérance visible sur la durée","Calme qui rassure l’entourage de travail"],"shadow":["Image d’inertie face au changement","Attachement aux méthodes éprouvées","Ambition qui s’installe dans le confortable"],"behaviors":["Rester longtemps fidèle au même projet","Refuser de bâcler pour tenir un délai","Apporter de quoi manger en réunion","Rappeler que la méthode habituelle a toujours fonctionné"],"summary":{"soft":"Aux yeux du monde, tu as la tranquillité d’un arbre : chacun sait où te trouver et peut s’y appuyer. Ton ambition pousse lentement et profondément.","cash":"Ta réputation tient en trois mots : fiable, calme, inamovible. Tu vises le sommet, mais à ton rythme et avec une pause goûter.","expert":"Le Milieu du Ciel en Taureau inscrit la vocation dans la durée et le tangible : image publique stable, ambition patiente, goût de la construction. La constance peut se figer en résistance."},"roastAngles":{"soft":["Les choses qui comptent te sont confiées, parce qu’avec toi elles restent debout."],"cash":["Tu occupes la même place en réunion depuis si longtemps qu’elle porte ton empreinte.","Ton plan d’ambition tient en une ligne : ne pas bouger jusqu’à ce que ça marche."],"expert":["Le Milieu du Ciel en Taureau fait de la permanence un titre : la réputation s’y bâtit lentement."]},"roastWeight":2,"avoid":["Parler d’argent ou de salaire","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('mc_sign:virgo', 'fr', '1', '{"keywords":["compétence","précision","service","modestie","exigence"],"essence":"Le Milieu du Ciel en Vierge donne une image publique de compétence discrète : ce qui se reconnaît, c’est la précision, l’utilité et une ambition tournée vers le travail bien fait.","light":["Réputation de sérieux","Souci du détail apprécié","Modestie dans la réussite"],"shadow":["Tendance à rester dans l’ombre de son propre travail","Exigence difficile à satisfaire","Crainte d’une erreur visible"],"behaviors":["Relire un document que personne n’a demandé de relire","Devenir la référence officieuse pour toute question pratique","Minimiser sa part dans un succès","Repérer la coquille sur la dernière diapositive"],"summary":{"soft":"Le monde te voit comme une main sûre. Ton ambition est modeste en apparence et haute en vérité : tu veux que ce que tu fais soit juste, utile, irréprochable.","cash":"Ta réputation : la personne qui a vu l’erreur avant tout le monde. Tu vises l’excellence sans que ça se remarque, et tu boudes un peu quand ça ne se remarque pas.","expert":"Le Milieu du Ciel en Vierge oriente la vocation vers le service et la maîtrise technique : image publique sobre, méthodique, fiable. L’ambition vise la compétence plus que le prestige."},"roastAngles":{"soft":["Les choses délicates finissent entre tes mains, et c’est très bien ainsi."],"cash":["Tu corriges une présentation qui n’est pas la tienne, pendant la présentation.","Tu réponds « ce n’était rien » après avoir sauvé le projet entier en une nuit."],"expert":["Le Milieu du Ciel en Vierge fonde la réputation sur l’exactitude : le mérite s’y prouve dans le détail."]},"roastWeight":2,"avoid":["Réduire à un rôle subalterne","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:aquarius', 'fr', '1', '{"keywords":["idéaux","collectif","originalité","avenir","indépendance"],"essence":"Jupiter en Verseau fait grandir par les idées et le groupe : confiance dans le progrès, l’amitié et les chemins hors norme.","light":["Ouverture d’esprit réelle face à la différence","Capacité à fédérer autour d’une idée","Générosité tournée vers le collectif"],"shadow":["Amour de l’humanité plus facile que celui du voisin","Théories séduisantes, application floue","Détachement pris pour de la hauteur"],"behaviors":["Lancer un groupe de discussion pour chaque projet","Défendre l’idée la moins populaire de la pièce","Proposer au petit-déjeuner une solution pour la société entière","Oublier de répondre à un message personnel"],"summary":{"soft":"Ta confiance regarde vers ce qui n’existe pas encore. Tu grandis parmi les autres, en défendant des idées neuves, et tu laisses à chacun la liberté de rester soi.","cash":"Tu as un plan pour sauver le monde et douze messages d’amis sans réponse. Tu aimes les gens, surtout en groupe et en théorie.","expert":"Jupiter en Verseau oriente l’expansion vers l’idéal collectif : esprit de réseau, pensée prospective, indépendance. L’excès est l’abstraction, la conviction détachée de l’affect."},"roastAngles":{"soft":["Tu fais confiance à l’avenir comme à un vieux complice qui n’est pas encore arrivé."],"cash":["Tu crées un groupe pour organiser la soirée, puis tu coupes les notifications.","Tu défends l’humanité entière mais tu laisses ton voisin en « vu » depuis mardi."],"expert":["Jupiter en Verseau généralise volontiers : l’idée du groupe y compte plus que le cas particulier."]},"roastWeight":1,"avoid":["Évoquer des opinions ou un engagement militant précis","Assimiler le détachement à de la froideur"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:aries', 'fr', '1', '{"keywords":["élan","audace","initiative","impatience","foi en soi"],"essence":"Jupiter en Bélier place la confiance dans l’initiative : la croissance passe par le premier pas, l’élan et le goût du défi.","light":["Enthousiasme qui met les autres en mouvement","Courage de commencer sans attendre de permission","Optimisme immédiat face à l’obstacle"],"shadow":["Engagements lancés plus vite qu’ils ne sont tenus","Surestimation de ses forces au démarrage","Désintérêt dès que la nouveauté retombe"],"behaviors":["Dire oui à un projet avant d’en connaître les détails","Ouvrir plusieurs chantiers la même semaine","Se porter volontaire en premier","Quitter une file d’attente au bout de deux minutes"],"summary":{"soft":"Ta confiance s’allume au départ : tu crois aux débuts comme d’autres croient aux étoiles filantes. Ton élan donne du courage à ceux qui hésitent encore.","cash":"Tu fonces d’abord, tu lis la notice après. Ta chance, c’est que ça marche souvent ; ton problème, c’est que tu comptes dessus.","expert":"Jupiter en Bélier lie l’expansion à l’initiative personnelle : la confiance naît de l’action directe. L’excès typique est la précipitation, l’engagement pris avant toute évaluation."},"roastAngles":{"soft":["Tu as la foi des commencements : chaque lundi a pour toi un goût de grand départ."],"cash":["Tu as douze projets lancés et un seul terminé : celui de les annoncer à tout le monde.","Tu lis « niveau difficile » et tu entends « fait pour moi, en mieux »."],"expert":["Jupiter en Bélier amplifie l’impulsion : la confiance précède ici l’examen, rarement l’inverse."]},"roastWeight":1,"avoid":["Réduire le placement à de l’agressivité","Présenter la chance comme acquise"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:cancer', 'fr', '1', '{"keywords":["protection","générosité","foyer","mémoire","refuge"],"essence":"Jupiter en Cancer fait grandir par le soin : la confiance s’enracine dans le foyer, les proches et le sentiment d’appartenance.","light":["Générosité protectrice envers les siens","Capacité à créer un lieu où chacun se sent accueilli","Fidélité aux souvenirs et aux liens anciens"],"shadow":["Surprotection qui étouffe un peu","Tendance à nourrir pour ne pas dire","Attachement excessif au passé"],"behaviors":["Remplir de provisions le sac de quelqu’un qui part","Garder tous les dessins, cartes et billets de train","Demander à chaque arrivant si le repas a été pris","Transformer n’importe quel logement en nid en une soirée"],"summary":{"soft":"Ta confiance a le goût d’une cuisine éclairée tard le soir. Tu grandis en prenant soin, et ceux que tu accueilles s’en souviennent longtemps.","cash":"Tu adoptes les gens comme d’autres adoptent des chats : vite, et avec des provisions. Personne ne repart de chez toi les mains vides, ni sans un conseil.","expert":"Jupiter en Cancer, signe de son exaltation, épanouit sa générosité dans le registre protecteur : croissance par l’attachement et la mémoire. L’excès prend la forme de la surprotection."},"roastAngles":{"soft":["Tu fais de la place à table avant même de savoir qui vient dîner."],"cash":["Tu demandes « tu as mangé ? » avant « bonjour », et tu n’écoutes pas la réponse.","Tu gardes une boîte de souvenirs par personne, y compris pour le facteur."],"expert":["Exalté en Cancer, Jupiter protège avec largesse ; la mesure lui manque surtout dans l’attachement."]},"roastWeight":1,"avoid":["Réduire le placement à la maternité","Supposer une famille heureuse ou présente"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:capricorn', 'fr', '1', '{"keywords":["ambition","mesure","mérite","structure","retenue"],"essence":"Jupiter en Capricorne fait croître par l’effort : confiance prudente, fondée sur le mérite, la structure et les résultats.","light":["Ambition patiente, construite étape par étape","Sens des responsabilités qui inspire le respect","Sobriété dans la réussite"],"shadow":["Optimisme tenu en laisse","Difficulté à savourer ce qui est accompli","Générosité conditionnée au mérite"],"behaviors":["Fêter une réussite en préparant déjà l’étape suivante","Lire les conditions avant de se réjouir","Dire « pas mal » pour dire « excellent »","Prévoir un plan de secours au plan de secours"],"summary":{"soft":"Ta confiance se mérite, et d’abord auprès de toi. Tu grandis en bâtissant, pierre après pierre, et ce que tu construis tient debout longtemps.","cash":"Tu fêtes une victoire en ouvrant ton agenda. Ton optimisme existe, mais il a demandé trois justificatifs et un délai de réflexion.","expert":"Jupiter en Capricorne, en chute, voit son expansion disciplinée : croissance lente, ambition structurée, confiance fondée sur la preuve. La retenue peut brider la générosité spontanée."},"roastAngles":{"soft":["Tu crois aux sommets qui se gagnent à pied, et tu connais la valeur de chaque marche."],"cash":["Tu réponds « faisons d’abord le bilan » à quelqu’un qui voulait juste trinquer.","Tu accueilles une bonne nouvelle en demandant où est le piège."],"expert":["En chute en Capricorne, Jupiter croit ce qu’il a vérifié : l’enthousiasme passe par le contrôle."]},"roastWeight":1,"avoid":["Conclure à un manque de chance","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:gemini', 'fr', '1', '{"keywords":["curiosité","dispersion","parole","apprentissage","réseaux"],"essence":"Jupiter en Gémeaux élargit par la curiosité : la confiance vient des idées, des échanges et de la variété, au risque de l’éparpillement.","light":["Facilité à apprendre un peu de tout","Art de relier des gens et des idées éloignés","Parole vive qui rend les sujets accessibles"],"shadow":["Savoir étendu mais peu approfondi","Trop de pistes ouvertes en même temps","Tendance à s’engager en parlant"],"behaviors":["Garder quarante onglets ouverts","Commencer trois livres sans en finir aucun","Répondre à une question par deux anecdotes","S’inscrire à une formation de plus"],"summary":{"soft":"Ta confiance voyage de mot en mot : tu grandis en posant des questions, en reliant les idées, en parlant avec tout le monde. Ta curiosité est une porte toujours entrouverte.","cash":"Tu sais un peu de tout sur absolument tout, surtout sur ce que tu as lu en diagonale ce matin. Finir un livre reste un projet.","expert":"Jupiter en Gémeaux, en exil, disperse l’expansion dans le multiple : curiosité vaste, synthèse difficile. La confiance repose sur l’information et l’échange plus que sur une conviction unique."},"roastAngles":{"soft":["Tu collectionnes les idées comme d’autres les coquillages : pour le plaisir d’en trouver encore."],"cash":["Tu as quarante onglets ouverts et tu jures que chacun est en cours de lecture.","Tu expliques avec aplomb un sujet découvert il y a vingt minutes dans un podcast."],"expert":["En exil en Gémeaux, Jupiter multiplie les savoirs sans toujours les hiérarchiser."]},"roastWeight":2,"avoid":["Traiter la curiosité comme de la superficialité","Confondre bavardage et manque de fond"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:leo', 'fr', '1', '{"keywords":["panache","générosité","fierté","créativité","rayonnement"],"essence":"Jupiter en Lion fait croître par l’expression de soi : confiance dans le panache, la créativité et la générosité visible.","light":["Chaleur qui encourage les autres à oser","Générosité spectaculaire et sincère","Foi dans ses propres talents"],"shadow":["Besoin d’applaudissements pour se sentir à la hauteur","Goût du grandiose là où le simple suffirait","Fierté vite froissée"],"behaviors":["Offrir le cadeau le plus voyant de la soirée","Raconter une anecdote en occupant toute la pièce","Organiser une fête là où un message aurait suffi","Vérifier discrètement qui a remarqué"],"summary":{"soft":"Ta confiance réchauffe comme un feu de cheminée : tu donnes sans compter, et tu crois au talent des autres autant qu’au tien. Ta joie est contagieuse.","cash":"Tu fais tout en grand, y compris les petits gestes. Tu offres le cadeau, le discours et l’entrée en scène, puis tu vérifies que tout le monde a bien vu.","expert":"Jupiter en Lion associe l’expansion à l’expression personnelle : magnanimité, sens du prestige, créativité affirmée. L’excès tient à l’orgueil et au besoin de reconnaissance."},"roastAngles":{"soft":["Tu donnes comme on allume les lumières : pour que tout le monde y voie plus clair."],"cash":["Tu organises un anniversaire surprise et tu fais quand même un discours sur toi.","Tu dis « c’est trois fois rien » en tendant un cadeau qui a son propre ruban doré."],"expert":["Jupiter en Lion grandit ce qu’il montre ; la générosité y cherche volontiers un public."]},"roastWeight":2,"avoid":["Assimiler le placement à de l’arrogance","Parler d’apparence"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:libra', 'fr', '1', '{"keywords":["équité","diplomatie","alliances","élégance","indécision"],"essence":"Jupiter en Balance fait grandir par la relation : confiance dans l’accord, l’équité et les alliances choisies.","light":["Talent pour réconcilier des gens en désaccord","Sens naturel de la justice et de la mesure","Générosité dans l’écoute"],"shadow":["Excès de compromis pour préserver la paix","Décisions repoussées à force de peser","Besoin d’approbation avant d’avancer"],"behaviors":["Demander l’avis de cinq personnes avant de choisir un restaurant","Dire « les deux se défendent » dans un débat","Présenter l’une à l’autre des personnes faites pour s’entendre","Arrondir les angles d’un message avant de l’envoyer"],"summary":{"soft":"Ta confiance grandit à deux : tu crois aux accords, aux mains tendues, à l’idée qu’il existe toujours un terrain commun. Avec toi, les conversations s’apaisent.","cash":"Tu donnes raison à tout le monde, puis tu rentres chez toi sans savoir ce que tu penses. Ta générosité préférée : laisser l’autre choisir le restaurant.","expert":"Jupiter en Balance développe la confiance par le lien : sens de l’équité, diplomatie, goût des alliances. L’excès réside dans la conciliation à tout prix et l’ajournement des choix."},"roastAngles":{"soft":["Tu cherches l’accord comme d’autres cherchent la lumière : par instinct, et avec grâce."],"cash":["Tu réponds « comme tu veux » avec une préférence très nette que personne ne devine.","Tu arbitres un débat entre amis et tu finis par t’excuser auprès des deux camps."],"expert":["Jupiter en Balance élargit par l’association ; l’excès de mesure y devient parfois indécision."]},"roastWeight":1,"avoid":["Parler de mariage ou de justice comme d’un conseil","Réduire le placement au charme"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:pisces', 'fr', '1', '{"keywords":["compassion","imaginaire","foi","lâcher-prise","débordement"],"essence":"Jupiter en Poissons, en domicile, élargit sans frontières : confiance dans l’intuition, la compassion et ce qui dépasse l’explication.","light":["Bonté spontanée, sans calcul","Imaginaire vaste et consolant","Capacité à faire confiance au courant"],"shadow":["Limites floues face aux demandes des autres","Fuite dans le rêve quand le réel pèse","Confiance accordée trop largement"],"behaviors":["Prêter sans noter à qui","Pleurer devant une publicité","Laisser les choses « se faire » sans fixer d’échéance","Écouter les soucis d’un inconnu dans le train"],"summary":{"soft":"Ta confiance ressemble à la mer : large, mouvante, sans bord. Tu grandis en accueillant, en imaginant, et ta douceur fait du bien à ceux qui te croisent.","cash":"Tu fais confiance à l’univers pour gérer ton agenda. Tu prêtes, tu pardonnes, tu oublies à qui, et tu recommences avec le sourire.","expert":"Jupiter en Poissons, en domicile, déploie une expansion diffuse : compassion, intuition, sens du sacré. L’excès tient à l’absence de limites et à l’idéalisation."},"roastAngles":{"soft":["Tu crois à la bonté comme on croit à la marée : elle revient toujours."],"cash":["Tu as prêté ton chargeur, ton pull et ton après-midi à quelqu’un croisé la veille.","Tu réponds « ça se fait tout seul » à une échéance qui ne se fait jamais toute seule."],"expert":["En domicile en Poissons, Jupiter donne sans mesure ; la confiance y précède tout discernement."]},"roastWeight":2,"avoid":["Parler de spiritualité comme d’une croyance précise","Associer le placement à des dépendances"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:sagittarius', 'fr', '1', '{"keywords":["horizon","optimisme","quête de sens","voyages","franchise"],"essence":"Jupiter en Sagittaire, en domicile, donne toute son ampleur : confiance dans le sens, l’horizon et la liberté d’aller voir ailleurs.","light":["Optimisme robuste et communicatif","Soif de comprendre le monde en grand","Franchise qui ouvre les débats"],"shadow":["Certitude d’avoir raison","Engagements plus vastes que l’agenda","Leçons données sans avoir été demandées"],"behaviors":["Réserver un billet sur un coup de tête","Transformer une discussion en conférence","Répondre que tout finit par s’arranger, sans plan précis","Arriver en retard avec une excellente histoire"],"summary":{"soft":"Ta confiance regarde loin. Tu crois qu’il y a toujours un ailleurs, un sens, une route de plus, et ton optimisme donne envie de te suivre.","cash":"Tu as un avis sur tout et un billet pour ailleurs. Ton plan, c’est « j’improvise », et le pire, c’est que ça suffit souvent.","expert":"Jupiter en Sagittaire, en domicile, exprime pleinement sa nature : foi, vision large, goût de l’enseignement et du lointain. L’excès est celui de la démesure et du dogmatisme."},"roastAngles":{"soft":["Tu portes l’horizon en toi : même un mardi ordinaire te semble mener quelque part."],"cash":["Tu donnes un cours magistral sur un pays où tu as passé une escale de trois heures.","Tu arrives en retard, sans excuse, mais avec une théorie sur le sens de la vie."],"expert":["En domicile, Jupiter voit large et juge vite : la conviction devance volontiers la vérification."]},"roastWeight":2,"avoid":["Parler de croyances précises","Annoncer des voyages"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:scorpio', 'fr', '1', '{"keywords":["intensité","profondeur","flair","transformation","secret"],"essence":"Jupiter en Scorpion fait croître par la profondeur : confiance dans l’intensité, le flair et la capacité à traverser les crises.","light":["Flair pour ce qui se cache derrière les apparences","Ressources décuplées dans les moments difficiles","Engagement entier dans ce qui compte"],"shadow":["Goût du tout ou rien","Soupçon poussé trop loin","Tendance à vouloir tout savoir sans rien livrer"],"behaviors":["Mener l’enquête avant un premier café avec quelqu’un","Poser la question qui fait taire la table","Se donner sans réserve à un projet, ou pas du tout","Garder sous clé les confidences des autres"],"summary":{"soft":"Ta confiance descend là où d’autres n’osent pas regarder. Tu grandis dans l’intensité, et tu sais trouver des ressources au fond des moments sombres.","cash":"Tu ne fais rien à moitié, surtout pas les recherches sur les gens. Tu sais tout de tout le monde et personne ne connaît ton plat préféré.","expert":"Jupiter en Scorpion porte l’expansion vers l’intensité et l’enquête : ressources de crise, flair psychologique. L’excès se manifeste dans le soupçon et le goût de l’emprise."},"roastAngles":{"soft":["Tu fais confiance à ce qui est vrai, même quand le vrai demande du courage."],"cash":["Tu connais le parcours complet de quelqu’un avant même d’avoir entendu son prénom.","Tu dis « je demande juste par curiosité » avec le regard d’un interrogatoire."],"expert":["Jupiter en Scorpion amplifie le désir de sonder ; la confiance s’y gagne par l’épreuve."]},"roastWeight":1,"avoid":["Évoquer la sexualité ou les héritages","Dramatiser en parlant de destin sombre"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:taurus', 'fr', '1', '{"keywords":["abondance","patience","plaisirs","sécurité","constance"],"essence":"Jupiter en Taureau fait croître par accumulation lente : confiance dans le tangible, le durable et le plaisir des sens.","light":["Générosité concrète, qui nourrit et accueille","Patience pour laisser les choses mûrir","Sens sûr de la qualité"],"shadow":["Excès de confort qui endort l’envie d’évoluer","Tendance à accumuler au-delà du nécessaire","Entêtement présenté comme de la sagesse"],"behaviors":["Reprendre du dessert par principe","Choisir l’objet le plus solide du rayon, quitte à attendre","Garder le même café, la même table, la même commande","Recevoir avec trop de plats pour le nombre d’invités"],"summary":{"soft":"Ta confiance pousse lentement, comme un verger : tu crois à ce qui se touche, se goûte et dure. Autour de toi, il y a toujours de quoi se sentir accueilli et rassasié.","cash":"Tu appelles ça « profiter de la vie » ; ton canapé appelle ça une relation exclusive. La générosité, chez toi, se sert à la louche.","expert":"Jupiter en Taureau oriente l’expansion vers la matière et la durée : croissance progressive, goût de la stabilité. L’excès se loge dans l’accumulation et la résistance au changement."},"roastAngles":{"soft":["Tu fais confiance au temps long : chez toi, même la joie prend le temps de mijoter."],"cash":["Tu as cuisiné pour douze, il y a quatre invités, et tu demandes encore si ça suffit.","Ton optimisme est simple : rien de grave ne peut arriver tant qu’il reste du fromage."],"expert":["Jupiter en Taureau consolide plutôt qu’il n’étend : la confiance se mesure à ce qui tient dans la durée."]},"roastWeight":1,"avoid":["Parler d’argent comme d’un conseil ou d’une promesse d’enrichissement","Réduire le placement à la gourmandise"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:jupiter:virgo', 'fr', '1', '{"keywords":["précision","service","méthode","détail","perfectionnisme"],"essence":"Jupiter en Vierge cherche la croissance dans le travail bien fait : confiance dans la méthode, l’utilité et l’amélioration continue.","light":["Générosité qui passe par l’aide pratique","Sens du détail qui rend les grands projets réalisables","Humilité face à ce qui reste à apprendre"],"shadow":["Vision d’ensemble noyée sous les détails","Critique abondante, y compris envers soi","Difficulté à juger un travail terminé"],"behaviors":["Refaire une liste pour mieux classer la précédente","Corriger une faute dans un message déjà envoyé","Proposer un tableau pour organiser les vacances","Rendre service avant toute demande"],"summary":{"soft":"Ta confiance se construit geste après geste. Tu grandis en rendant les choses plus justes, plus utiles, et ton aide discrète change vraiment la journée des autres.","cash":"Tu vois grand, mais d’abord tu corriges la virgule. Ton optimisme existe : il est rangé par ordre alphabétique, avec une marge d’erreur.","expert":"Jupiter en Vierge, en exil, voit son ampleur contrainte par l’analyse : expansion par le perfectionnement et le service. Le risque est de multiplier les détails au détriment de la vision."},"roastAngles":{"soft":["Tu crois aux petites améliorations comme d’autres aux grands miracles, et tu as souvent raison."],"cash":["Tu as fait un tableau pour choisir quel tableau utiliser.","Tu rends service si bien que les gens n’osent plus te dire que c’était déjà fait."],"expert":["En exil en Vierge, Jupiter mesure avant de croire : la confiance exige des preuves détaillées."]},"roastWeight":2,"avoid":["Présenter le placement comme un manque de chance","Aborder l’hygiène de vie ou le corps"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:aquarius', 'fr', '1', '{"keywords":["indépendance","action collective","esprit rebelle","obstination","inventivité"],"essence":"Mars en Verseau agit à sa manière et pour une idée : l’énergie est indépendante, inventive et tenace, se mobilise volontiers pour un groupe et se cabre devant tout ordre imposé.","light":["Inventivité dans la manière de faire","Capacité à fédérer autour d’un projet commun","Sang-froid et recul dans le conflit"],"shadow":["Refus de principe devant l’autorité","Obstination à faire autrement","Colère froide, exprimée par la distance"],"behaviors":["Faire exactement l’inverse de ce qui vient d’être ordonné","Inventer une méthode personnelle pour une tâche simple","Se mobiliser pour une cause collective plus que pour soi","Répondre à un conflit en cessant de répondre"],"summary":{"soft":"Tu agis à ta façon, hors des sentiers tracés, et souvent pour quelque chose de plus grand que toi. Ton élan ouvre des chemins nouveaux.","cash":"Il suffit de te dire « il faut » pour que tu fasses le contraire. Tu aurais fait la chose avec plaisir si personne ne l’avait demandée.","expert":"Mars en Verseau, signe d’air fixe, donne un élan indépendant et tenace : vous agissez par principe et pour le collectif, et résistez à toute injonction."},"roastAngles":{"soft":["Tu ne suis pas le chemin, tu en dessines un autre, et quelques curieux te suivent."],"cash":["Tu lis « ne pas ouvrir » sur une porte et ta main est déjà sur la poignée.","Tu te mets en colère en devenant soudain très calme et très injoignable."],"expert":["Élan fixe d’air : vous obéissez volontiers à une idée, jamais à une consigne."]},"roastWeight":2,"avoid":["Présenter l’indépendance comme de l’asociabilité","Réduire ce placement à la provocation"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:aries', 'fr', '1', '{"keywords":["impulsion","courage","initiative","colère éclair","goût du défi"],"essence":"Mars en Bélier est en domicile : l’action est immédiate, directe et courageuse, la colère éclate vite et retombe aussitôt, et l’élan faiblit quand il faut durer.","light":["Courage et capacité à se lancer en premier","Franchise dans l’affrontement","Énergie de démarrage hors du commun"],"shadow":["Impulsivité, décisions prises sous le coup du moment","Colère vive pour un obstacle mineur","Projets abandonnés une fois l’élan passé"],"behaviors":["Démarrer avant la fin des consignes","S’emporter en dix secondes et avoir tout oublié en dix minutes","Transformer une file d’attente en épreuve personnelle","Lancer cinq projets et en finir un"],"summary":{"soft":"Tu as le courage des commencements : tu fonces, tu ouvres la voie, tu oses. Ta colère passe comme un orage d’été, vite et sans rancune.","cash":"Tu fonces d’abord, tu lis les consignes après. Ta colère dure moins longtemps qu’une publicité, mais tout l’étage l’a entendue.","expert":"Mars en Bélier occupe son domicile de feu cardinal : l’impulsion y est pure et immédiate ; vous agissez par initiative, avec une combativité franche et peu d’endurance."},"roastAngles":{"soft":["Ton énergie craque comme une allumette : elle éclaire tout, tout de suite."],"cash":["Tu claques la porte, puis tu reviens deux minutes après demander ce qu’on mange.","Tu doubles tout le monde dans l’escalator sans aucun retard à rattraper, par principe."],"expert":["Mars en domicile : vous excellez à ouvrir les hostilités, moins à tenir le siège."]},"roastWeight":3,"avoid":["Réduire ce placement à de la violence","Présenter l’impulsivité comme de l’immaturité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:cancer', 'fr', '1', '{"keywords":["action indirecte","instinct protecteur","humeur changeante","colère rentrée","ténacité défensive"],"essence":"Mars en Cancer est en chute : l’action suit l’humeur et procède par détours, l’énergie se mobilise pour défendre les proches, et la colère se retient avant de déborder.","light":["Courage pour protéger les proches","Ténacité quand l’attachement est en jeu","Intuition du bon moment pour agir"],"shadow":["Colère exprimée par la bouderie ou le silence","Énergie dépendante de l’humeur du jour","Tendance à ressortir d’anciens griefs"],"behaviors":["Claquer les portes de placard au lieu de dire ce qui ne va pas","Défendre un proche avec plus d’ardeur que soi-même","Contourner l’obstacle plutôt que l’affronter","Cuisiner ou ranger avec fracas pour évacuer une contrariété"],"summary":{"soft":"Ta force se réveille pour ceux que tu aimes. Tu avances à ta manière, de côté parfois, mais tu ne lâches jamais ce qui compte pour toi.","cash":"Tu ne te fâches pas, tu fais la vaisselle très fort. Et si on touche à tes proches, là, tout le quartier est au courant.","expert":"Mars en Cancer est en chute, en eau cardinale : l’élan y dépend de l’humeur et s’exprime de biais ; vous agissez pour protéger et contenez longtemps la colère."},"roastAngles":{"soft":["Ton courage a une adresse : il habite là où vivent ceux que tu aimes."],"cash":["Tu dis « je ne suis pas en colère » en rangeant les casseroles avec fracas.","Tu ressors une dispute de l’an dernier au milieu d’une dispute sur autre chose."],"expert":["Mars en chute : vous attaquez rarement de front, mais vous défendez un territoire jusqu’au bout."]},"roastWeight":3,"avoid":["Présenter la chute comme de la faiblesse","Réduire ce placement à la passivité agressive"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:capricorn', 'fr', '1', '{"keywords":["ambition","discipline","endurance","maîtrise","stratégie de long terme"],"essence":"Mars en Capricorne est en exaltation : l’action est disciplinée, patiente et orientée vers un but, l’effort se dose sur la durée, et la colère reste froide, contenue et utile.","light":["Discipline et sens de l’effort durable","Efficacité sous la contrainte","Ambition structurée, tournée vers le résultat"],"shadow":["Dureté envers soi et envers les autres","Difficulté à se reposer sans culpabilité","Froideur dans le conflit"],"behaviors":["Se fixer un objectif à cinq ans et s’y tenir","Travailler pendant les vacances « juste pour avancer »","Exprimer la colère par un silence et un courriel très bien rédigé","Transformer un loisir en programme d’entraînement"],"summary":{"soft":"Tu gravis les choses pas à pas, avec une patience de montagne. Ta force est calme et sûre : elle arrive là où elle l’avait annoncé.","cash":"Tu te détends avec un objectif et un chronomètre. Ta colère ne crie pas : elle envoie un courriel à huit heures précises, avec copie.","expert":"Mars en Capricorne est en exaltation, en terre cardinale : l’élan y est maîtrisé et stratégique ; vous agissez avec méthode, endurance et un sens aigu de l’objectif."},"roastAngles":{"soft":["Ton énergie ne s’éparpille pas : elle monte, marche après marche, jusqu’au sommet."],"cash":["Tu prends un jour de congé et tu en profites pour ranger toute la cave.","Tu annonces une pause détente, avec un planning de la détente heure par heure."],"expert":["Mars exalté : vous repoussez la satisfaction avec une constance qui tient de la stratégie."]},"roastWeight":3,"avoid":["Réduire ce placement à de la froideur","Présenter l’ambition comme de l’arrivisme"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:gemini', 'fr', '1', '{"keywords":["énergie dispersée","joute verbale","vivacité","agitation","polyvalence"],"essence":"Mars en Gémeaux agit par la parole et le mouvement : l’énergie est nerveuse, vive et dispersée, le combat se mène avec des mots, et l’ennui est le premier adversaire.","light":["Réactivité et rapidité d’exécution","Habileté dans le débat et la négociation","Capacité à mener plusieurs tâches de front"],"shadow":["Dispersion de l’énergie entre trop de projets","Sarcasme en guise de colère","Difficulté à tenir un effort monotone"],"behaviors":["Se disputer par messages interminables","Changer de tâche toutes les dix minutes","Gagner une dispute grâce à une formule bien placée","Tapoter du pied ou du stylo en réunion"],"summary":{"soft":"Ton énergie est vive comme un oiseau : tu passes d’une chose à l’autre avec adresse, et tes mots sont ton meilleur outil.","cash":"Tu fais six choses à la fois, dont quatre restent en plan. Quand tu t’énerves, ce n’est pas un cri, c’est un exposé avec arguments.","expert":"Mars en Gémeaux, signe d’air mutable, porte l’action vers le verbe et la mobilité : vous combattez par l’argument et dispersez volontiers l’effort sur plusieurs fronts."},"roastAngles":{"soft":["Tes mains et tes idées courent ensemble, et rarement dans la même direction."],"cash":["Tu envoies un pavé de colère, puis tu corriges une faute dans le message suivant.","Tu commences le ménage, tu retrouves une vieille photo, et le ménage est fini."],"expert":["Élan mutable d’air : vous gagnez la querelle par la formule et perdez le fil du chantier."]},"roastWeight":2,"avoid":["Réduire ce placement à de l’inconstance","Présenter la joute verbale comme de la méchanceté"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:leo', 'fr', '1', '{"keywords":["panache","fierté","volonté","goût de diriger","colère théâtrale"],"essence":"Mars en Lion agit avec panache et volonté : l’énergie est constante, fière et créative, le besoin de diriger est net, et la colère surgit dès que l’amour-propre est touché.","light":["Volonté ferme et confiance dans l’action","Capacité à entraîner les autres","Générosité dans l’effort"],"shadow":["Orgueil blessé par la moindre critique","Tendance à commander plutôt qu’à demander","Difficulté à agir sans reconnaissance"],"behaviors":["Prendre la tête d’un groupe sans que personne l’ait proposé","Travailler deux fois mieux devant un public","Quitter une pièce sur une réplique de fin","Refuser de l’aide par fierté"],"summary":{"soft":"Tu agis avec le cœur et tu donnes du courage aux autres. Quand tu t’engages, c’est en entier, avec une chaleur qui entraîne.","cash":"Tu ne t’énerves pas, tu fais une scène, avec sortie de pièce et dernière réplique. Tu acceptes la critique, à condition que ce soit un compliment.","expert":"Mars en Lion, signe de feu fixe, donne un élan soutenu et orgueilleux : vous agissez pour créer et diriger, et l’atteinte à l’amour-propre déclenche la colère."},"roastAngles":{"soft":["Ton énergie réchauffe la pièce : rien qu’à te voir démarrer, on a envie de suivre."],"cash":["Tu demandes « qui a fait ça ? » seulement quand la réponse attendue est « toi, bravo ».","Tu quittes une dispute en te retournant sur le seuil pour la phrase finale."],"expert":["Élan fixe de feu : vous pardonnez la contradiction, rarement le manque d’égards."]},"roastWeight":3,"avoid":["Réduire ce placement à de l’arrogance","Présenter le besoin de reconnaissance comme de la vanité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:libra', 'fr', '1', '{"keywords":["action concertée","sens de la justice","hésitation","colère polie","stratégie"],"essence":"Mars en Balance est en exil : l’action passe par l’autre et par la négociation, la décision tarde à force de peser, et la colère, contenue par politesse, s’allume surtout devant l’injustice.","light":["Sens de l’équité dans le conflit","Talent pour négocier et rallier","Combativité au service d’une cause juste"],"shadow":["Hésitation au moment d’agir","Colère détournée en remarques feutrées","Besoin de l’accord d’autrui pour se lancer"],"behaviors":["Attendre que l’autre décide, puis contester la décision","Se fâcher sans quitter une courtoisie parfaite","Défendre quelqu’un d’autre plus facilement que soi","Rédiger un message de reproche et l’adoucir cinq fois avant l’envoi"],"summary":{"soft":"Ta force est celle de l’accord : tu agis mieux à deux, tu cherches ce qui est juste, et tu sais te battre sans blesser.","cash":"Tu t’énerves avec des formules de politesse. Tu veux bien décider, mais seulement après avoir demandé son avis à toute la tablée.","expert":"Mars en Balance est en exil, en air cardinal : l’élan s’y soumet à la délibération et au regard d’autrui ; vous agissez par alliance et combattez surtout l’injustice."},"roastAngles":{"soft":["Tu te bats avec des gants de velours, et c’est souvent toi qui ramènes la paix."],"cash":["Tu écris « pas de souci » en tapant sur les touches comme sur un adversaire.","Tu te mets en colère pour défendre un inconnu, jamais pour ta propre part de gâteau."],"expert":["Mars en exil : vous partez en guerre avec courtoisie, après consultation des parties."]},"roastWeight":2,"avoid":["Présenter l’exil comme une absence de combativité","Réduire ce placement à l’indécision"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:pisces', 'fr', '1', '{"keywords":["action intuitive","énergie fluctuante","dévouement","évitement du conflit","inspiration"],"essence":"Mars en Poissons agit par inspiration et par vagues : l’énergie fluctue avec l’ambiance, se donne pour autrui ou pour un rêve, et la colère se dissout, se détourne ou s’évapore.","light":["Dévouement dans l’action pour autrui","Souplesse, art de contourner l’obstacle","Élan créatif et intuitif"],"shadow":["Difficulté à affronter directement","Énergie irrégulière, démarrages remis à plus tard","Tendance à s’esquiver plutôt qu’à dire non"],"behaviors":["Éviter une confrontation en disparaissant de la conversation","Travailler par élans, tard le soir, quand l’inspiration vient","Aider tout le monde et oublier sa propre liste","Dire oui pour avoir la paix, puis ne pas venir"],"summary":{"soft":"Ton énergie suit les marées : elle vient par vagues, portée par l’inspiration et par le cœur. Tu agis mieux quand tu crois à ce que tu fais.","cash":"Tu évites le conflit avec un talent de contorsionniste. Tu as dit oui pour avoir la paix, et maintenant tu cherches comment ne pas y aller.","expert":"Mars en Poissons, signe d’eau mutable, donne un élan diffus et intuitif : vous agissez par inspiration et par dévouement, et esquivez l’affrontement direct."},"roastAngles":{"soft":["Ta force ne cogne pas, elle contourne : comme l’eau, elle finit par passer."],"cash":["Tu répètes ta colère sous la douche, puis en vrai tu dis « non, laisse, c’est moi ».","Tu repousses une tâche au lendemain avec une constance digne d’un athlète."],"expert":["Élan mutable d’eau : votre colère se retire comme la marée, sans avoir rien renversé."]},"roastWeight":2,"avoid":["Présenter ce placement comme faible ou passif","Réduire l’esquive à de la lâcheté"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:sagittarius', 'fr', '1', '{"keywords":["élan","goût de l’aventure","conviction","excès d’enthousiasme","besoin d’espace"],"essence":"Mars en Sagittaire agit par enthousiasme et par conviction : l’énergie vise loin, aime le risque et le grand air, se bat pour ses idées et se disperse dès que la routine s’installe.","light":["Enthousiasme qui met en mouvement","Courage de ses opinions","Goût de l’effort en plein air et du dépassement"],"shadow":["Engagements plus grands que le temps disponible","Colère en forme de sermon","Abandon des projets une fois la nouveauté passée"],"behaviors":["Dire oui à trois projets le même soir","Partir en randonnée sans vérifier la météo","S’emporter pour une question de principe","Réserver un billet sur un coup de tête"],"summary":{"soft":"Ton énergie regarde l’horizon : tu te lances avec foi, tu entraînes les autres, et tu crois assez fort pour deux.","cash":"Tu vises très loin avec un plan qui tient sur un coin de nappe. Quand tu t’énerves, ça finit en conférence sur les grands principes.","expert":"Mars en Sagittaire, signe de feu mutable, met l’élan au service d’un idéal : vous agissez par conviction, avec ampleur et optimisme, et supportez mal la contrainte."},"roastAngles":{"soft":["Tu cours vers l’horizon avec une telle joie que personne ne pense à demander la destination."],"cash":["Tu t’inscris à un marathon un soir d’enthousiasme, sans posséder de baskets.","Tu acceptes d’aider à trois déménagements le même samedi, et tu y crois."],"expert":["Élan mutable de feu : vous engagez la bataille pour le principe et laissez l’intendance à d’autres."]},"roastWeight":2,"avoid":["Réduire ce placement à de l’irresponsabilité","Présenter l’optimisme comme de la naïveté"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:scorpio', 'fr', '1', '{"keywords":["détermination","stratégie","endurance","rancune","maîtrise de soi"],"essence":"Mars en Scorpion est en domicile : l’action est concentrée, stratégique et tenace, la volonté ne lâche pas son objectif, et la colère, froide et silencieuse, n’oublie rien.","light":["Détermination sans faille","Sang-froid dans les situations de crise","Capacité à aller au fond d’un problème"],"shadow":["Rancune durable","Goût du contrôle et du rapport de force","Tendance à agir en secret"],"behaviors":["Se taire pendant une dispute et tout retenir","Préparer sa réponse pendant des semaines","Poursuivre un objectif sans en parler à personne","Couper les ponts du jour au lendemain, sans scène"],"summary":{"soft":"Ta volonté est profonde et silencieuse : quand tu veux quelque chose, tu y mets tout, et tu traverses les tempêtes sans lâcher.","cash":"Tu ne te mets pas en colère, tu prends des notes. Tu pardonnes volontiers, à une date que tu n’as pas encore communiquée.","expert":"Mars en Scorpion occupe son domicile d’eau fixe : l’élan y est concentré, stratégique et endurant ; vous agissez à couvert et gardez durablement la mémoire des offenses."},"roastAngles":{"soft":["Ta force avance sous la surface, comme un courant : invisible, et pourtant elle porte loin."],"cash":["Tu dis « c’est oublié », puis tu rejoues la scène entière, réplique par réplique.","Tu perds une partie de cartes en famille et tu prépares la revanche pendant un an."],"expert":["Mars en domicile : vous ne répondez pas à l’offense, vous la versez au dossier."]},"roastWeight":3,"avoid":["Présenter ce placement comme vengeur ou dangereux","Insister sur une dimension charnelle"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:taurus', 'fr', '1', '{"keywords":["endurance","lenteur à démarrer","ténacité","colère rare et massive","force tranquille"],"essence":"Mars en Taureau est en exil : l’action démarre lentement mais ne s’arrête plus, l’effort est régulier et obstiné, et la colère, longue à venir, est difficile à apaiser.","light":["Endurance et constance dans l’effort","Calme sous la pression","Capacité à finir ce qui est commencé"],"shadow":["Inertie devant ce qui doit changer vite","Obstination face à un obstacle","Rancune tenace après une colère"],"behaviors":["Repousser le démarrage, puis travailler sans s’arrêter","Rester de marbre pendant des mois, puis exploser une fois","Refuser toute bousculade dans son rythme","Finir une tâche pénible par pur entêtement"],"summary":{"soft":"Tu avances à ton pas, sans te laisser distraire, et tu arrives au bout. Ta force est celle des choses qui durent et que rien ne presse.","cash":"Il faut une grue pour te faire démarrer et un mur pour t’arrêter. Ta colère arrive une fois par an, et on s’en souvient jusqu’à la suivante.","expert":"Mars en Taureau est en exil, en terre fixe : l’élan y est lent, mais d’une endurance remarquable ; vous agissez par persévérance et cédez rarement une fois en marche."},"roastAngles":{"soft":["Ta force ressemble à celle des rivières : tranquille, et rien ne la détourne."],"cash":["Tu dis « j’arrive » depuis le canapé, et le canapé n’a rien remarqué.","Tu restes calme pendant six mois, puis tu ressors la liste complète un mardi."],"expert":["Mars en exil : vous mettez du temps à vous fâcher, et davantage encore à décolérer."]},"roastWeight":2,"avoid":["Confondre lenteur et paresse","Présenter l’exil comme un manque de volonté"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mars:virgo', 'fr', '1', '{"keywords":["efficacité","précision du geste","sens du travail","agacement","perfectionnisme"],"essence":"Mars en Vierge agit avec méthode et précision : l’énergie se dépense dans le travail bien fait, l’efficacité passe avant l’éclat, et la colère prend la forme de l’agacement et de la critique.","light":["Efficacité et sens de l’organisation","Habileté technique, soin du geste","Endurance dans les tâches minutieuses"],"shadow":["Irritabilité devant le désordre et l’à-peu-près","Critique tatillonne sous l’effet de l’énervement","Surmenage par incapacité à déléguer"],"behaviors":["Refaire discrètement ce qu’un autre vient de faire","Nettoyer ou trier pour calmer une contrariété","Soupirer devant un lave-vaisselle mal rangé","Établir un plan détaillé avant le moindre geste"],"summary":{"soft":"Tu agis avec soin et précision, comme on répare une montre. Ton énergie se met au service des choses bien faites, et l’on peut compter sur toi.","cash":"Tu ne cries pas, tu soupires, puis tu refais le travail des autres en silence. Ta colère a un tableau de suivi.","expert":"Mars en Vierge, signe de terre mutable, canalise l’élan vers la tâche et la méthode : vous agissez avec précision et exprimez la colère par la critique du détail."},"roastAngles":{"soft":["Ton énergie a des mains d’artisan : elle ne brille pas, elle fait les choses bien."],"cash":["Tu réorganises le lave-vaisselle des autres en retenant un commentaire.","Tu dis « laisse, je m’en occupe » avec un soupir qui vaut un long discours."],"expert":["Élan mutable de terre : votre colère s’énonce en liste de points à corriger."]},"roastWeight":2,"avoid":["Réduire ce placement à la maniaquerie","Présenter le goût du travail comme de la soumission"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:aquarius', 'fr', '1', '{"keywords":["originalité","pensée abstraite","indépendance d’esprit","esprit de contradiction","idées en avance"],"essence":"Mercure en Verseau pense de façon indépendante et abstraite : l’esprit observe de loin, relie les idées en système, aime le contre-pied et tient fermement à ses théories.","light":["Originalité des idées et des solutions","Objectivité, recul sur les situations","Aisance avec les concepts et les systèmes"],"shadow":["Esprit de contradiction par principe","Détachement perçu comme de la distance","Attachement rigide à une théorie personnelle"],"behaviors":["Défendre l’avis contraire pour tester la solidité du raisonnement","Expliquer un chagrin par un schéma","Envoyer un article de fond à minuit sans un mot d’accompagnement","Répondre à une question personnelle par une généralité sur l’humanité"],"summary":{"soft":"Ton esprit regarde les choses d’un peu plus haut. Tu penses autrement, et c’est souvent toi qui ouvres la porte que personne n’avait vue.","cash":"Dès que tout le monde est d’accord, tu changes de camp. Tu appelles ça l’esprit critique, les autres appellent ça un dîner compliqué.","expert":"Mercure en Verseau, signe d’air fixe, favorise l’abstraction et la pensée en système : vous raisonnez avec recul, innovez volontiers et tenez ferme sur vos principes."},"roastAngles":{"soft":["Tes idées arrivent d’ailleurs, avec un léger décalage horaire sur le reste du monde."],"cash":["Tu réponds « tout dépend de la définition » à quelqu’un qui demandait l’heure.","Tu contredis une idée, puis tu la défends dès que l’autre a changé d’avis."],"expert":["Pensée fixe d’air : vous changez volontiers le monde en théorie, plus rarement d’opinion."]},"roastWeight":2,"avoid":["Présenter le détachement comme une absence d’émotion","Réduire l’originalité à de l’excentricité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:aries', 'fr', '1', '{"keywords":["franc-parler","vivacité","impatience mentale","répartie","décision rapide"],"essence":"Mercure en Bélier donne une pensée rapide, directe et combative : l’idée part avant d’être polie, et la parole sert à trancher plutôt qu’à nuancer.","light":["Franchise qui évite les malentendus","Capacité à décider vite et à lancer une idée","Répartie immédiate dans le débat"],"shadow":["Tendance à couper la parole","Avis tranché avant d’avoir tout entendu","Lassitude rapide devant les explications longues"],"behaviors":["Répondre à un message avant de l’avoir lu jusqu’au bout","Finir les phrases des autres pour gagner du temps","Dire d’abord ce qui est pensé, arrondir les angles ensuite","Apprendre en essayant plutôt qu’en lisant le mode d’emploi"],"summary":{"soft":"Ta pensée file comme une étincelle : tu dis les choses en face, sans détour, et cette franchise fait souvent gagner du temps à tout le monde.","cash":"Tu penses vite, tu parles encore plus vite. La nuance arrive après, en général par message d’excuse.","expert":"Mercure en Bélier, signe de feu cardinal, privilégie l’intuition immédiate et le verbe offensif ; vous tranchez d’abord, vous argumentez ensuite."},"roastAngles":{"soft":["Tes mots partent comme des flèches, mais c’est toujours la sincérité qui les lance."],"cash":["Tu réponds « oui mais » avant la fin de la phrase de l’autre.","Tu lis la notice une fois le meuble monté, et monté de travers."],"expert":["Pensée cardinale de feu : vous concluez avant la démonstration, puis vous défendez la conclusion."]},"roastWeight":2,"avoid":["Réduire ce placement à de l’agressivité","Confondre rapidité d’esprit et manque de profondeur"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:cancer', 'fr', '1', '{"keywords":["mémoire affective","pensée intuitive","écoute","subjectivité","pudeur verbale"],"essence":"Mercure en Cancer pense avec la mémoire et le ressenti : les informations se retiennent par l’émotion qui les accompagne, et la parole cherche d’abord à protéger le lien.","light":["Mémoire remarquable des détails personnels","Écoute attentive, qui met en confiance","Sens des mots qui réconfortent"],"shadow":["Tendance à prendre une remarque neutre pour un reproche","Difficulté à dire les choses directement","Ressassement des conversations passées"],"behaviors":["Se souvenir mot pour mot d’une phrase entendue des années plus tôt","Relire une ancienne conversation tard le soir","Répondre « peu importe » en espérant que l’autre devine","Garder les lettres, les cartes et les captures d’écran qui comptent"],"summary":{"soft":"Tu penses avec le cœur et tu retiens tout ce qui t’a touché. Tes mots savent envelopper, parce que tu écoutes avant de parler.","cash":"Tu te souviens d’une phrase lâchée un mardi d’il y a six ans, intonation comprise. Et non, ce n’était « pas grave ».","expert":"Mercure en Cancer, signe d’eau cardinal, lie la pensée à la mémoire affective : vous retenez ce qui vous a touché et vous formulez avec prudence, par égard pour le lien."},"roastAngles":{"soft":["Ta mémoire est un album : chaque phrase y garde la couleur du moment où tu l’as entendue."],"cash":["Tu réponds « non mais c’est bon », et on sent bien que ce n’est pas bon du tout.","Tu cites une remarque d’il y a huit ans avec la date, la météo et le pull de l’autre."],"expert":["Pensée d’eau cardinale : chez vous, un fait sans charge affective s’oublie, un mot blessant s’archive."]},"roastWeight":2,"avoid":["Présenter la sensibilité comme un manque de logique","Caricaturer en susceptibilité permanente"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:capricorn', 'fr', '1', '{"keywords":["pensée structurée","sobriété","sens pratique","humour pince-sans-rire","sérieux"],"essence":"Mercure en Capricorne pense avec méthode et économie : l’esprit organise, hiérarchise et vise le résultat, la parole est sobre et pèse chaque mot avant de l’engager.","light":["Esprit de synthèse orienté vers le résultat","Parole fiable, qui engage","Humour sec et efficace"],"shadow":["Sécheresse dans la formulation","Pessimisme présenté comme du réalisme","Peu de place laissée à la fantaisie"],"behaviors":["Répondre par un seul mot, ponctuation comprise","Rédiger un message personnel comme une note de service","Préparer un plan en trois parties pour une discussion de couple","Demander « concrètement, que faire ? » au milieu d’un débat d’idées"],"summary":{"soft":"Tu parles peu, mais chaque mot compte. Ton esprit construit patiemment, et l’on peut s’appuyer sur ce que tu dis.","cash":"Tu réponds « ok. » avec le point, et tu trouves ça chaleureux. Ton message d’anniversaire ressemble à un compte rendu.","expert":"Mercure en Capricorne, signe de terre cardinal, structure la pensée vers l’efficacité : vous hiérarchisez, synthétisez et parlez avec une économie de moyens assumée."},"roastAngles":{"soft":["Tes phrases sont courtes comme des marches : avec toi, on monte toujours quelque part."],"cash":["Tu envoies « bien reçu » à quelqu’un qui vient de t’ouvrir son cœur.","Tu fais un tableau comparatif pour choisir un film du dimanche soir."],"expert":["Pensée cardinale de terre : vous jugez une idée à ce qu’elle permet de faire avant la fin du trimestre."]},"roastWeight":2,"avoid":["Présenter la sobriété comme de la froideur affective","Oublier l’humour propre à ce placement"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:gemini', 'fr', '1', '{"keywords":["curiosité","agilité verbale","polyvalence","dispersion","humour"],"essence":"Mercure en Gémeaux est dans son domicile : la pensée est vive, mobile et curieuse de tout, la parole abondante, et l’intérêt saute d’un sujet à l’autre avec aisance.","light":["Aisance à expliquer, reformuler et vulgariser","Curiosité qui relie des sujets éloignés","Humour et sens de la formule"],"shadow":["Dispersion entre trop de centres d’intérêt","Difficulté à approfondir un sujet jusqu’au bout","Avis changeant selon le dernier argument entendu"],"behaviors":["Mener plusieurs conversations écrites en même temps","Ouvrir vingt onglets et n’en fermer aucun","Commencer une anecdote, bifurquer, puis oublier la chute","Poser des questions à tout le monde, y compris aux inconnus dans une file d’attente"],"summary":{"soft":"Ton esprit papillonne avec grâce : tout t’intéresse, tout se relie, et tu sais trouver les mots qui rendent les choses légères.","cash":"Tu as un avis sur tout, et un deuxième avis au cas où. Ta phrase commence quelque part et finit dans un autre sujet.","expert":"Mercure en Gémeaux occupe son domicile d’air mutable : l’intelligence y est agile, associative et verbale, au prix d’une attention qui se disperse volontiers."},"roastAngles":{"soft":["Dans ta tête, une fenêtre reste toujours ouverte, et les idées entrent en courant d’air."],"cash":["Tu racontes une histoire en ouvrant quatre parenthèses, sans jamais en refermer une.","Tu envoies douze messages là où un seul suffisait, et le dernier dit « bref »."],"expert":["Mercure en domicile : vous comprenez vite, expliquez mieux encore, et changez de sujet avant la conclusion."]},"roastWeight":3,"avoid":["Réduire ce placement à de la superficialité","Parler de duplicité ou de double jeu"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:leo', 'fr', '1', '{"keywords":["éloquence","conviction","sens du récit","fierté intellectuelle","chaleur"],"essence":"Mercure en Lion pense en grand et parle avec panache : l’idée s’expose avec conviction, le récit prime sur le détail, et l’avis exprimé engage la fierté.","light":["Talent pour raconter et captiver un auditoire","Parole chaleureuse, qui encourage","Clarté et fermeté des convictions"],"shadow":["Difficulté à reconnaître une erreur en public","Tendance à ramener la conversation à sa propre expérience","Goût de l’effet au détriment de la précision"],"behaviors":["Raconter une anecdote banale comme une épopée","Parler avec les mains et hausser la voix sans s’en apercevoir","Présenter une opinion comme une évidence","Attendre une réaction après chaque message envoyé"],"summary":{"soft":"Quand tu parles, on écoute : tu racontes avec chaleur et tu donnes de l’éclat aux idées. Ta parole a quelque chose de généreux.","cash":"Tu ne donnes pas ton avis, tu le proclames. Et si personne ne réagit, tu le redis plus fort, avec les gestes.","expert":"Mercure en Lion, signe de feu fixe, donne une pensée affirmative et une expression théâtrale : vous exposez avec autorité et cédez difficilement sur une conviction."},"roastAngles":{"soft":["Tu racontes les choses avec tant de cœur que même la liste de courses devient un récit."],"cash":["Tu as raconté cette anecdote dix fois, et à chaque version ton rôle a pris de l’ampleur.","Tu envoies un vocal de cinq minutes pour dire oui, avec introduction et rappel."],"expert":["Pensée fixe de feu : chez vous, admettre une erreur de raisonnement relève presque de l’abdication."]},"roastWeight":2,"avoid":["Réduire ce placement à de la vantardise","Confondre assurance verbale et absence de doute"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:libra', 'fr', '1', '{"keywords":["diplomatie","sens de la nuance","comparaison","hésitation","élégance verbale"],"essence":"Mercure en Balance pense par comparaison : chaque idée est pesée avec son contraire, la parole cherche l’équilibre et l’accord, et la forme compte autant que le fond.","light":["Diplomatie et tact dans la formulation","Capacité à comprendre le point de vue adverse","Sens de l’argument équitable"],"shadow":["Indécision prolongée devant un choix simple","Tendance à dire ce que l’autre veut entendre","Évitement de la contradiction frontale"],"behaviors":["Demander l’avis de plusieurs personnes avant de trancher","Commencer ses phrases par « d’un côté » et « en même temps »","Reformuler un désaccord jusqu’à le rendre méconnaissable","Hésiter longuement devant un menu"],"summary":{"soft":"Tu as l’art de dire les choses avec douceur et justesse. Tu vois toujours l’autre côté, et cela rend ta parole apaisante.","cash":"Tu pèses le pour, le contre, puis le pour du contre. À la fin, tu demandes aux autres ce qu’ils prennent.","expert":"Mercure en Balance, signe d’air cardinal, raisonne par mise en regard des contraires : vous argumentez avec équité, mais concluez tard, par souci d’équilibre."},"roastAngles":{"soft":["Tes mots arrivent toujours bien habillés, même pour annoncer une mauvaise nouvelle."],"cash":["Tu lances un sondage auprès de cinq personnes pour choisir entre deux pizzas.","Tu dis « c’est intéressant comme point de vue » quand le désaccord est total."],"expert":["Pensée cardinale d’air : vous instruisez à charge et à décharge, et le verdict se fait attendre."]},"roastWeight":2,"avoid":["Présenter la diplomatie comme de l’hypocrisie","Réduire ce placement à l’indécision"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:pisces', 'fr', '1', '{"keywords":["imagination","pensée par images","intuition","flou","empathie verbale"],"essence":"Mercure en Poissons est en exil et en chute : la pensée procède par images, impressions et associations plus que par démonstration, et capte l’ambiance avant les faits.","light":["Imagination et sens poétique","Intuition de ce que l’autre ressent sans avoir à l’entendre","Aisance avec la métaphore, la musique, l’image"],"shadow":["Flou dans les explications et les consignes","Distraction, oublis pratiques","Difficulté à trancher entre deux versions des faits"],"behaviors":["Perdre le fil de sa phrase en la prononçant","Répondre à un message en pensée et oublier de l’écrire","Comprendre l’humeur d’une pièce avant d’avoir entendu un mot","Expliquer un itinéraire avec des impressions plutôt qu’avec des noms de rue"],"summary":{"soft":"Tu penses en images et en musique. Tu comprends ce qui ne se dit pas, et tes mots ont la douceur de ceux qui ont d’abord ressenti.","cash":"Tu as répondu à ce message, mais seulement dans ta tête. Tu expliques un trajet par « tu sens quand c’est là ».","expert":"Mercure en Poissons, en exil et en chute, en eau mutable : la pensée y est analogique et intuitive ; vous saisissez l’ensemble par impression, au détriment de la précision."},"roastAngles":{"soft":["Tes pensées nagent en eau profonde : jamais en ligne droite, mais souvent avec des perles."],"cash":["Tu commences une phrase, tu regardes par la fenêtre, et la phrase repart sans toi.","Tu dis « attends, j’avais un truc à dire » environ une fois par conversation."],"expert":["Mercure en chute : vous retenez l’atmosphère d’une réunion mieux que l’ordre du jour."]},"roastWeight":3,"avoid":["Présenter la chute comme une faiblesse intellectuelle","Réduire ce placement à de la confusion"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:sagittarius', 'fr', '1', '{"keywords":["vue d’ensemble","franchise","enthousiasme","goût du débat","approximation"],"essence":"Mercure en Sagittaire est en exil : la pensée vise le sens général plutôt que le détail, s’enthousiasme pour les grandes idées et s’exprime avec une franchise sans filtre.","light":["Vision large et sens de la synthèse","Enthousiasme communicatif pour apprendre et transmettre","Honnêteté spontanée"],"shadow":["Approximation sur les faits et les chiffres","Franchise qui tourne à la bourde","Tendance à faire la leçon"],"behaviors":["Gonfler un chiffre pour rendre l’histoire meilleure","Dire tout haut ce que la tablée pensait tout bas","Transformer une question simple en exposé sur le sens de la vie","Commencer trois livres et en recommander cinq"],"summary":{"soft":"Ton esprit voit loin et large : tu cherches le sens, tu t’enthousiasmes, tu donnes envie d’apprendre. Ta franchise a la fraîcheur du grand air.","cash":"Tu dis la vérité d’abord et tu regardes les têtes après. Les détails, tu les arrondis : c’est l’idée générale qui compte.","expert":"Mercure en Sagittaire est en exil, en feu mutable : la synthèse et la conviction l’emportent sur l’exactitude ; vous pensez par grandes lignes et affirmez volontiers."},"roastAngles":{"soft":["Tu parles comme on part en voyage : avec élan, et sans trop regarder la carte."],"cash":["Tu dis « sans vouloir te vexer » et toute la table retient son souffle.","Tu cites une étude que tu n’as pas lue, avec un pourcentage inventé sur place."],"expert":["Mercure en exil : chez vous, l’idée générale est juste et la référence précise reste à vérifier."]},"roastWeight":2,"avoid":["Présenter l’exil comme un défaut d’intelligence","Réduire ce placement à du bavardage"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:scorpio', 'fr', '1', '{"keywords":["perspicacité","esprit d’enquête","sens du non-dit","ironie mordante","secret"],"essence":"Mercure en Scorpion pense en profondeur et sonde ce qui se cache : l’esprit enquête, lit entre les lignes, garde ses conclusions pour lui et parle peu, mais avec précision.","light":["Perspicacité psychologique","Concentration tenace sur un sujet","Discrétion absolue sur ce qui est confié"],"shadow":["Soupçon devant une réponse trop simple","Ironie qui pique plus que prévu","Rétention d’information par stratégie"],"behaviors":["Poser la question dont la réponse est déjà connue","Remarquer l’heure de dernière connexion et en tirer des conclusions","Retrouver une information en quelques recherches bien menées","Se taire dans un débat, puis placer la phrase qui clôt tout"],"summary":{"soft":"Tu vois ce que les mots cachent et tu écoutes les silences. Ce que l’on te confie reste chez toi, à l’abri.","cash":"Tu poses des questions dont tu connais déjà la réponse, pour voir. Tes amis appellent ça discuter, toi tu appelles ça vérifier.","expert":"Mercure en Scorpion, signe d’eau fixe, donne une intelligence d’enquête, secrète et pénétrante : vous cherchez le mobile derrière le propos et livrez peu de vos conclusions."},"roastAngles":{"soft":["Tu lis entre les lignes avec une telle finesse que les lignes en deviennent presque inutiles."],"cash":["Tu sais déjà tout avant de demander, tu demandes quand même, et tu compares les versions.","Tu réponds « intéressant » et la personne en face revoit toute sa journée."],"expert":["Pensée fixe d’eau : vous écoutez moins ce qui est dit que la raison pour laquelle cela est dit."]},"roastWeight":3,"avoid":["Présenter ce placement comme manipulateur","Associer la lucidité à de la noirceur"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:taurus', 'fr', '1', '{"keywords":["pensée concrète","lenteur réfléchie","bon sens","ténacité","voix posée"],"essence":"Mercure en Taureau pense lentement et solidement : l’esprit a besoin de concret, de temps et de preuves tangibles avant de se prononcer, puis ne change plus guère d’avis.","light":["Bon sens pratique et jugement fiable","Mémoire durable de ce qui a été appris","Parole calme, qui rassure"],"shadow":["Difficulté à revenir sur une opinion formée","Lenteur à répondre quand la décision presse","Méfiance envers les idées trop abstraites"],"behaviors":["Demander un exemple concret avant d’accepter une idée","Annoncer un temps de réflexion et réfléchir vraiment","Répéter le même argument, sur le même rythme, jusqu’à l’usure de l’adversaire","Apprendre par la répétition et la pratique"],"summary":{"soft":"Tu prends le temps de penser, et ce que tu dis tient debout. Ta parole a le calme des choses qui ne changent pas d’avis tous les matins.","cash":"Tu réfléchis longtemps, puis tu ne bouges plus. Te faire changer d’avis demande un dossier, des preuves et un goûter.","expert":"Mercure en Taureau, signe de terre fixe, ancre la pensée dans le concret : vous assimilez lentement, retenez durablement et cédez peu une fois l’opinion formée."},"roastAngles":{"soft":["Tes idées mûrissent comme des fruits : lentement, mais on peut compter dessus."],"cash":["Tu écris « je réfléchis » en réponse, et la suite arrive à la saison suivante.","Tu as changé d’avis une fois, et tout le monde s’en souvient encore."],"expert":["Pensée fixe de terre : une opinion acquise devient chez vous un bien immobilier."]},"roastWeight":2,"avoid":["Confondre lenteur et manque de vivacité","Caricaturer la constance en fermeture d’esprit"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:mercury:virgo', 'fr', '1', '{"keywords":["analyse","précision","sens du détail","esprit critique","méthode"],"essence":"Mercure en Vierge est en domicile et en exaltation : la pensée trie, classe et vérifie, avec un goût marqué pour la précision, la méthode et l’utilité concrète.","light":["Analyse fine et repérage immédiat des erreurs","Méthode et clarté dans l’explication","Fiabilité des informations transmises"],"shadow":["Tendance à corriger les autres sans que personne l’ait demandé","Perfectionnisme qui retarde la conclusion","Difficulté à voir l’ensemble derrière les détails"],"behaviors":["Repérer la faute d’orthographe avant de lire le message","Faire des listes, puis des listes de listes","Relire un courriel plusieurs fois avant de l’envoyer","Vérifier l’information à la source avant de la répéter"],"summary":{"soft":"Ton esprit a la patience des artisans : tu observes, tu tries, tu affines. Grâce à toi, les choses deviennent claires et utilisables.","cash":"Tu as vu la faute de frappe. Tu ne dis rien. Tu ne penses plus qu’à ça depuis le début de la réunion.","expert":"Mercure en Vierge cumule domicile et exaltation en terre mutable : l’intelligence y est analytique, méthodique et critique, parfois au détriment de la synthèse."},"roastAngles":{"soft":["Tu ranges les idées comme d’autres rangent une armoire : avec soin, et un peu de tendresse."],"cash":["Tu relis ton message quatre fois, tu l’envoies, et là tu repères la coquille.","Tu corriges la carte du restaurant dans ta tête pendant que les autres commandent."],"expert":["Mercure doublement dignifié : vous distinguez l’erreur dans un texte avant d’en saisir le propos."]},"roastWeight":3,"avoid":["Réduire ce placement à de la maniaquerie","Présenter l’esprit critique comme de la froideur"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:aquarius', 'fr', '1', '{"keywords":["détachement","indépendance","amitié","recul","besoin d’espace"],"essence":"La Lune en Verseau, signe fixe d’air, donne une vie émotionnelle détachée, indépendante et amicale. La sécurité intérieure passe par la liberté, l’espace personnel et le droit de rester différent.","light":["Écoute sans jugement","Amitié fidèle, sans possessivité","Recul qui aide à garder la tête froide"],"shadow":["Distance prise dès que l’émotion se fait pressante","Tendance à analyser un sentiment pour ne pas le vivre","Besoin d’air qui déroute les proches"],"behaviors":["Répondre à une déclaration par « c’est noté »","Avoir besoin de trois jours en solitaire après une fête","Consoler avec un article scientifique","Observer sa propre tristesse comme un phénomène curieux","Donner des nouvelles toutes les trois semaines, avec affection"],"summary":{"soft":"Ton cœur aime à sa façon : avec de l’espace, de la curiosité et une amitié qui ne retient personne. On peut tout te dire, tu ne juges pas.","cash":"On te dit “je t’aime”, tu réponds “c’est noté”. Tu observes tes émotions de loin, comme un documentaire animalier.","expert":"La Lune en Verseau, signe fixe d’air, met l’émotion à distance pour la penser. Vous avez besoin d’indépendance et d’affinités d’esprit ; la fusion affective vous met mal à l’aise."},"roastAngles":{"soft":["Tu laisses à chacun la liberté d’être soi : c’est rare, et c’est une vraie forme d’amour."],"cash":["Quelqu’un pleure devant toi. Tu compatis sincèrement, et tu cherches déjà une étude sur le sujet.","Après une soirée entre amis, tu as besoin de trois jours sans voir personne, toi y compris."],"expert":["Lune en Verseau : émotion fixe, d’air. Vous éprouvez les choses, mais de préférence à bonne distance."]},"roastWeight":2,"avoid":["Présenter le détachement comme une absence de cœur","Réduire le placement à la bizarrerie"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:aries', 'fr', '1', '{"keywords":["réactivité","spontanéité","impatience","franchise affective","élan"],"essence":"La Lune en Bélier, signe cardinal de feu, donne une vie émotionnelle vive, immédiate et sans détour. Les besoins s’expriment sur-le-champ et la sécurité intérieure passe par l’action.","light":["Émotions franches, exprimées sans calcul","Capacité à rebondir vite après un coup dur","Enthousiasme spontané, communicatif"],"shadow":["Réactions à chaud, parfois regrettées dans l’heure","Impatience devant les besoins des autres","Difficulté à rester avec une émotion sans agir"],"behaviors":["Envoyer le message sous le coup de la colère","Claquer une porte puis proposer un café dix minutes après","Vouloir régler le problème tout de suite, même à minuit","S’ennuyer dès que tout est calme","Répondre avant la fin de la phrase"],"summary":{"soft":"Tes émotions arrivent comme une étincelle : vives, sincères, vite passées. Avec toi, rien ne couve, tout se dit, et l’air redevient léger.","cash":"Tu t’énerves en quatre secondes et tu oublies en cinq. Le problème, c’est que les autres ont meilleure mémoire.","expert":"La Lune en Bélier, signe cardinal de feu, rend la réponse émotionnelle immédiate et combative. Vous déchargez la tension par l’action ; l’attente et l’ambiguïté affective vous coûtent."},"roastAngles":{"soft":["Ton cœur démarre au quart de tour, et il ne sait pas garder rancune plus d’une heure."],"cash":["Tu as envoyé le message à chaud. Tu as relu après. Tu assumes, mais tu as éteint le téléphone.","Ta façon de te calmer, c’est de régler le problème tout de suite, à minuit, par message vocal."],"expert":["Lune en Bélier : émotion cardinale, de feu. Vous réagissez d’abord ; l’analyse suit, quand elle suit."]},"roastWeight":3,"avoid":["Présenter la colère comme de la violence","Confondre vivacité émotionnelle et immaturité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:cancer', 'fr', '1', '{"keywords":["sensibilité","foyer","mémoire affective","protection","humeur cyclique"],"essence":"La Lune en Cancer, où elle est en domicile, donne une vie émotionnelle profonde, protectrice et tournée vers le foyer. La sensibilité y est à son maximum et la sécurité intérieure passe par l’appartenance.","light":["Tendresse instinctive et sens du réconfort","Intuition très sûre de l’humeur des proches","Fidélité aux souvenirs et aux liens anciens"],"shadow":["Humeur qui monte et descend comme une marée","Blessure facile, gardée longtemps en mémoire","Besoin de réassurance qui ne se dit pas"],"behaviors":["Relire de vieilles conversations un dimanche soir","Préparer un plat d’enfance pour aller mieux","Deviner l’état d’un proche à sa façon de dire bonjour","Se refermer d’un coup après une remarque anodine","Garder le pull d’une personne aimée"],"summary":{"soft":"Tu as un cœur de maison, avec de la lumière aux fenêtres. Tu sens tout avant qu’on te le dise, et tu protèges les tiens sans faire de bruit.","cash":"Tu as changé d’humeur trois fois depuis ce matin, et tu en veux à quelqu’un pour un rêve que tu as fait.","expert":"La Lune en Cancer est en domicile : en signe cardinal d’eau, elle exprime pleinement sensibilité, mémoire et instinct protecteur. Vous avez besoin d’un refuge ; l’humeur suit chez vous des cycles marqués."},"roastAngles":{"soft":["Tu te souviens de tout ce qui a compté, et tu en fais un abri pour les jours de pluie."],"cash":["Tu relis de vieux messages le dimanche soir, pour vérifier que ça pique toujours autant.","Quelqu’un a dit “tu le prends mal, non ?”. Tu n’as rien répondu. Depuis mardi."],"expert":["Lune en Cancer, en domicile : mémoire affective intacte. Vous n’oubliez rien de ce qui vous a touché."]},"roastWeight":3,"avoid":["Réduire le placement aux larmes ou à l’instinct maternel","Présenter la sensibilité comme une faiblesse"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:capricorn', 'fr', '1', '{"keywords":["retenue","maîtrise","responsabilité","pudeur","endurance"],"essence":"La Lune en Capricorne, où elle est en exil, donne une vie émotionnelle contenue, pudique et responsable. La sécurité intérieure repose sur la maîtrise, l’utilité et le fait de ne dépendre de personne.","light":["Sang-froid dans les moments critiques","Fiabilité affective qui se prouve par les actes","Endurance face aux périodes difficiles"],"shadow":["Émotions remises à plus tard, indéfiniment","Difficulté à demander de l’aide","Sérieux précoce qui laisse peu de place au jeu"],"behaviors":["Répondre « ça va, j’ai du travail » à une question sur ses sentiments","Régler les problèmes des autres avant d’écouter les siens","Pleurer en cachette, brièvement, puis reprendre sa liste de tâches","Montrer son affection en réparant quelque chose","Culpabiliser d’un dimanche sans rien produire"],"summary":{"soft":"Ton cœur est pudique : il parle peu, mais il est là, solide, quand tout vacille. Ta tendresse se lit dans ce que tu fais, pas dans ce que tu dis.","cash":"Tu as rangé tes émotions dans un dossier “à voir plus tard”. Le dossier date de l’école primaire et il est très bien tenu.","expert":"La Lune en Capricorne est en exil : en signe cardinal de terre, l’émotion se contient et se structure. Vous privilégiez la maîtrise et l’utile ; exprimer un besoin affectif vous demande du temps."},"roastAngles":{"soft":["Tu portes les autres sans rien demander : tu as le droit, toi aussi, de poser la tête sur une épaule."],"cash":["On t’a demandé comment tu te sentais. Tu as répondu par ton planning de la semaine.","Tu as pleuré quatre minutes, montre en main, puis tu as repris ta liste là où tu l’avais laissée."],"expert":["Lune en Capricorne, en exil : émotion sous contrôle. Vous consolez par des solutions, rarement par des mots."]},"roastWeight":3,"avoid":["Parler de froideur ou d’absence de sentiments","Dramatiser la notion d’exil"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:gemini', 'fr', '1', '{"keywords":["verbalisation","curiosité","humeur mobile","légèreté","agitation mentale"],"essence":"La Lune en Gémeaux, signe mutable d’air, donne une vie émotionnelle mobile, curieuse et bavarde. Les émotions passent par les mots, et la sécurité intérieure dépend de l’échange et de la nouveauté.","light":["Humour qui désamorce les tensions","Capacité à mettre des mots sur ce qui se passe","Légèreté qui aide à prendre du recul"],"shadow":["Humeur changeante d’une heure à l’autre","Tendance à expliquer une émotion plutôt qu’à la ressentir","Agitation mentale au moment de s’endormir"],"behaviors":["Raconter le même souci à cinq personnes pour savoir quoi en penser","Envoyer douze messages courts au lieu d’un seul","Faire une blague au moment le plus sérieux","Changer d’avis sur ses sentiments entre midi et le soir","Écouter un podcast pour ne pas entendre ses pensées"],"summary":{"soft":"Chez toi, le cœur parle : il raconte, il questionne, il rit pour respirer. Mettre des mots sur ce que tu ressens, c’est ta façon de t’apaiser.","cash":"Tu traites tes émotions par messages vocaux de sept minutes. Tu ne sais pas ce que tu ressens, mais tu as trois hypothèses.","expert":"La Lune en Gémeaux, signe mutable d’air, intellectualise la vie émotionnelle. Vous avez besoin de verbaliser pour assimiler ; l’humeur varie vite, au gré des échanges et des stimulations."},"roastAngles":{"soft":["Ton cœur a besoin de parler pour savoir ce qu’il pense : laisse-le bavarder, il s’y retrouve."],"cash":["Tu as demandé l’avis de cinq personnes sur ta dispute, et tu as suivi celui qui t’arrangeait.","Tu envoies douze messages à la suite, puis “laisse tomber”, puis un treizième pour expliquer."],"expert":["Lune en Gémeaux : émotion mutable, d’air. Vous commentez ce que vous éprouvez, plus que vous ne l’éprouvez."]},"roastWeight":3,"avoid":["Parler d’instabilité ou de duplicité","Confondre besoin de parler et superficialité des sentiments"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:leo', 'fr', '1', '{"keywords":["chaleur","fierté","démonstration","loyauté de cœur","besoin de reconnaissance"],"essence":"La Lune en Lion, signe fixe de feu, donne une vie émotionnelle chaleureuse, fière et démonstrative. La sécurité intérieure dépend du sentiment de compter et de recevoir une affection visible.","light":["Affection généreuse, qui se montre","Loyauté de cœur, durable","Don pour mettre de la joie et du jeu dans le quotidien"],"shadow":["Amour-propre vite froissé","Besoin de preuves d’affection répétées","Tendance à dramatiser pour se faire entendre"],"behaviors":["Bouder avec panache quand un message reste sans réponse","Faire d’un anniversaire un événement d’une semaine","Raconter sa peine avec des gestes de théâtre","Couvrir les proches de cadeaux et de compliments","Retenir qui n’a pas réagi à la bonne nouvelle"],"summary":{"soft":"Ton cœur est un feu de cheminée : il réchauffe large et il aime qu’on vienne s’y asseoir. Tu aimes en grand, et tu mérites qu’on te le rende.","cash":"Tu ne fais pas la tête, tu fais une représentation. Avec un entracte, au cas où quelqu’un voudrait présenter ses excuses.","expert":"La Lune en Lion, signe fixe de feu, lie la sécurité affective à la reconnaissance. Vous exprimez vos sentiments avec ampleur et constance ; l’indifférence vous atteint davantage que le conflit."},"roastAngles":{"soft":["Tu aimes comme on fait une fête : avec des lumières partout et une place d’honneur pour chacun."],"cash":["Ton anniversaire dure une semaine. Tu n’as rien décidé, c’est le calendrier qui s’adapte.","Tu as annoncé une bonne nouvelle, et tu as noté mentalement qui a mis plus d’une heure à réagir."],"expert":["Lune en Lion : besoin fixe de reconnaissance. Vous pardonnez l’offense, plus difficilement l’inattention."]},"roastWeight":3,"avoid":["Réduire le placement au caprice ou à la vanité","Employer des images de roi ou de reine"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:libra', 'fr', '1', '{"keywords":["harmonie","lien","tact","évitement du conflit","partage"],"essence":"La Lune en Balance, signe cardinal d’air, donne une vie émotionnelle tournée vers la relation, la douceur et l’accord. La sécurité intérieure dépend de l’harmonie du lien et de la paix autour de soi.","light":["Tact naturel et sens de l’écoute","Capacité à apaiser une tension dans un groupe","Goût de partager plutôt que de vivre les choses à part"],"shadow":["Malaise profond devant le conflit ouvert","Besoins personnels effacés pour préserver l’entente","Humeur suspendue à celle de l’autre"],"behaviors":["Dire « ce n’est pas grave » en pensant le contraire","Rédiger un message délicat en six brouillons","Changer de restaurant pour que personne ne soit déçu","Sourire pendant une dispute pour calmer le jeu","Vérifier trois fois que tout le monde est d’accord"],"summary":{"soft":"Ton cœur cherche l’accord comme une oreille cherche la note juste. Tu apaises, tu relies, tu arrondis : la paix autour de toi est ton vrai repos.","cash":"Tu dis “non mais c’est pas grave” avec le sourire, et tu y repenses pendant onze jours ouvrés.","expert":"La Lune en Balance, signe cardinal d’air, subordonne le bien-être émotionnel à la qualité du lien. Vous recherchez l’accord et l’équité ; le conflit ouvert vous déstabilise plus que le compromis."},"roastAngles":{"soft":["Tu fais de la place à tout le monde : n’oublie pas de garder une chaise pour toi."],"cash":["Tu as écrit six brouillons pour dire “ça m’a un peu dérangé”, et tu as envoyé “pas de souci”.","Pendant une dispute, tu défends l’avis de l’autre mieux que l’autre, puis tu demandes pardon."],"expert":["Lune en Balance : besoin cardinal d’entente. Vous cédez volontiers, puis vous tenez les comptes en silence."]},"roastWeight":3,"avoid":["Réduire le placement à la dépendance affective","Confondre recherche de paix et hypocrisie"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:pisces', 'fr', '1', '{"keywords":["empathie","perméabilité","rêverie","compassion","retrait"],"essence":"La Lune en Poissons, signe mutable d’eau, donne une vie émotionnelle perméable, rêveuse et compatissante. La sécurité intérieure passe par la douceur, l’imaginaire et des moments de retrait.","light":["Empathie immédiate, sans effort","Imagination consolatrice","Douceur qui accueille sans poser de conditions"],"shadow":["Absorption des émotions des autres comme si c’étaient les siennes","Évasion dès que la réalité se fait rude","Difficulté à savoir ce qui relève de soi"],"behaviors":["Pleurer pour un personnage de dessin animé","Revenir d’un dîner avec la fatigue de toute la table","Dormir pour laisser passer l’orage","Pardonner avant d’avoir reçu des excuses","Écouter la même chanson triste en boucle"],"summary":{"soft":"Ton cœur n’a pas de porte : tout y entre, la joie des autres comme leur peine. Ta douceur console sans un mot, comme une mer calme.","cash":"Tu absorbes l’humeur de toute la pièce, y compris celle du chien. Ta solution à tout : une sieste et une chanson triste.","expert":"La Lune en Poissons, signe mutable d’eau, rend la sensibilité poreuse et diffuse. Vous captez les climats affectifs sans filtre ; des temps de retrait sont nécessaires pour distinguer ce qui vous appartient."},"roastAngles":{"soft":["Tu ressens pour deux, parfois pour dix : pense à garder un peu de cette tendresse pour toi."],"cash":["Tu as pleuré pour un personnage secondaire, dans un film que tu avais déjà vu quatre fois.","Quelqu’un t’a fait du tort, et c’est toi qui lui as trouvé des excuses avant qu’il ouvre la bouche."],"expert":["Lune en Poissons : émotion mutable, d’eau. Vous compatissez d’abord, et vous vérifiez les faits ensuite."]},"roastWeight":3,"avoid":["Réduire le placement à la naïveté ou au rôle de victime","Évoquer des dons de voyance"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:sagittarius', 'fr', '1', '{"keywords":["optimisme","liberté","mouvement","sens","franchise affective"],"essence":"La Lune en Sagittaire, signe mutable de feu, donne une vie émotionnelle optimiste, mobile et éprise de liberté. La sécurité intérieure passe par l’espace, le mouvement et le sentiment que tout garde un sens.","light":["Moral qui remonte vite","Franchise affective, sans arrière-pensée","Don pour dédramatiser et élargir la perspective"],"shadow":["Fuite quand l’émotion devient pesante","Paroles de réconfort parfois trop expéditives","Engagements affectifs pris dans l’enthousiasme"],"behaviors":["Proposer une randonnée à quelqu’un qui voulait juste parler","Regarder des billets de train après une contrariété","Rire au milieu d’une conversation grave","Étouffer dès qu’un week-end est planifié heure par heure","Philosopher sur une rupture au lieu de la pleurer"],"summary":{"soft":"Ton cœur a besoin de ciel : d’air, de route, de rires. Tu remontes vite, et tu emmènes les autres avec toi vers quelque chose de plus grand.","cash":"Quand ça ne va pas, tu regardes des billets de train. Ton conseil pour toutes les peines : “allez, on sort”.","expert":"La Lune en Sagittaire, signe mutable de feu, associe le bien-être à la liberté et au sens. Vous surmontez l’émotion par le mouvement et la mise en perspective ; la contrainte affective vous pèse vite."},"roastAngles":{"soft":["Tu soignes les chagrins avec de l’horizon : une route, un rire, et le cœur repart."],"cash":["On t’a confié un gros chagrin. Tu as répondu par une citation, puis par une idée de randonnée.","Tu as besoin d’espace dans une relation : environ un continent, avec possibilité de revenir dîner."],"expert":["Lune en Sagittaire : émotion mutable, de feu. Vous relativisez plus vite que vous ne ressentez."]},"roastWeight":2,"avoid":["Réduire le placement à la peur de l’engagement","Présenter l’optimisme comme de l’insouciance"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:scorpio', 'fr', '1', '{"keywords":["intensité","secret","confiance","profondeur","mémoire des blessures"],"essence":"La Lune en Scorpion, où elle est en chute, donne une vie émotionnelle intense, secrète et entière. La sécurité intérieure exige une confiance totale, et les sentiments se vivent en profondeur plus qu’ils ne se montrent.","light":["Profondeur de l’attachement, sans demi-mesure","Flair pour ce que les autres cachent","Force intérieure dans les moments difficiles"],"shadow":["Méfiance qui précède la confiance","Mémoire longue des blessures","Émotions retenues jusqu’à la saturation"],"behaviors":["Répondre « rien » avec un regard qui dit tout","Tester la loyauté des proches sans prévenir","Deviner un mensonge à une virgule près","Ne jamais reparler d’une blessure et ne jamais l’oublier","Vérifier une histoire qui semblait trop lisse"],"summary":{"soft":"Tu ressens en profondeur, là où peu de gens osent descendre. Ta réserve protège un cœur entier, qui ne se donne qu’une fois la confiance gagnée.","cash":"Tu réponds “rien” avec un regard qui contient trois chapitres. Tu n’oublies jamais, tu classes.","expert":"La Lune en Scorpion est en chute : en signe fixe d’eau, l’émotion se concentre et se retient. Vous éprouvez intensément sans le montrer ; la confiance s’accorde lentement et ne se partage pas."},"roastAngles":{"soft":["Tu aimes sans bruit et sans retour en arrière : qui entre dans ton cœur y a sa place pour longtemps."],"cash":["Tu as senti le mensonge à la ponctuation. Tu n’as rien dit. Tu attends juste de voir jusqu’où ça va.","Ta confiance se mérite en plusieurs épreuves, dont personne n’a reçu ni le règlement ni les dates."],"expert":["Lune en Scorpion, en chute : émotion fixe, d’eau. Vous ne confiez rien, mais vous observez tout."]},"roastWeight":3,"avoid":["Réduire le placement à la jalousie ou à la vengeance","Dramatiser la notion de chute"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:taurus', 'fr', '1', '{"keywords":["sécurité","confort","constance","sensorialité","attachement"],"essence":"La Lune en Taureau, où elle est en exaltation, donne une vie émotionnelle stable, sensible au confort et attachée à ce qui dure. La sécurité intérieure repose sur le tangible et le régulier.","light":["Calme qui apaise l’entourage","Fidélité affective sur la durée","Art de prendre soin par le concret : un repas, une couverture, du temps"],"shadow":["Résistance émotionnelle à tout imprévu","Possessivité envers les personnes et les objets aimés","Consolation cherchée dans l’assiette ou les achats"],"behaviors":["Avoir un plaid attitré et une place attitrée sur le canapé","Mal vivre un changement de programme de dernière minute","Manger quelque chose de bon pour se remettre d’une contrariété","Garder le même parfum de glace depuis l’enfance","Mettre des semaines à digérer une dispute"],"summary":{"soft":"Ton cœur aime ce qui dure : les rituels, les bras familiers, le pain chaud. Près de toi, on se pose, et tout retrouve sa juste mesure.","cash":"Ton langage affectif, c’est le fromage. On t’a déplacé un dîner, et tu as eu besoin de trois jours pour t’en remettre.","expert":"La Lune en Taureau est en exaltation : en signe fixe de terre, elle stabilise l’humeur et ancre les besoins dans le sensible. Vous cherchez la permanence ; tout changement affectif s’assimile lentement."},"roastAngles":{"soft":["Tu consoles avec un plat chaud et une présence tranquille : on ne fait pas plus sûr."],"cash":["Tu as une place sur le canapé. Personne ne l’a décidé, tout le monde le sait, et gare à qui s’y assoit.","On a changé le programme à la dernière minute, et ton silence a duré plus longtemps que la soirée."],"expert":["Lune en Taureau, en exaltation : besoin de constance. Vous tenez à vos habitudes comme à des personnes."]},"roastWeight":3,"avoid":["Réduire le placement à la gourmandise","Faire de la stabilité une forme de paresse affective"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:moon:virgo', 'fr', '1', '{"keywords":["pudeur","utilité","routine","inquiétude","attention aux détails"],"essence":"La Lune en Vierge, signe mutable de terre, donne une vie émotionnelle pudique, attentive et tournée vers l’utile. La sécurité intérieure passe par l’ordre, la routine et le sentiment de bien faire.","light":["Attention concrète aux besoins des autres","Fiabilité dans les petits gestes du quotidien","Lucidité sur ses propres réactions"],"shadow":["Inquiétude qui s’accroche aux détails","Autocritique dès que l’émotion déborde","Difficulté à recevoir de l’aide sans la mériter"],"behaviors":["Ranger un placard pour se calmer","Rejouer une conversation en corrigeant ses répliques","Montrer son affection en rappelant une échéance oubliée","Demander pardon d’avoir pleuré","Préparer un sac la veille, puis le vérifier le matin"],"summary":{"soft":"Ton cœur prend soin par petites touches : un rappel, un geste, une chose réparée. Sous ta pudeur, il y a une attention de chaque instant.","cash":"Quand ça ne va pas, tu ranges. Ton placard à épices est donc classé par ordre alphabétique, et par date.","expert":"La Lune en Vierge, signe mutable de terre, soumet l’émotion à l’analyse. Vous vous apaisez par l’ordre et l’utilité ; le besoin de bien faire entretient une vigilance constante."},"roastAngles":{"soft":["Tu dis “je t’aime” en vérifiant que l’autre a pris son écharpe : c’est discret, et c’est immense."],"cash":["Tu rejoues la conversation de midi sous la douche, avec de meilleures répliques et des notes de bas de page.","Tu as pleuré deux minutes, tu as demandé pardon pour le dérangement, puis tu as nettoyé la table."],"expert":["Lune en Vierge : émotion triée, classée, annotée. Vous ressentez beaucoup, mais avec méthode."]},"roastWeight":3,"avoid":["Réduire le placement à la froideur ou à la maniaquerie","Employer un vocabulaire médical pour décrire l’inquiétude"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:aquarius', 'fr', '1', '{"keywords":["utopie collective","monde connecté","fraternité rêvée","avenir idéalisé"],"essence":"Neptune en Verseau idéalise le collectif : les réseaux, le progrès, la fraternité à grande échelle. Une génération qui rêve de communautés sans frontières ; chez une personne, le lien réel se confond parfois avec le lien à distance.","light":["Idéal d’égalité vécu avec sincérité","Imagination tournée vers les solutions communes","Aisance à créer du lien au-delà des cercles habituels"],"shadow":["Proximité virtuelle prise pour de l’intimité","Utopies défendues sans regarder leurs limites","Flou sur sa place personnelle dans le groupe"],"behaviors":["Se sentir proche de quelqu’un jamais rencontré hors écran","Rejoindre une communauté en ligne à minuit et la quitter à l’aube","Débattre d’un monde meilleur dans un fil de commentaires"],"summary":{"soft":"Tu rêves à plusieurs. Ton imaginaire voit ce que les gens pourraient faire ensemble, et tu as cette foi tranquille dans l’idée que personne n’avance vraiment en solitaire.","cash":"Tu as des amitiés profondes avec des gens dont tu ne connais que le pseudonyme et l’avis sur une série.","expert":"Neptune en Verseau, signe fixe d’air, porte l’idéal sur le collectif et l’innovation. Chez vous, l’imaginaire se nourrit du réseau, avec une frontière incertaine entre communauté réelle et communauté rêvée."},"roastAngles":{"soft":["Tu crois encore qu’une bonne idée partagée peut changer la journée de quelqu’un, et tu as raison."],"cash":["Tu refais le monde dans une conversation de groupe, entre deux images de chats.","Tu te sens en communion avec l’humanité, surtout quand le téléphone est en mode avion."],"expert":["Neptune en Verseau : utopie du lien généralisé, où l’idéal collectif peut masquer la distance individuelle."]},"roastWeight":1,"avoid":["Moquer l’usage des écrans comme une dépendance","Associer le placement à un camp ou à une idéologie"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:aries', 'fr', '1', '{"keywords":["idéal combatif","héroïsme rêvé","élan inspiré","croisade"],"essence":"Neptune en Bélier idéalise l’action : une génération qui rêve de commencements, de causes à défendre, de héros ordinaires. Chez une personne, l’inspiration pousse à foncer, mais la cible reste parfois floue.","light":["Foi communicative dans les nouveaux départs","Courage inspiré par un idéal plutôt que par l’intérêt","Capacité à redonner de l’élan à une cause essoufflée"],"shadow":["Combats menés pour une image plutôt que pour un but","Enthousiasme qui retombe dès que le réel résiste","Confusion entre impulsion et vocation"],"behaviors":["S’engager dans une cause découverte la veille","Annoncer un grand projet avant d’en connaître la première étape","Défendre un inconnu dans une file d’attente"],"summary":{"soft":"Tu crois aux commencements. Il y a chez toi un idéal qui a besoin d’agir, de défendre, d’ouvrir un chemin, et cette foi dans le premier pas donne du courage autour de toi.","cash":"Tu pars sauver le monde avant le petit-déjeuner. Vers midi, tu as oublié lequel.","expert":"Neptune en Bélier, placement générationnel, projette l’idéal sur l’initiative et le combat. Chez vous, l’inspiration appelle l’acte, avec un risque de flou sur l’objectif poursuivi."},"roastAngles":{"soft":["Tu as dans le cœur un drapeau sans pays, et l’envie sincère de le planter quelque part d’utile."],"cash":["Tu signes la pétition, tu partages la pétition, et tu demandes ensuite de quoi elle parle.","Ton héros intérieur a une cape magnifique et aucune idée de l’adresse où intervenir."],"expert":["Neptune en Bélier : idéalisation de l’élan pionnier, où la ferveur précède souvent la définition du but."]},"roastWeight":0,"avoid":["Associer le placement à une cause ou à un camp précis","Parler de violence ou de conflit armé"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:cancer', 'fr', '1', '{"keywords":["nostalgie","foyer idéalisé","mémoire rêvée","tendresse"],"essence":"Neptune en Cancer idéalise les racines : la maison, l’enfance, la famille telle qu’elle se raconte. Une génération portée par la nostalgie ; chez une personne, l’imaginaire revient sans cesse vers un refuge, réel ou reconstruit par le souvenir.","light":["Tendresse qui rassemble et console","Mémoire affective, attentive aux petites choses","Don pour créer une atmosphère de refuge"],"shadow":["Passé embelli au détriment du présent","Sensibilité qui absorbe l’humeur de toute la maisonnée","Difficulté à quitter un lieu ou un rôle protecteur"],"behaviors":["Garder les cartes d’anniversaire de toute une vie dans une boîte à chaussures","Refaire la recette d’enfance en regrettant qu’elle n’ait pas tout à fait le même goût","Pleurer devant une vieille photo de vacances"],"summary":{"soft":"Tu portes en toi une maison idéale, faite de souvenirs, d’odeurs et de voix aimées. Cette tendresse pour ce qui a été te rend capable d’offrir un vrai refuge aux autres.","cash":"Tu regrettes une époque que tu as en partie inventée. Dans ton souvenir, même les trajets en voiture étaient merveilleux.","expert":"Neptune en Cancer, signe cardinal d’eau, attache l’idéal au foyer et à la mémoire. Chez vous, l’imaginaire se nourrit du passé, avec une tendance marquée à l’idéalisation des origines."},"roastAngles":{"soft":["Tu gardes les souvenirs au chaud comme d’autres gardent des braises, et on vient s’y réchauffer."],"cash":["Tu dis « c’était mieux avant » à propos d’une période où tu te plaignais déjà beaucoup.","Tu ne jettes rien : chaque ticket de cinéma est une pièce de musée, avec visite guidée."],"expert":["Neptune en Cancer : la nostalgie y tient lieu d’idéal, et le souvenir y est volontiers retouché."]},"roastWeight":0,"avoid":["Supposer quoi que ce soit sur l’enfance ou la famille réelle","Évoquer une perte ou une absence"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:capricorn', 'fr', '1', '{"keywords":["réussite idéalisée","structures rêvées","désillusion lucide","devoir"],"essence":"Neptune en Capricorne idéalise la construction : la réussite, les institutions, l’effort qui mène au sommet. Une génération qui rêve de solidité ; chez une personne, l’idéal prend la forme d’un plan, et le flou touche l’ambition elle-même.","light":["Idéal exigeant, traduit en efforts concrets","Sens du devoir porté par une vision","Capacité à donner une forme durable à un rêve"],"shadow":["Réussite poursuivie sans savoir pour qui","Désenchantement devant les autorités admirées","Sérieux qui étouffe la fantaisie"],"behaviors":["Rédiger un plan de carrière détaillé pour un métier pas encore choisi","Travailler tard pour un objectif que personne n’a fixé","Présenter ses rêves avec un tableau et des échéances"],"summary":{"soft":"Tu rêves de choses qui tiennent debout. Ton imaginaire aime les fondations, les projets au long cours, et tu sais donner à un idéal le sérieux qu’il mérite.","cash":"Tu as un rêve, bien sûr. Il a un échéancier, des indicateurs de suivi et aucune place pour la sieste.","expert":"Neptune en Capricorne, signe cardinal de terre, porte l’idéal sur les structures et l’accomplissement social. Chez vous, l’imaginaire cherche une forme, tandis que le flou touche le rapport à l’autorité."},"roastAngles":{"soft":["Tu bâtis des châteaux en Espagne, mais avec des plans, des fondations et un permis."],"cash":["Tu gravis la montagne avec application, et tu demandes au sommet qui avait choisi cette montagne.","Même tes rêveries ont un ordre du jour, et tu arrives en avance à la réunion."],"expert":["Neptune en Capricorne : l’idéal y cherche une forme institutionnelle, et s’expose à la désillusion des cadres."]},"roastWeight":1,"avoid":["Donner un conseil de carrière ou d’argent","Commenter des institutions ou des opinions"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:gemini', 'fr', '1', '{"keywords":["mots rêvés","imagination verbale","idées flottantes","récit"],"essence":"Neptune en Gémeaux idéalise la parole et les idées : une génération fascinée par les récits, les signes, la circulation des nouvelles. Chez une personne, l’imaginaire passe par les mots, et la frontière entre le fait et l’histoire bien racontée s’estompe.","light":["Talent pour raconter, sens de l’image juste","Écoute intuitive de ce qui se dit entre les lignes","Esprit poétique appliqué aux échanges quotidiens"],"shadow":["Récits embellis sans intention de tromper","Dispersion rêveuse entre trop d’idées","Malentendus nés d’un message resté vague"],"behaviors":["Raconter la même anecdote avec un détail de plus à chaque fois","Répondre à un message en pensée et croire l’avoir envoyé","Collectionner des carnets dont seule la première page est écrite"],"summary":{"soft":"Chez toi, les mots ont des ailes. Tu sais raconter, suggérer, faire sentir, et ta façon de parler ouvre de petits mondes dans la conversation la plus ordinaire.","cash":"Tu ne mens pas : tu améliores. Ton anecdote de vacances a gagné un orage et deux personnages depuis l’été.","expert":"Neptune en Gémeaux, signe mutable d’air, porte l’idéal et le flou sur le langage et l’information. Chez vous, la pensée procède par images, avec une précision factuelle variable."},"roastAngles":{"soft":["Tu parles comme on fait des ricochets : c’est léger, précis, et ça porte plus loin que prévu."],"cash":["Tu as répondu à ce message dans ta tête, avec beaucoup d’esprit. Dans la vraie vie, toujours rien.","Tu commences une phrase sans savoir où elle finit, et tu comptes sur elle pour te le dire."],"expert":["Neptune en Gémeaux : imagination verbale féconde, rapport plus lâche à l’exactitude des faits rapportés."]},"roastWeight":0,"avoid":["Traiter la personne de menteuse","Confondre rêverie et manque de sérieux"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:leo', 'fr', '1', '{"keywords":["romanesque","éclat rêvé","scène","grand amour idéalisé"],"essence":"Neptune en Lion idéalise l’éclat : le spectacle, la passion, la création. Une génération qui rêve en grand format ; chez une personne, l’imaginaire met de la mise en scène partout, et l’amour se vit volontiers comme un film.","light":["Imagination généreuse, tournée vers la fête et la création","Capacité à enchanter un moment ordinaire","Foi dans le talent des autres comme dans le sien"],"shadow":["Goût du grandiose qui supporte mal la banalité","Idéalisation des personnes admirées","Déception quand les applaudissements manquent"],"behaviors":["Organiser un simple dîner comme une première de théâtre","Tomber sous le charme d’un rôle plus que d’une personne","Raconter sa journée avec des pauses dramatiques"],"summary":{"soft":"Tu as le sens du merveilleux. Tu vois le potentiel de lumière dans les gens et les moments, et quand tu t’y mets, la vie ressemble un peu plus à une fête.","cash":"Tu vis ta vie comme une bande-annonce : musique forte, grands gestes, et tout le monde attend encore le film.","expert":"Neptune en Lion, signe fixe de feu, projette l’idéal sur la création, l’amour et la représentation de soi. Chez vous, l’imaginaire cherche l’éclat, et s’accommode mal du prosaïque."},"roastAngles":{"soft":["Tu mets des projecteurs sur les autres avec la même générosité que sur toi."],"cash":["Tu ne craques pas pour une personne, tu craques pour son générique d’ouverture.","Même pour annoncer que le lave-vaisselle est plein, tu ménages un effet de suspense."],"expert":["Neptune en Lion : idéalisation du geste créateur et du sentiment, au risque d’une théâtralité qui s’ignore."]},"roastWeight":0,"avoid":["Réduire le placement à de la vanité","Commenter l’apparence"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:libra', 'fr', '1', '{"keywords":["amour idéalisé","harmonie rêvée","paix","romantisme"],"essence":"Neptune en Balance idéalise le lien : le couple, l’accord, la paix entre les êtres. Une génération qui rêve d’harmonie ; chez une personne, l’imaginaire embellit l’autre, et le désaccord est flouté plutôt qu’affronté.","light":["Foi sincère dans la possibilité de s’entendre","Délicatesse dans la manière d’aborder l’autre","Sens esthétique qui adoucit les rapports"],"shadow":["Idéalisation du partenaire jusqu’à ne plus le voir","Conflits évités au prix d’un flou durable","Promesses d’accord faites pour préserver l’ambiance"],"behaviors":["Dire « tout va bien » avec un sourire très appliqué","Imaginer toute une histoire à partir d’un seul regard","Laisser l’autre choisir le restaurant pour éviter d’avoir un avis"],"summary":{"soft":"Tu crois à l’harmonie comme d’autres croient au printemps. Tu vois le meilleur chez l’autre, tu arrondis les angles, et ta douceur rend la rencontre possible.","cash":"Tu ne tombes pas sur des gens décevants : tu tombes sur des gens normaux que tu avais repeints en chefs-d’œuvre.","expert":"Neptune en Balance, signe cardinal d’air, porte l’idéal sur la relation et l’équilibre. Chez vous, l’autre est volontiers perçu à travers un filtre embellissant, et le conflit tend à se dissoudre dans le non-dit."},"roastAngles":{"soft":["Tu regardes les gens avec une lumière de fin d’après-midi : tout le monde y gagne."],"cash":["Tu as écrit toute la romance dans ta tête avant même que l’autre ait répondu « salut ».","Pour éviter une dispute, tu acceptes un compromis que personne n’avait demandé, toi compris."],"expert":["Neptune en Balance : idéalisation du partenaire et de la concorde, au détriment de la confrontation utile."]},"roastWeight":1,"avoid":["Annoncer une déception amoureuse","Juger les relations passées de la personne"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:pisces', 'fr', '1', '{"keywords":["fusion","compassion","imaginaire sans bord","évasion"],"essence":"Neptune en Poissons se trouve dans le signe qu’il gouverne : l’idéal, le rêve et la compassion s’y déploient sans retenue. Une génération très perméable aux ambiances ; chez une personne, l’imaginaire déborde, et la limite entre soi et les autres s’efface.","light":["Empathie spontanée, sans calcul","Imagination artistique abondante","Capacité à pardonner et à lâcher prise"],"shadow":["Évasion dès que le réel devient rugueux","Limites personnelles difficiles à poser","Tendance à absorber les émotions d’autrui"],"behaviors":["Pleurer devant une publicité pour des croquettes","Manquer sa station parce qu’une chanson était trop prenante","Dire oui à un service en espérant qu’il soit oublié"],"summary":{"soft":"Tu ressens le monde comme une mer : tout te traverse, tout te touche. Cette sensibilité immense est un don quand tu lui offres un rivage, une musique, une page, une présence.","cash":"Tu as les émotions de toute la rame de métro en plus des tiennes. Pas étonnant que tu regardes par la fenêtre.","expert":"Neptune en Poissons est en domicile : dissolution des limites, empathie et imaginaire s’y expriment pleinement. Chez vous, la sensibilité capte les ambiances collectives, et demande un cadre pour ne pas se diluer."},"roastAngles":{"soft":["Tu écoutes les gens comme la mer écoute les rivières : en leur faisant de la place."],"cash":["On te demande l’heure et tu réponds que le temps est une notion relative.","Tu as dit « j’arrive » avec une sincérité totale, depuis ton canapé, les yeux fermés."],"expert":["Neptune en Poissons, en domicile : perméabilité maximale, inspiration abondante, contours personnels à préciser."]},"roastWeight":1,"avoid":["Parler d’addiction, de fuite dans des substances ou de fragilité psychique","Réduire le placement à de la naïveté"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:sagittarius', 'fr', '1', '{"keywords":["quête de sens","ailleurs idéalisé","foi","grand récit"],"essence":"Neptune en Sagittaire idéalise le sens et le lointain : les voyages, les sagesses, les grandes explications. Une génération en quête d’une vérité plus vaste ; chez une personne, l’imaginaire regarde l’horizon, et l’ailleurs paraît plus lumineux qu’ici.","light":["Optimisme inspiré, tourné vers le large","Curiosité sincère pour les sagesses du monde","Capacité à donner du sens à une épreuve"],"shadow":["Croyance enthousiaste accordée trop vite","Ailleurs rêvé pour éviter l’ici","Grands principes aux contours imprécis"],"behaviors":["Revenir d’un stage d’un week-end avec une nouvelle philosophie de vie","Citer un proverbe lointain sans en connaître la provenance","Planifier un tour du monde sur un coin de nappe"],"summary":{"soft":"Tu as besoin de croire que la vie mène quelque part. Tu cherches du sens dans les voyages, les rencontres, les idées, et ton espérance élargit l’horizon de ceux qui t’écoutent.","cash":"Il te manque toujours une retraite, un livre ou un billet d’avion pour atteindre la révélation.","expert":"Neptune en Sagittaire, signe mutable de feu, porte l’idéal sur la quête de sens et les horizons lointains. Chez vous, l’imaginaire appelle une vision d’ensemble, parfois adoptée avant d’être examinée."},"roastAngles":{"soft":["Tu regardes une carte du monde comme d’autres regardent un ciel étoilé : avec confiance."],"cash":["Tu as trouvé le sens de la vie trois fois ce trimestre, et chaque version annulait la précédente.","Tu cites une sagesse ancestrale lue ce matin sur un sachet de tisane."],"expert":["Neptune en Sagittaire : idéalisation du lointain et du sens, avec une adhésion parfois plus rapide que l’examen."]},"roastWeight":1,"avoid":["Viser une croyance, une pratique spirituelle ou une confession précise","Traiter la personne de naïve"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:scorpio', 'fr', '1', '{"keywords":["mystère","fascination","profondeur rêvée","secret"],"essence":"Neptune en Scorpion idéalise la profondeur : le mystère, l’intensité, ce qui se cache sous la surface. Une génération attirée par l’invisible et les vérités enfouies ; chez une personne, l’imaginaire plonge, et le flou entoure les attachements les plus forts.","light":["Intuition fine des motivations cachées","Capacité à accompagner les autres dans leurs zones d’ombre","Imaginaire puissant, nourri de symboles"],"shadow":["Fascination pour ce qui est compliqué ou inaccessible","Soupçons construits sur des impressions","Attachements fusionnels aux contours flous"],"behaviors":["Préférer le personnage énigmatique à celui qui dit clairement ce qu’il veut","Deviner un secret, puis le garder comme un trésor","Écouter la même chanson sombre en boucle pendant une semaine"],"summary":{"soft":"Tu sens ce qui se passe sous la surface. Le mystère ne t’effraie pas, il t’appelle, et cette profondeur te permet de comprendre des choses que les autres n’osent pas dire.","cash":"Quelqu’un de simple, disponible et clair t’ennuie un peu. Il te faut une énigme, de préférence avec des chapitres manquants.","expert":"Neptune en Scorpion, signe fixe d’eau, porte l’idéal sur l’intensité et sur ce qui demeure caché. Chez vous, l’imaginaire s’attache aux profondeurs, et la fusion brouille les limites."},"roastAngles":{"soft":["Tu lis dans les silences comme d’autres lisent dans les livres, avec la même gourmandise."],"cash":["Tu trouves quelqu’un « mystérieux » alors qu’il a juste oublié de répondre à ton message.","Tu ne veux pas connaître quelqu’un : tu veux accéder à ses archives classées."],"expert":["Neptune en Scorpion : attrait pour le caché, où l’intuition psychologique côtoie la projection."]},"roastWeight":1,"avoid":["Tout vocabulaire de sexualité, de dépendance ou de disparition","Dramatiser l’attrait pour le mystère"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:taurus', 'fr', '1', '{"keywords":["idéal de simplicité","nature rêvée","confort sacralisé","sensorialité"],"essence":"Neptune en Taureau idéalise la matière : la terre, le confort, les choses bien faites. Une génération qui rêve d’abondance tranquille ; chez une personne, l’imaginaire s’attache aux sensations, et la valeur des choses se brouille facilement.","light":["Sens du geste artisanal et de la lenteur","Capacité à trouver de la poésie dans le quotidien matériel","Douceur apaisante pour l’entourage"],"shadow":["Attachement rêveur à des objets ou à des habitudes","Flou dans la gestion des ressources","Idéal de tranquillité qui évite tout effort de changement"],"behaviors":["Acheter un pain artisanal comme d’autres visitent un musée","Garder un objet cassé « pour sa valeur sentimentale »","Rêver d’une cabane à la campagne sans jamais regarder les annonces"],"summary":{"soft":"Tu rêves avec les mains et les sens. Un jardin, une matière, un repas partagé suffisent à nourrir ton imaginaire, et tu sais rendre le quotidien plus doux qu’il ne l’était.","cash":"Ton idéal de vie tient en une image : une table en bois, du soleil, personne qui te presse. Le reste, tu le remets à plus tard.","expert":"Neptune en Taureau, signe fixe de terre, attache l’idéal aux valeurs matérielles et sensorielles. Chez vous, l’imaginaire se fixe sur le tangible, au prix d’un certain flou dans l’évaluation des choses."},"roastAngles":{"soft":["Tu trouves du sacré dans une tomate bien mûre, et franchement, ça se défend."],"cash":["Tu appelles « besoin essentiel » une troisième couverture en laine, et tu y crois sincèrement.","Ta méditation préférée ressemble beaucoup à une sieste, mais avec une bougie parfumée à côté."],"expert":["Neptune en Taureau : idéalisation du confort et de la permanence, avec une estimation volontiers approximative."]},"roastWeight":0,"avoid":["Donner un conseil d’argent ou parler de dépenses réelles","Commenter l’alimentation ou le corps"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:neptune:virgo', 'fr', '1', '{"keywords":["idéal de service","perfection rêvée","doute","dévouement discret"],"essence":"Neptune en Vierge idéalise l’utile : le travail bien fait, le service, la pureté du détail. Une génération qui rêve d’un quotidien irréprochable ; chez une personne, l’idéal se loge dans les petites tâches, et le flou s’y glisse sous forme de doute.","light":["Dévouement concret, sans besoin de reconnaissance","Sens du détail mis au service d’un idéal","Humilité devant le travail à accomplir"],"shadow":["Idéal de perfection jamais atteint, donc toujours reproché","Doute qui grignote les décisions simples","Tendance à se sacrifier dans des tâches sans fin"],"behaviors":["Relire un message d’une ligne avant de l’envoyer, puis après","Proposer son aide avant d’avoir fini son propre travail","Ranger pour réfléchir, puis oublier à quoi"],"summary":{"soft":"Ton idéal a les manches retroussées. Tu rêves d’un monde où chaque chose serait à sa place et chaque personne aidée, et tu y travailles par de petits gestes patients.","cash":"Tu rêves d’une vie parfaitement organisée. En attendant, tu as trois listes, et aucune ne sait où est passée la quatrième.","expert":"Neptune en Vierge est en exil : l’idéal y rencontre l’exigence d’analyse. Chez vous, l’imaginaire se discipline par le service et la méthode, mais le doute brouille l’évaluation de vos propres efforts."},"roastAngles":{"soft":["Tu soignes les détails comme d’autres allument des bougies : c’est ta façon d’honorer le quotidien."],"cash":["Tu t’excuses d’une faute de frappe dans un message que personne n’avait encore ouvert.","Tu aides tout le monde à déménager, puis tu t’en veux d’avoir mal scotché un carton."],"expert":["Neptune en Vierge, en exil : l’idéal y devient scrupule, et la dévotion prend la forme du travail minutieux."]},"roastWeight":1,"avoid":["Glisser vers l’hypocondrie ou tout sujet médical","Présenter le doute comme une fragilité psychique"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:aquarius', 'fr', '1', '{"keywords":["collectif","détachement","amitié","contribution"],"essence":"Le Nœud Nord en Verseau indique une direction de croissance : contribuer à un projet commun, prendre du recul, traiter chacun en égal. Le réflexe ancien consiste à chercher les applaudissements et à vivre chaque remarque comme une affaire d’honneur.","light":["Sens du collectif en plein essor","Recul qui apaise l’amour-propre","Générosité tournée vers le projet plutôt que vers le rôle"],"shadow":["Besoin d’attention difficile à mettre en veille","Susceptibilité quand le premier rôle échappe","Habitude de prendre les choses personnellement"],"behaviors":["Vérifier combien de personnes ont réagi à sa publication","Ramener doucement la conversation vers sa propre anecdote","Découvrir le plaisir d’applaudir le succès de quelqu’un d’autre"],"summary":{"soft":"Ta route va vers les autres. Tu sais briller ; il s’agit maintenant de mettre cette chaleur au service d’un projet commun et de goûter la joie de compter parmi plusieurs.","cash":"Tu écoutes l’histoire de quelqu’un en préparant la tienne, qui est meilleure. Ton chemin : la garder pour plus tard.","expert":"Le Nœud Nord en Verseau oriente la croissance vers le collectif, l’amitié et la pensée détachée. L’axe invite à relativiser le besoin de reconnaissance personnelle au profit d’une contribution commune."},"roastAngles":{"soft":["Tu sais tenir la scène ; ta chance est de découvrir le bonheur de chanter dans le chœur."],"cash":["Tu offres un cadeau et tu surveilles le visage de l’autre comme un jury de concours.","Tu prends un « bof » sur le choix du restaurant comme une critique de l’ensemble de ton œuvre."],"expert":["Le Nœud Nord en Verseau : dépasser la quête d’approbation pour une participation égalitaire au groupe."]},"roastWeight":1,"avoid":["Traiter la personne d’égocentrique","Associer le collectif à un camp ou à une cause précise"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:aries', 'fr', '1', '{"keywords":["affirmation de soi","courage","autonomie","oser déplaire"],"essence":"Le Nœud Nord en Bélier indique une direction de croissance : apprendre à s’affirmer, à décider par soi-même et à passer en premier sans s’excuser. Le réflexe ancien consiste à s’ajuster aux autres jusqu’à ne plus savoir ce qui est voulu pour soi.","light":["Courage qui grandit à chaque décision prise pour soi","Franchise de plus en plus assumée","Capacité naissante à entreprendre sans validation"],"shadow":["Habitude de chercher l’accord de tous avant d’agir","Désirs personnels tus pour préserver la paix","Agacement rentré faute d’avoir dit non à temps"],"behaviors":["Demander l’avis de cinq personnes avant de choisir un plat","Répondre « peu importe » alors que la préférence existe bel et bien","S’excuser d’avoir un avis au moment de le donner"],"summary":{"soft":"Ta route va vers toi. Tu as appris à faire de la place aux autres ; il s’agit maintenant d’oser dire ce que tu veux, simplement, et de découvrir que le lien y résiste très bien.","cash":"Tu sais ce que tout le monde veut manger ce soir, sauf toi. Ton chemin tient en trois lettres : « moi ».","expert":"Le Nœud Nord en Bélier oriente la croissance vers l’autonomie et l’initiative. L’axe invite à quitter la recherche systématique de consensus pour assumer une volonté propre, quitte à déplaire."},"roastAngles":{"soft":["Tu as tant écouté les autres que ta propre voix mérite enfin le micro."],"cash":["Tu dis « ça m’est égal » alors que tu as déjà choisi, et tu boudes si personne ne devine.","Tu t’excuses quand quelqu’un te marche sur le pied, par réflexe et avec le sourire."],"expert":["Le Nœud Nord en Bélier : passer du compromis réflexe à la décision assumée, tel est l’apprentissage."]},"roastWeight":2,"avoid":["Encourager l’égoïsme ou la rupture d’une relation","Présenter la direction de croissance comme un destin écrit"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:cancer', 'fr', '1', '{"keywords":["tendresse","vulnérabilité","foyer","accueil des émotions"],"essence":"Le Nœud Nord en Cancer indique une direction de croissance : accueillir ses émotions, prendre soin, se créer un lieu où se poser. Le réflexe ancien consiste à tout maîtriser, à se définir par le travail et à tenir debout sans jamais rien demander.","light":["Tendresse qui apprend à se dire","Capacité grandissante à demander du soutien","Sens du foyer en construction"],"shadow":["Refuge dans le travail quand l’émotion monte","Besoin de garder le contrôle en toute circonstance","Pudeur qui passe pour de la froideur"],"behaviors":["Répondre « j’ai beaucoup de travail » à la question « comment ça va »","Organiser les vacances comme un projet avec livrables","Avoir du mal à accepter un plat préparé par quelqu’un d’autre"],"summary":{"soft":"Ta route va vers la douceur. Tu sais tenir, assumer, réussir ; il s’agit maintenant de te laisser toucher, de dire ce que tu ressens, et de découvrir qu’on peut s’appuyer sur quelqu’un.","cash":"Tu gères une crise au travail sans ciller, mais écrire « tu me manques » te demande trois brouillons.","expert":"Le Nœud Nord en Cancer oriente la croissance vers la vie affective, l’intime et le soin. L’axe invite à relâcher l’exigence de maîtrise et de statut pour reconnaître le besoin d’attachement."},"roastAngles":{"soft":["Tu portes beaucoup pour les autres ; ta chance est d’apprendre à te laisser porter un peu."],"cash":["Tu réponds « ça va, je gère » avec une valise dans chaque main et un carton sous le bras.","Tu as un plan pour tout, sauf pour le moment où quelqu’un te demande ce que tu ressens."],"expert":["Le Nœud Nord en Cancer : apprendre la vulnérabilité et l’intime, là où le devoir tenait lieu d’identité."]},"roastWeight":2,"avoid":["Conseiller de quitter un travail ou de fonder une famille","Supposer quoi que ce soit sur la famille réelle"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:capricorn', 'fr', '1', '{"keywords":["responsabilité","autonomie","construction","maturité"],"essence":"Le Nœud Nord en Capricorne indique une direction de croissance : prendre ses responsabilités, se fixer un cap et bâtir dans la durée. Le réflexe ancien consiste à se réfugier dans le cocon, à dépendre de l’humeur du moment et à attendre une prise en charge.","light":["Autorité intérieure qui se construit pas à pas","Fierté grandissante de tenir un engagement","Capacité à transformer la sensibilité en solidité"],"shadow":["Repli sur le cocon quand l’enjeu grandit","Décisions prises selon l’humeur du jour","Attente qu’un proche règle la situation"],"behaviors":["Appeler un parent avant de prendre une décision d’adulte","Annuler un engagement parce que « ce n’était pas le bon jour »","Découvrir la satisfaction d’un objectif tenu jusqu’au bout"],"summary":{"soft":"Ta route va vers la solidité. Tu as une sensibilité précieuse ; il s’agit maintenant de te faire confiance, de tenir un cap, et de devenir pour toi l’appui que tu cherchais ailleurs.","cash":"Tu as de grandes ambitions, juste après la sieste et si l’ambiance s’y prête. Ton chemin : y aller quand même.","expert":"Le Nœud Nord en Capricorne oriente la croissance vers la responsabilité, la structure et l’accomplissement. L’axe invite à quitter la dépendance affective et l’humeur pour l’engagement durable."},"roastAngles":{"soft":["Tu as le cœur tendre ; ta chance est de découvrir que tu as aussi les épaules."],"cash":["Tu repousses une échéance importante parce que la journée « ne le sentait pas ».","Tu postes ton formulaire à remplir dans le groupe de famille, au cas où quelqu’un s’en chargerait."],"expert":["Le Nœud Nord en Capricorne : apprendre l’autonomie et la tenue dans le temps, au-delà du besoin de protection."]},"roastWeight":2,"avoid":["Donner un conseil de carrière","Traiter la personne d’immature"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:gemini', 'fr', '1', '{"keywords":["curiosité","écoute","légèreté","questions"],"essence":"Le Nœud Nord en Gémeaux indique une direction de croissance : poser des questions, écouter, s’intéresser au détail et au voisin de table. Le réflexe ancien consiste à détenir la vérité, à généraliser et à préférer les grandes théories aux échanges réels.","light":["Curiosité qui s’ouvre aux points de vue différents","Souplesse d’esprit en progrès constant","Plaisir croissant de la conversation simple"],"shadow":["Habitude de conclure avant d’avoir écouté","Certitudes servies comme des évidences","Impatience devant les nuances et les détails"],"behaviors":["Répondre par un grand principe à une question pratique","Donner un avis définitif sur un livre lu à moitié","Découvrir qu’une question bien posée apprend plus qu’un exposé"],"summary":{"soft":"Ta route va vers la curiosité. Tu as le sens des grandes vérités ; il s’agit maintenant d’écouter, de demander, de laisser les autres t’apprendre quelque chose que tu ne savais pas.","cash":"On te demande où est la gare et tu réponds par ta philosophie du voyage. Ton chemin : la réponse courte.","expert":"Le Nœud Nord en Gémeaux oriente la croissance vers l’échange, la curiosité et la pensée nuancée. L’axe invite à passer de la conviction globale à l’information précise et au dialogue."},"roastAngles":{"soft":["Tu as beaucoup de réponses ; ta chance est de découvrir le plaisir des questions."],"cash":["Tu commences par « en fait, c’est très simple », et vingt minutes plus tard personne n’a pu parler.","Tu as un avis tranché sur un pays où tu as fait une escale de deux heures."],"expert":["Le Nœud Nord en Gémeaux : troquer la certitude doctrinale contre la curiosité et l’écoute du particulier."]},"roastWeight":1,"avoid":["Viser les convictions ou croyances de la personne","Présenter la légèreté comme de la superficialité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:leo', 'fr', '1', '{"keywords":["oser briller","créativité","cœur","place personnelle"],"essence":"Le Nœud Nord en Lion indique une direction de croissance : prendre sa place, créer, se montrer et parler avec le cœur. Le réflexe ancien consiste à se fondre dans le groupe, à observer de loin et à préférer l’idée à l’élan.","light":["Joie qui grandit quand elle s’exprime","Créativité personnelle en plein éveil","Chaleur capable d’entraîner un groupe"],"shadow":["Habitude de se cacher derrière le collectif","Détachement affiché pour éviter de s’exposer","Compliments reçus avec gêne puis écartés"],"behaviors":["Proposer une idée en commençant par « quelqu’un devrait »","Répondre à un compliment en parlant du travail des autres","S’installer au fond de la salle par réflexe"],"summary":{"soft":"Ta route va vers la lumière. Tu sais te fondre dans un groupe ; il s’agit maintenant d’oser te montrer, de créer quelque chose qui te ressemble et d’y mettre tout ton cœur.","cash":"Tu as un talent évident et une technique très au point pour que personne ne le remarque.","expert":"Le Nœud Nord en Lion oriente la croissance vers l’expression personnelle, la création et l’engagement du cœur. L’axe invite à quitter la réserve du collectif pour assumer une place singulière."},"roastAngles":{"soft":["Tu as une lumière que tu ranges trop souvent dans un tiroir ; elle mérite une lampe."],"cash":["On te félicite et tu réponds « c’est surtout grâce à l’équipe », alors que tu as travaillé sans personne.","Tu fais un cadeau magnifique et tu le signes « de la part de tout le monde »."],"expert":["Le Nœud Nord en Lion : passer de la neutralité du groupe à l’affirmation créatrice, voilà l’enjeu de l’axe."]},"roastWeight":2,"avoid":["Encourager la vanité ou la recherche d’attention","Commenter l’apparence"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:libra', 'fr', '1', '{"keywords":["coopération","écoute de l’autre","diplomatie","partage"],"essence":"Le Nœud Nord en Balance indique une direction de croissance : coopérer, écouter, tenir compte de l’autre et bâtir à deux. Le réflexe ancien consiste à foncer en solitaire, à décider vite pour soi et à vivre la concession comme une défaite.","light":["Sens du partenariat en plein apprentissage","Tact qui adoucit une franchise naturelle","Capacité grandissante à demander un avis"],"shadow":["Habitude de tout faire sans personne pour aller plus vite","Impatience devant la lenteur des autres","Réflexe de trancher avant d’avoir consulté"],"behaviors":["Annoncer une décision commune déjà prise en solo","Finir le travail de groupe pendant que le groupe en discute encore","Marcher dix mètres devant les autres dans la rue"],"summary":{"soft":"Ta route va vers l’autre. Tu sais avancer sans attendre personne ; il s’agit maintenant de ralentir d’un pas, d’écouter, et de découvrir qu’à deux le chemin mène plus loin.","cash":"Tu dis « on en parle » une fois que tout est réservé, payé et confirmé. Ton chemin : demander avant.","expert":"Le Nœud Nord en Balance oriente la croissance vers la relation, la coopération et la recherche d’équilibre. L’axe invite à tempérer l’initiative solitaire par la prise en compte d’autrui."},"roastAngles":{"soft":["Tu sais très bien avancer ; ta chance est de découvrir la joie d’attendre quelqu’un."],"cash":["Tu demandes « on fait quoi ce soir ? » avec les billets déjà dans la poche.","Tu appelles « travail d’équipe » le moment où les autres valident ce que tu as fini hier."],"expert":["Le Nœud Nord en Balance : apprendre l’accord et la réciprocité, là où primait l’élan individuel."]},"roastWeight":2,"avoid":["Annoncer une rencontre ou une mise en couple","Encourager à s’effacer devant l’autre"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:pisces', 'fr', '1', '{"keywords":["lâcher-prise","confiance","compassion","intuition"],"essence":"Le Nœud Nord en Poissons indique une direction de croissance : lâcher prise, faire confiance, accueillir ce qui ne se mesure pas. Le réflexe ancien consiste à tout vérifier, à corriger chaque détail et à s’inquiéter de ce qui pourrait ne pas être parfait.","light":["Intuition qui gagne en assurance","Indulgence grandissante envers soi et les autres","Capacité à laisser venir sans tout prévoir"],"shadow":["Contrôle du détail au détriment de l’ensemble","Autocritique rarement en repos","Difficulté à supporter l’imprévu"],"behaviors":["Refaire une liste parce que l’ancienne était mal alignée","Relire un itinéraire déjà connu par cœur avant de partir","Découvrir qu’une journée sans programme peut très bien se passer"],"summary":{"soft":"Ta route va vers la confiance. Tu sais analyser, organiser, améliorer ; il s’agit maintenant de desserrer les mains, d’écouter ton intuition et de laisser la vie faire une part du travail.","cash":"Tu as un plan, un plan de rechange et un tableau pour comparer les deux. Ton chemin : poser le stylo.","expert":"Le Nœud Nord en Poissons oriente la croissance vers l’abandon confiant, la compassion et l’intuition. L’axe invite à relâcher l’exigence d’analyse et de contrôle du détail."},"roastAngles":{"soft":["Tu as pensé à tout, sauf à la douceur de ne penser à rien ; elle patiente sans rancune."],"cash":["Tu prépares une soirée détente avec un minutage précis et un point d’étape à mi-parcours.","Tu lâches prise, oui, mais d’abord tu notes quand, comment et jusqu’à quelle heure."],"expert":["Le Nœud Nord en Poissons : passer du tri au tout, de la vérification à la confiance, sans perdre le discernement."]},"roastWeight":2,"avoid":["Tout sujet médical ou d’inquiétude présentée comme un diagnostic","Viser une croyance ou une spiritualité précise"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:sagittarius', 'fr', '1', '{"keywords":["vision d’ensemble","confiance","aventure","sens"],"essence":"Le Nœud Nord en Sagittaire indique une direction de croissance : prendre de la hauteur, se fier à son intuition, partir voir plus loin. Le réflexe ancien consiste à accumuler les informations, à peser chaque avis et à tourner autour de la décision.","light":["Confiance qui grandit en osant choisir","Goût de l’aventure en train de s’éveiller","Capacité à dégager l’essentiel du détail"],"shadow":["Dispersion entre mille informations contradictoires","Besoin de consulter tout le monde avant de trancher","Bavardage qui remplace la décision"],"behaviors":["Comparer douze avis en ligne avant d’acheter une bouilloire","Solliciter l’avis de tout le voisinage sur une question déjà résolue","Découvrir qu’un départ improvisé se passe très bien"],"summary":{"soft":"Ta route va vers le large. Tu sais t’informer, comparer, discuter ; il s’agit maintenant de te fier à ce que tu sens, de choisir une direction et d’oser partir sans tout savoir.","cash":"Tu as lu tous les avis, comparé toutes les options et ouvert vingt onglets. Ton chemin : en fermer dix-neuf.","expert":"Le Nœud Nord en Sagittaire oriente la croissance vers la vision d’ensemble, la conviction et l’exploration. L’axe invite à dépasser l’accumulation d’informations pour dégager un sens et s’y tenir."},"roastAngles":{"soft":["Tu as toutes les cartes en main ; ta chance est d’oser enfin choisir une route."],"cash":["Tu fais un sondage auprès de six personnes pour savoir si tu as vraiment envie d’y aller.","Tu connais les horaires, les tarifs et la météo du voyage que tu n’as toujours pas réservé."],"expert":["Le Nœud Nord en Sagittaire : passer de la collecte de faits à la conviction, du commentaire à l’engagement."]},"roastWeight":1,"avoid":["Annoncer un voyage ou un départ","Viser une croyance précise"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:scorpio', 'fr', '1', '{"keywords":["profondeur","lâcher le confort","confiance partagée","transformation"],"essence":"Le Nœud Nord en Scorpion indique une direction de croissance : aller au fond des choses, partager vraiment, accepter de changer. Le réflexe ancien consiste à s’accrocher au confort, aux habitudes et à ce qui est acquis, quitte à éviter tout ce qui remue.","light":["Courage émotionnel qui se découvre peu à peu","Capacité à lâcher ce qui ne sert plus","Intimité de plus en plus authentique"],"shadow":["Attachement aux habitudes par peur du changement","Tendance à tout garder pour soi, objets comme sentiments","Résistance passive devant une conversation délicate"],"behaviors":["Changer de sujet dès qu’une discussion devient sérieuse","Garder un vieux pull, un vieux poste et une vieille opinion par confort","Dire « tout est très bien comme ça » en regardant ailleurs"],"summary":{"soft":"Ta route va vers la profondeur. Tu sais créer du confort ; il s’agit maintenant d’oser les vraies conversations, de partager ce qui compte, et de te laisser transformer par ce que tu vis.","cash":"Dès qu’une discussion devient sérieuse, tu proposes de reprendre du dessert. Ton chemin passe après le dessert.","expert":"Le Nœud Nord en Scorpion oriente la croissance vers l’engagement émotionnel, le partage et la transformation. L’axe invite à desserrer l’attachement au confort et à l’acquis."},"roastAngles":{"soft":["Tu construis des abris solides ; ta chance est d’oser en sortir quand le vent t’appelle."],"cash":["Tu réponds « on est bien, là, non ? » à quelqu’un qui venait de dire « il faut qu’on parle ».","Tu gardes le même fauteuil, le même plat et le même avis depuis toujours, par principe de précaution."],"expert":["Le Nœud Nord en Scorpion : consentir à la crise féconde et au partage, plutôt qu’à la conservation."]},"roastWeight":2,"avoid":["Tout vocabulaire de sexualité, de perte ou de disparition","Donner un conseil d’argent ou de patrimoine"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:taurus', 'fr', '1', '{"keywords":["simplicité","stabilité","confiance en ses ressources","calme"],"essence":"Le Nœud Nord en Taureau indique une direction de croissance : construire du simple, du stable, du tangible, et s’appuyer sur ses propres ressources. Le réflexe ancien consiste à chercher l’intensité et les situations compliquées pour se sentir vivre.","light":["Goût grandissant pour ce qui dure","Capacité à se rassurer par des gestes concrets","Patience qui s’apprend et finit par payer"],"shadow":["Attirance pour les situations dramatiques","Méfiance devant ce qui se passe trop bien","Tendance à tout remettre en jeu quand le calme s’installe"],"behaviors":["Chercher le problème caché dans une journée sans histoire","Compliquer un projet simple pour le rendre intéressant","Découvrir avec surprise le plaisir d’un dimanche où rien n’arrive"],"summary":{"soft":"Ta route va vers la paix. Tu connais bien les tempêtes ; il s’agit maintenant de te fier à ce qui est simple, de bâtir doucement, et de goûter ce que tu as sans craindre de le perdre.","cash":"Quand tout va bien, tu trouves ça louche. Ton chemin : apprendre qu’une soirée calme n’est pas un piège.","expert":"Le Nœud Nord en Taureau oriente la croissance vers la stabilité, la valeur propre et le rapport simple au concret. L’axe invite à délaisser la logique de crise pour celle de la construction patiente."},"roastAngles":{"soft":["Tu as le droit de te sentir bien sans raison, et de laisser le calme durer plus d’une soirée."],"cash":["Tu te méfies d’une relation sans drame comme d’un contrat sans petites lignes.","Tu appelles « ennui » ce que les autres appellent « une semaine normale »."],"expert":["Le Nœud Nord en Taureau : apprendre la permanence et la suffisance, contre l’attrait de l’intensité."]},"roastWeight":1,"avoid":["Donner un conseil d’argent","Supposer un passé douloureux ou des crises réelles"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:north_node:virgo', 'fr', '1', '{"keywords":["concret","méthode","discernement","service utile"],"essence":"Le Nœud Nord en Vierge indique une direction de croissance : ordonner, trier, s’occuper du concret et rendre service utilement. Le réflexe ancien consiste à se laisser porter, à rêver la solution et à attendre que les choses s’arrangent d’elles-mêmes.","light":["Discernement qui s’affine avec la pratique","Satisfaction croissante du travail bien fini","Capacité à transformer une intuition en méthode"],"shadow":["Flou entretenu pour éviter de choisir","Habitude de s’en remettre au hasard","Retards expliqués par de très bonnes histoires"],"behaviors":["Compter sur l’inspiration pour remplir un formulaire","Retrouver ses clés grâce à une intuition plutôt qu’à un rangement","Découvrir le plaisir inattendu d’une liste entièrement cochée"],"summary":{"soft":"Ta route va vers le concret. Tu as une intuition immense ; il s’agit maintenant de lui donner des mains, un ordre, un rythme, et de voir tes rêves prendre forme au quotidien.","cash":"Tu fais confiance à l’univers pour tes dossiers administratifs. L’univers, lui, attend toujours la pièce jointe.","expert":"Le Nœud Nord en Vierge oriente la croissance vers la méthode, le discernement et le service concret. L’axe invite à quitter le flou et la remise à plus tard pour l’organisation du réel."},"roastAngles":{"soft":["Tu as des rêves immenses ; ta chance est d’apprendre à leur donner un agenda."],"cash":["Tu réponds « ça se fera tout seul » à propos d’une chose qui ne s’est jamais faite toute seule.","Tu arrives en retard avec une explication si poétique que personne n’ose regarder sa montre."],"expert":["Le Nœud Nord en Vierge : donner forme et rigueur à ce qui demeurait intuition, sans renoncer à la sensibilité."]},"roastWeight":1,"avoid":["Tout sujet médical ou d’hygiène de vie","Opposer rêve et sérieux comme si l’un valait moins que l’autre"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:aquarius', 'fr', '1', '{"keywords":["collectif transformé","idées radicales","réseaux","indépendance farouche"],"essence":"Pluton en Verseau concentre l’intensité sur le collectif, les idées et les réseaux. Une génération qui transforme les façons de faire société ; chez une personne, le besoin de maîtrise passe par l’indépendance d’esprit et l’influence au sein du groupe.","light":["Vision capable de réinventer un fonctionnement commun","Fidélité profonde à ses idéaux","Lucidité sur les dynamiques de groupe"],"shadow":["Certitude froide d’avoir compris avant les autres","Emprise par les idées plutôt que par les sentiments","Détachement utilisé pour garder le contrôle"],"behaviors":["Quitter un groupe par principe, avec un texte d’explication argumenté","Analyser les rapports d’influence d’une simple bande de copains","Défendre une idée impopulaire jusqu’à ce qu’elle devienne la règle"],"summary":{"soft":"Tu portes une exigence profonde pour le collectif. Tu vois ce qui pourrait fonctionner autrement entre les gens, et ta fidélité à tes idées donne de la portée à ta parole.","cash":"Tu observes le groupe de loin, tu comprends qui influence qui, et tu fais semblant de n’y attacher aucune importance.","expert":"Pluton en Verseau, signe fixe d’air, porte la transformation sur le collectif et les systèmes d’idées. Chez vous, le rapport au pouvoir se joue dans le groupe : influence, indépendance, adhésion."},"roastAngles":{"soft":["Tu crois aux idées qui changent les règles du jeu, et tu sais attendre qu’elles fassent leur chemin."],"cash":["Tu ne cherches pas à diriger le groupe : tu veux juste en avoir écrit le règlement.","Tu te tiens à l’écart de la conversation, puis tu la résumes mieux que ceux qui y étaient."],"expert":["Pluton en Verseau : pouvoir des idées et des réseaux, intensité intellectualisée, attachement tenu à distance."]},"roastWeight":0,"avoid":["Associer le placement à un camp, à une idéologie ou à une prédiction de société","Présenter le détachement comme de l’insensibilité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:aries', 'fr', '1', '{"keywords":["volonté radicale","commencement","combat intérieur","affirmation"],"essence":"Pluton en Bélier concentre l’intensité sur l’affirmation de soi : une génération qui transforme le monde en osant y entrer de force. Chez une personne, le besoin de maîtrise passe par l’initiative, et chaque blocage devient une affaire personnelle.","light":["Volonté capable de repartir de zéro","Courage devant les situations que d’autres jugent perdues","Instinct pour déclencher un changement nécessaire"],"shadow":["Rapport de force engagé au moindre obstacle","Difficulté à céder, même sur un détail","Impatience qui force les transformations"],"behaviors":["Transformer une simple partie de cartes en affaire d’honneur","Recommencer un projet depuis le début plutôt que le corriger","Prendre la tête d’un groupe sans attendre la moindre invitation"],"summary":{"soft":"Il y a en toi une force de commencement très profonde. Quand tout semble figé, tu trouves l’énergie de rouvrir une voie, et cette volonté entraîne ceux qui n’osaient plus.","cash":"Tu ne veux pas gagner, tu veux qu’il soit bien clair que personne ne t’a laissé gagner.","expert":"Pluton en Bélier, placement générationnel, lie la transformation à l’affirmation individuelle. Chez vous, le rapport au pouvoir se joue dans l’initiative et la capacité à imposer un commencement."},"roastAngles":{"soft":["Tu as cette flamme obstinée qui rallume le feu quand tout le monde croyait la soirée finie."],"cash":["Tu abordes une partie de jeu de société avec le regard de quelqu’un qui défend un territoire.","Quand on te dit « c’est impossible », tu entends surtout une invitation personnelle."],"expert":["Pluton en Bélier : la volonté s’y exerce par la percée, et tolère mal la résistance d’autrui."]},"roastWeight":0,"avoid":["Parler de violence ou d’agressivité comme d’un fait","Tout vocabulaire de disparition ou de sexualité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:cancer', 'fr', '1', '{"keywords":["clan","protection farouche","mémoire","attachement"],"essence":"Pluton en Cancer concentre l’intensité sur le foyer et l’appartenance. Une génération marquée par la transformation des familles et des racines ; chez une personne, le besoin de maîtrise prend la forme d’une protection sans relâche des siens.","light":["Loyauté indéfectible envers le cercle proche","Force de protection dans les moments difficiles","Mémoire affective qui soude un groupe"],"shadow":["Emprise affective au nom du soin","Difficulté à laisser les proches s’éloigner","Vieux griefs gardés intacts"],"behaviors":["Demander un message à l’arrivée, même pour un trajet de dix minutes","Nourrir tout le monde, y compris ceux qui n’ont pas faim","Ressortir un vieux reproche de famille pendant le repas de fête"],"summary":{"soft":"Tu aimes avec une force de racine. Les tiens peuvent compter sur toi dans la tempête, et cette fidélité fait de toi un abri, pourvu que tu laisses la porte ouverte.","cash":"Tu protèges les tiens comme un coffre-fort protège des bijoux : avec amour, et sans leur demander leur avis.","expert":"Pluton en Cancer, signe cardinal d’eau, porte la transformation sur la famille et la sécurité affective. Chez vous, l’intensité s’exprime par l’attachement, avec un enjeu de contrôle au sein du cercle intime."},"roastAngles":{"soft":["Tu gardes les tiens au chaud avec une constance qui tient tête à tous les hivers."],"cash":["Tu dis « fais comme tu veux » avec la voix de quelqu’un qui a déjà préparé la chambre.","Tu ressers du gratin à des gens qui ont posé leur fourchette depuis longtemps."],"expert":["Pluton en Cancer : l’attachement y devient un enjeu absolu, d’où une protection volontiers enveloppante."]},"roastWeight":0,"avoid":["Supposer une histoire familiale douloureuse","Tout vocabulaire de perte ou de disparition"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:capricorn', 'fr', '1', '{"keywords":["ambition profonde","structures transformées","maîtrise","endurance"],"essence":"Pluton en Capricorne concentre l’intensité sur l’ambition, les structures et l’autorité. Une génération qui voit les cadres établis se transformer ; chez une personne, le besoin de maîtrise passe par la compétence, la durée et le contrôle de sa trajectoire.","light":["Détermination qui tient sur la longue distance","Sens des responsabilités dans les moments critiques","Capacité à rebâtir une structure sur des bases saines"],"shadow":["Contrôle exercé par la retenue et le silence","Travail utilisé comme une armure","Difficulté à montrer une faille"],"behaviors":["Répondre « ça avance » à toute question personnelle","Préparer un plan de secours pour le plan de secours","Travailler pendant les vacances « juste pour garder la main »"],"summary":{"soft":"Tu as une force de fond, patiente et sérieuse. Tu sais ce que coûte une chose bien construite, et ta détermination transforme lentement mais sûrement ce que tu prends en charge.","cash":"Tu te détends très bien, à condition d’avoir un objectif de détente et un moyen de mesurer le résultat.","expert":"Pluton en Capricorne, signe cardinal de terre, porte la transformation sur les structures de pouvoir et la réussite sociale. Chez vous, l’intensité prend la forme de l’ambition contenue et de la maîtrise de soi."},"roastAngles":{"soft":["Tu portes beaucoup sans le dire, avec une solidité qui rassure tout le monde autour."],"cash":["Tu réponds « je gère » avec le calme de quelqu’un qui a déjà trois scénarios de repli.","Tu ne demandes pas d’aide : tu attends d’avoir fini pour dire que c’était un peu lourd."],"expert":["Pluton en Capricorne : volonté de maîtrise appliquée à la carrière et au statut, émotion tenue sous contrôle."]},"roastWeight":1,"avoid":["Donner un conseil de carrière ou d’argent","Commenter des institutions ou des opinions"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:gemini', 'fr', '1', '{"keywords":["parole qui transforme","curiosité obstinée","enquête","idées puissantes"],"essence":"Pluton en Gémeaux concentre l’intensité sur l’esprit : savoir, parole, information. Une génération pour qui les idées changent le cours des choses ; chez une personne, le besoin de maîtrise passe par ce qu’elle sait et par ce qu’elle choisit de dire.","light":["Esprit d’enquête qui va au bout d’une question","Parole capable de faire basculer une discussion","Capacité à changer en profondeur de façon de penser"],"shadow":["Usage de l’information comme d’un levier","Questions insistantes qui virent à l’interrogatoire","Pensées qui tournent en boucle sans s’arrêter"],"behaviors":["Poser « juste une dernière question » six fois de suite","Lire toute la discussion d’un groupe avant d’y écrire un seul mot","Retenir mot pour mot une phrase dite à la légère"],"summary":{"soft":"Ton esprit ne se contente pas de la surface. Tu cherches le mot exact, la vraie raison, et quand tu parles, tes phrases ont le pouvoir de déplacer quelque chose chez l’autre.","cash":"Tu poses une question anodine, puis onze autres. À la fin, l’autre a tout avoué sans savoir quoi.","expert":"Pluton en Gémeaux, signe mutable d’air, porte la transformation sur le mental et la communication. Chez vous, le rapport au pouvoir passe par l’information : la détenir, la relier, la formuler."},"roastAngles":{"soft":["Tu poses les questions qui font réfléchir longtemps après que la conversation est finie."],"cash":["Tu te souviens d’une phrase que l’autre a dite en passant, et tu la ressors avec le jour et l’heure.","Tu lis les conditions d’utilisation en entier, au cas où quelqu’un te cacherait quelque chose."],"expert":["Pluton en Gémeaux : la curiosité y devient enquête, et le verbe un instrument d’influence."]},"roastWeight":0,"avoid":["Parler de manipulation comme d’un trait de la personne","Évoquer des pensées obsédantes sur un mode médical"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:leo', 'fr', '1', '{"keywords":["fierté","pouvoir créateur","rayonnement intense","autorité personnelle"],"essence":"Pluton en Lion concentre l’intensité sur l’affirmation et la création. Une génération qui transforme le rapport à l’individu et à son pouvoir ; chez une personne, le besoin de maîtrise passe par la fierté, le rôle tenu et la marque laissée.","light":["Force créatrice qui va jusqu’au bout de son geste","Générosité protectrice envers les siens","Capacité à se relever avec panache"],"shadow":["Orgueil qui transforme un désaccord en affront","Besoin de garder le premier rôle","Difficulté à reconnaître une erreur en public"],"behaviors":["Refuser de demander son chemin par principe","Organiser la fête, choisir la musique et placer les invités","Raconter un échec comme une victoire stratégique"],"summary":{"soft":"Tu as un cœur entier et une présence qui compte. Quand tu crois en quelque chose ou en quelqu’un, tu y mets toute ta force, et cette ardeur réchauffe largement autour de toi.","cash":"Tu acceptes très bien la critique, à condition qu’elle arrive avec des fleurs et commence par un compliment.","expert":"Pluton en Lion, signe fixe de feu, porte la transformation sur l’identité et la puissance créatrice. Chez vous, le rapport au pouvoir est personnel : il engage la fierté et le besoin de reconnaissance."},"roastAngles":{"soft":["Tu donnes à ceux que tu aimes une place au premier rang, et tu ne la reprends pas."],"cash":["Tu reconnais une erreur environ une fois par décennie, et tu attends qu’on salue le geste.","Tu délègues volontiers, puis tu refais tout derrière, « juste pour harmoniser »."],"expert":["Pluton en Lion : volonté de puissance créatrice, où l’amour-propre devient le point sensible."]},"roastWeight":1,"avoid":["Traiter la personne de tyrannique ou d’égocentrique","Commenter l’apparence"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:libra', 'fr', '1', '{"keywords":["relations intenses","justice","rapport de force feutré","engagement"],"essence":"Pluton en Balance concentre l’intensité sur le lien : couple, alliance, équité. Une génération qui transforme les règles de l’engagement ; chez une personne, le besoin de maîtrise s’exprime en douceur, par la négociation et le souci de l’équilibre.","light":["Sens aigu de la justice dans les relations","Capacité à transformer un conflit en accord","Engagement profond une fois le lien choisi"],"shadow":["Contrôle exercé sous couvert de gentillesse","Comptabilité silencieuse de qui a donné quoi","Difficulté à supporter le désaccord ouvert"],"behaviors":["Tenir mentalement le compte exact des services rendus","Obtenir gain de cause en laissant l’autre croire que l’idée venait de lui","Rouvrir une discussion close parce qu’elle n’était « pas équitable »"],"summary":{"soft":"Tu prends les liens très au sérieux. Derrière ta douceur, il y a une exigence de justice et de vérité à deux qui rend tes relations profondes et capables d’évoluer.","cash":"Tu ne t’énerves jamais. Tu souris, tu reformules, et à la fin tout le monde fait ce que tu avais prévu.","expert":"Pluton en Balance, signe cardinal d’air, porte la transformation sur la relation et le contrat. Chez vous, le rapport de force existe mais demeure feutré : il passe par la négociation et l’exigence d’équité."},"roastAngles":{"soft":["Tu cherches la justesse dans chaque lien, avec une patience d’orfèvre."],"cash":["Tu sais exactement qui a payé le dernier café, et tu attends avec élégance que ça se rééquilibre.","Tu dis « on décide ensemble » en tendant une liste où il ne reste qu’une option."],"expert":["Pluton en Balance : pouvoir exercé par l’accord et la mesure, intensité relationnelle sous des dehors policés."]},"roastWeight":1,"avoid":["Annoncer une rupture ou juger la vie de couple","Tout conseil d’ordre juridique"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:pisces', 'fr', '1', '{"keywords":["dissolution","compassion profonde","foi","lâcher-prise"],"essence":"Pluton en Poissons concentre l’intensité sur l’imaginaire, la compassion et l’invisible. Une génération qui transforme en dissolvant plutôt qu’en affrontant ; chez une personne, la maîtrise passe paradoxalement par l’abandon et la confiance.","light":["Compassion qui va jusqu’au fond des choses","Capacité à se transformer en lâchant prise","Intuition puissante des courants collectifs"],"shadow":["Sacrifice de soi utilisé comme moyen d’influence","Fuite devant les rapports de force","Émotions envahissantes, difficiles à nommer"],"behaviors":["Tout donner à une cause, puis disparaître quelques jours pour récupérer","Pressentir l’ambiance d’une pièce avant d’y entrer","Céder dans une dispute et l’emporter par la douceur"],"summary":{"soft":"Ta force est une force d’eau : elle ne casse rien, elle transforme en profondeur. Tu ressens intensément ce qui relie les êtres, et tu sais changer en acceptant de lâcher.","cash":"Tu ne luttes pas, tu infuses. Trois semaines plus tard, tout le monde fait comme toi sans savoir pourquoi.","expert":"Pluton en Poissons, signe mutable d’eau, porte la transformation sur la sensibilité collective et l’imaginaire. Chez vous, l’intensité agit par imprégnation, et le contrôle cède la place à la dissolution."},"roastAngles":{"soft":["Tu changes les choses comme la marée change le rivage : sans bruit, mais pour de bon."],"cash":["Tu dis « ce n’est pas grave » avec une douceur telle que l’autre culpabilise toute la semaine.","Tu te dévoues corps et âme, et tu fais discrètement savoir que c’était corps et âme."],"expert":["Pluton en Poissons : intensité diffuse, pouvoir par l’abnégation, transformation vécue comme un abandon."]},"roastWeight":0,"avoid":["Viser une croyance ou une spiritualité précise","Tout vocabulaire de disparition, de perte ou de fragilité psychique"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:sagittarius', 'fr', '1', '{"keywords":["convictions profondes","quête de vérité","horizons transformés","franc-parler"],"essence":"Pluton en Sagittaire concentre l’intensité sur les convictions, le savoir et l’ailleurs. Une génération qui transforme les croyances et élargit le monde ; chez une personne, le besoin de maîtrise passe par la certitude d’avoir trouvé le sens.","light":["Soif de vérité qui ne se contente pas de réponses toutes faites","Capacité à changer radicalement de vision","Franchise entraînante"],"shadow":["Convictions défendues comme des territoires","Besoin d’avoir raison jusqu’au bout de la nuit","Tendance à prêcher plutôt qu’à écouter"],"behaviors":["Envoyer un long article à toute la famille avec la mention « à lire absolument »","Transformer un apéritif en débat de fond","Partir loin pour « comprendre quelque chose », sans préciser quoi"],"summary":{"soft":"Tu cherches le sens avec une ardeur entière. Quand une idée te touche, elle te transforme vraiment, et ta soif de vérité pousse les autres à regarder plus loin.","cash":"Tu n’as pas des opinions, tu as des missions. Et le dîner n’est pas fini tant que la tablée n’est pas convaincue.","expert":"Pluton en Sagittaire, signe mutable de feu, porte la transformation sur les croyances et les systèmes de sens. Chez vous, l’intensité s’attache à la conviction, avec un enjeu de pouvoir autour de la vérité."},"roastAngles":{"soft":["Tu poursuis la vérité comme un grand voyage, et tu envoies des nouvelles en chemin."],"cash":["Tu commences par « je ne veux pas te convaincre », et quarante minutes plus tard, si.","Tu as changé de vision du monde, et tes proches ont reçu le communiqué à l’aube."],"expert":["Pluton en Sagittaire : conviction vécue comme un absolu, où la quête de sens peut se durcir en doctrine."]},"roastWeight":1,"avoid":["Viser une croyance, une confession ou une opinion précise","Traiter la personne de fanatique"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:scorpio', 'fr', '1', '{"keywords":["tout ou rien","profondeur","métamorphose","secret"],"essence":"Pluton en Scorpion se trouve dans le signe qu’il gouverne : intensité, secret et transformation y sont à leur comble. Une génération qui regarde en face ce qui est caché ; chez une personne, tout se vit à fond, et la maîtrise de soi devient un enjeu central.","light":["Lucidité psychologique peu commune","Capacité à traverser une crise et à en sortir autrement","Loyauté absolue une fois la confiance donnée"],"shadow":["Méfiance qui met chaque proche à l’épreuve","Contrôle des informations livrées sur soi","Rancune conservée avec méthode"],"behaviors":["Tout savoir sur quelqu’un avant la première rencontre, sans avoir posé une question","Répondre « rien » quand quelque chose ne va manifestement pas","Couper les ponts sans un mot, puis ne jamais revenir dessus"],"summary":{"soft":"Tu vis les choses en profondeur, sans demi-teinte. Cette intensité te donne une force de transformation rare : tu sais muer, repartir, et reconnaître la vérité quand elle se présente.","cash":"Tu fais confiance après une enquête complète, trois mises à l’épreuve et une période d’observation.","expert":"Pluton en Scorpion est en domicile : ses significations de profondeur, de contrôle et de métamorphose s’y expriment pleinement. Chez vous, l’intensité est une norme, et la confiance s’accorde par étapes."},"roastAngles":{"soft":["Tu vois clair dans les gens, et tu as la délicatesse de ne pas toujours le leur dire."],"cash":["Tu réponds « je sais » à une confidence qu’on te faisait pour la première fois.","Tu pardonnes, bien sûr. Tu ranges juste le dossier dans un tiroir dont tu gardes la clé."],"expert":["Pluton en Scorpion, en domicile : exigence de vérité, contrôle de l’intime, transformation par crises successives."]},"roastWeight":1,"avoid":["Tout vocabulaire de disparition, de perte ou de sexualité","Le cliché du personnage dangereux ou vengeur"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:taurus', 'fr', '1', '{"keywords":["possession","endurance","sécurité matérielle","ténacité"],"essence":"Pluton en Taureau porte l’intensité sur la matière : ressources, territoire, sécurité. Une génération qui transforme lentement ses bases ; chez une personne, le besoin de maîtrise s’attache à ce qui se possède et se conserve.","light":["Endurance hors du commun","Capacité à reconstruire patiemment après un bouleversement","Loyauté profonde envers ce qui a été choisi"],"shadow":["Possessivité envers les biens comme envers les proches","Résistance farouche à toute perte de contrôle matériel","Rancune tenace quand une limite est franchie"],"behaviors":["Savoir exactement qui a emprunté quel livre et depuis quand","Garder ses provisions comme une réserve stratégique","Refuser de prêter son fauteuil, même pour cinq minutes"],"summary":{"soft":"Tu as une force tranquille, enracinée. Ce que tu construis, tu le protèges avec une constance rare, et les tiens savent qu’avec toi le sol ne se dérobe pas.","cash":"Tu partages volontiers, à condition de savoir où part chaque chose et quand elle revient.","expert":"Pluton en Taureau est en exil : l’intensité s’y fixe sur la possession et la sécurité matérielle. Chez vous, la transformation passe par le rapport aux ressources, et progresse avec lenteur."},"roastAngles":{"soft":["Tu tiens à ce que tu aimes comme un arbre tient à sa terre : sans bruit, et pour longtemps."],"cash":["Tu prêtes un stylo et tu en suis la trace comme celle d’un colis recommandé.","Ton frigo a des zones réservées, et tout le monde à la maison connaît les frontières."],"expert":["Pluton en Taureau, en exil : attachement intense au tangible, transformation consentie par nécessité seulement."]},"roastWeight":0,"avoid":["Donner un conseil d’argent","Présenter la possessivité comme un défaut de la personne plutôt que comme un comportement"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:pluto:virgo', 'fr', '1', '{"keywords":["contrôle par le détail","perfectionnement","analyse","travail en profondeur"],"essence":"Pluton en Vierge concentre l’intensité sur le travail, la méthode et l’amélioration. Une génération qui transforme par l’analyse et l’effort minutieux ; chez une personne, le besoin de maîtrise se loge dans le détail et la tâche accomplie sans défaut.","light":["Capacité à réparer ce qui semblait irrécupérable","Rigueur qui transforme un chaos en système","Dévouement entier au travail entrepris"],"shadow":["Contrôle exercé par la critique du détail","Exigence envers soi qui ne connaît pas de pause","Difficulté à déléguer sans vérifier"],"behaviors":["Vider le lave-vaisselle rempli par quelqu’un d’autre pour le remplir « correctement »","Tenir un fichier pour suivre ses autres fichiers","Repérer la coquille en page de garde avant de lire le titre"],"summary":{"soft":"Tu as le don de réparer, d’affiner, de remettre en état. Ton exigence vient d’un vrai respect pour le travail bien fait, et elle transforme en profondeur ce que tu touches.","cash":"Tu ne contrôles pas tout, non. Tu vérifies seulement que tout a été fait comme tu l’aurais fait.","expert":"Pluton en Vierge, signe mutable de terre, porte la transformation sur le travail et les méthodes. Chez vous, l’intensité prend la forme du perfectionnement, et le contrôle passe par l’analyse du détail."},"roastAngles":{"soft":["Tu améliores les choses en silence, et on s’aperçoit de ton passage au fait que tout marche."],"cash":["Tu repasses derrière quelqu’un qui vient de ranger, avec la discrétion d’une inspection officielle.","Tu as une méthode pour plier les sacs, et un avis très net sur ceux qui n’en ont pas."],"expert":["Pluton en Vierge : pouvoir exercé par la compétence et la critique, exigence tournée d’abord contre soi."]},"roastWeight":1,"avoid":["Tout sujet médical ou d’hygiène de vie","Parler d’obsession sur un mode clinique"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:aquarius', 'fr', '1', '{"keywords":["indépendance","principes","distance","rigueur d’esprit","sens du collectif"],"essence":"Saturne en Verseau, en domicile, place l’exigence sur les idées et le groupe : principes fermes, indépendance, engagement réfléchi envers le collectif.","light":["Pensée structurée et originale","Fidélité durable en amitié","Sens des responsabilités envers le groupe"],"shadow":["Distance émotionnelle érigée en règle","Principes appliqués sans souplesse","Sentiment de rester à part"],"behaviors":["Observer un groupe depuis le bord avant d’y entrer","Défendre une règle par principe, même à son désavantage","Garder les mêmes amis pendant vingt ans","Répondre à une émotion par une analyse"],"summary":{"soft":"Tu tiens à ta liberté autant qu’à tes principes, et tu offres aux autres la même. Ton amitié est discrète, mais elle traverse les années.","cash":"Tu réponds à « je suis triste » par un schéma en trois parties. Tu aimes le groupe, à condition d’avoir une sortie de secours et ton propre règlement.","expert":"Saturne en Verseau, en domicile, structure la pensée et le lien social : principes, objectivité, loyauté de groupe. La distance peut tenir lieu de protection affective."},"roastAngles":{"soft":["Tu restes un peu à l’écart, et c’est de là que tu vois le mieux ce dont chacun a besoin."],"cash":["Tu rejoins la soirée, tu repères la sortie, et tu restes debout juste à côté.","Tu appliques une règle que tu as toi-même inventée, sans exception, même pour toi."],"expert":["En domicile en Verseau, Saturne rationalise le lien : la loyauté s’y fonde sur le principe."]},"roastWeight":1,"avoid":["Évoquer des opinions précises","Parler d’isolement comme d’un destin"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:aries', 'fr', '1', '{"keywords":["autonomie","élan retenu","courage","peur d’échouer","effort"],"essence":"Saturne en Bélier met l’exigence sur l’initiative : l’élan se heurte au doute, et l’autonomie s’apprend par l’effort.","light":["Courage construit, qui ne dépend pas de l’humeur","Capacité à agir sans appui","Endurance dans les débuts difficiles"],"shadow":["Peur de se lancer déguisée en prudence","Alternance de frein et d’accélérateur","Dureté envers ses propres hésitations"],"behaviors":["Préparer longuement un premier pas","Refuser de l’aide pour prouver une capacité à faire sans personne","Démarrer d’un coup après des semaines de retenue","S’agacer d’attendre tout en hésitant à commencer"],"summary":{"soft":"Ton courage ne s’est pas donné d’emblée : tu l’as appris, un premier pas après l’autre. Cette lenteur à oser fait de toi quelqu’un de fiable quand les débuts sont rudes.","cash":"Tu veux y aller tout de suite, mais d’abord tu vérifies que tu as le droit. Tu conduis ta vie pied sur le frein et main sur le klaxon.","expert":"Saturne en Bélier, en chute, contraint l’impulsion : l’initiative devient un terrain d’exigence. L’autonomie s’affirme par la discipline plutôt que par l’élan."},"roastAngles":{"soft":["Tu as appris le courage à la main, et il tient mieux que celui qui vient tout seul."],"cash":["Tu répètes « j’y vais » depuis un moment, debout, manteau sur le dos, dans l’entrée.","Tu refuses toute aide pour porter les cartons, puis tu en veux à l’escalier."],"expert":["En chute, Saturne freine le premier mouvement : la décision y gagne en gravité, non en vitesse."]},"roastWeight":1,"avoid":["Parler de lâcheté","Annoncer des échecs"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:cancer', 'fr', '1', '{"keywords":["pudeur","protection","réserve affective","devoir familial","carapace"],"essence":"Saturne en Cancer place l’exigence sur la sécurité affective : pudeur des émotions, sens du devoir envers les proches, peur de dépendre.","light":["Fiabilité sans faille envers les siens","Capacité à tenir bon quand les autres flanchent","Tendresse qui se prouve par des actes"],"shadow":["Émotions gardées sous clé","Difficulté à demander du réconfort","Devoir familial porté sans partage"],"behaviors":["Répondre « ça va » en changeant de sujet","Prendre en charge l’organisation des fêtes de famille","S’occuper des autres pour détourner l’attention de soi","Ranger la maison quand quelque chose ne va pas"],"summary":{"soft":"Ta tendresse est pudique : elle passe par ce que tu fais plutôt que par ce que tu dis. Tu protèges les tiens avec constance, et toi aussi, tu mérites un abri.","cash":"Tu prends soin de tout le monde pour que personne ne te demande comment ça va. Ta carapace a une carapace, et elle est très bien rangée.","expert":"Saturne en Cancer, en exil, contraint l’expression affective : pudeur, sens du devoir familial, besoin de sécurité intérieure. La protection peut se muer en retrait défensif."},"roastAngles":{"soft":["Tu dis « je t’aime » en vérifiant que l’autre a bien pris une écharpe."],"cash":["Tu réponds « ça va » d’un air qui déconseille clairement la question suivante.","Tu consoles tout le monde, puis tu ranges la cuisine à minuit sans rien dire."],"expert":["En exil, Saturne tient l’émotion à distance : le soin s’y exprime par le devoir."]},"roastWeight":2,"avoid":["Supposer une enfance malheureuse","Parler de la mère ou du père"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:capricorn', 'fr', '1', '{"keywords":["ambition","discipline","responsabilité","endurance","autorité"],"essence":"Saturne en Capricorne, en domicile, exprime pleinement sa nature : ambition patiente, sens du devoir, goût de la structure et du long terme.","light":["Persévérance à toute épreuve","Sens des responsabilités précoce","Capacité à bâtir sur des années"],"shadow":["Travail utilisé comme refuge","Difficulté à se reposer sans culpabilité","Dureté envers la moindre faiblesse"],"behaviors":["Répondre à un courriel professionnel un dimanche","Planifier l’année sur un calendrier mural","Parler d’objectifs pendant les vacances","Refuser une pause tant que la tâche n’est pas finie"],"summary":{"soft":"Tu portes beaucoup, depuis longtemps, et tu le fais bien. Ta force tranquille rassure ; elle a aussi le droit de s’asseoir de temps en temps.","cash":"Tu te détends avec une liste de choses à faire pour te détendre. Tu avais déjà un plan de carrière à l’âge où les autres avaient un doudou.","expert":"Saturne en Capricorne, en domicile, agit avec toute sa cohérence : discipline, stratégie, sens de la hiérarchie et du temps. L’exigence peut s’exercer au détriment du repos."},"roastAngles":{"soft":["Tu gravis lentement, sans bruit, et c’est toi qui attends les autres en haut."],"cash":["Tu prends un jour de congé et tu le passes à ranger tes dossiers par couleur.","Tu dis « je décroche » en gardant ton téléphone professionnel sur la table de nuit."],"expert":["En domicile, Saturne gouverne par la durée : le résultat s’y construit, il ne s’improvise pas."]},"roastWeight":2,"avoid":["Donner un conseil de carrière","Présenter la réussite comme acquise"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:gemini', 'fr', '1', '{"keywords":["rigueur intellectuelle","doute","parole mesurée","concentration","méthode"],"essence":"Saturne en Gémeaux discipline la pensée : exigence de précision dans les mots, sérieux dans l’apprentissage, crainte de mal s’exprimer.","light":["Esprit méthodique et fiable","Parole pesée, qui engage","Capacité à approfondir un sujet jusqu’au bout"],"shadow":["Peur de dire une bêtise","Autocensure avant de prendre la parole","Sérieux excessif là où la légèreté suffirait"],"behaviors":["Relire un message plusieurs fois avant de l’envoyer","Vérifier un mot dans le dictionnaire en pleine conversation","Préparer des notes pour un simple appel","Se taire en réunion puis tout formuler après coup"],"summary":{"soft":"Tu pèses tes mots parce que tu sais ce qu’ils valent. Ta pensée avance lentement, sûrement, et quand tu parles enfin, les autres écoutent.","cash":"Tu rédiges un message, tu le relis, tu le corriges, tu doutes, puis tu envoies « ok ». Ta meilleure réplique arrive toujours dans l’escalier.","expert":"Saturne en Gémeaux structure le mental : pensée rigoureuse, expression contrôlée, apprentissage méthodique. La crainte de l’erreur peut inhiber la spontanéité de la parole."},"roastAngles":{"soft":["Tu choisis tes mots comme on choisit des clés : pour qu’ils ouvrent vraiment quelque chose."],"cash":["Tu prépares une fiche avec des tirets avant d’appeler pour commander une pizza.","Tu trouves la réponse parfaite trois jours après la fin de la discussion."],"expert":["Saturne en Gémeaux exige l’exactitude du propos : la parole y devient un engagement."]},"roastWeight":1,"avoid":["Parler de difficultés scolaires","Supposer un manque d’intelligence"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:leo', 'fr', '1', '{"keywords":["fierté","pudeur","exigence créative","peur du ridicule","dignité"],"essence":"Saturne en Lion met l’exigence sur l’expression de soi : besoin de reconnaissance méritée, peur du ridicule, créativité travaillée.","light":["Dignité constante, même sous pression","Talent poli par le travail","Autorité naturelle quand la confiance est là"],"shadow":["Crainte de se montrer avant d’avoir tout préparé","Difficulté à recevoir un compliment","Orgueil qui empêche de demander"],"behaviors":["Répéter longtemps avant de monter sur scène","Minimiser un compliment aussitôt reçu","Refuser de jouer à un jeu sans en maîtriser les règles","Travailler une création en secret pendant des mois"],"summary":{"soft":"Tu veux briller, mais pas à n’importe quel prix : seulement si c’est mérité. Cette pudeur donne à ta lumière quelque chose de rare et de digne.","cash":"Tu rêves d’applaudissements mais tu refuses de monter sur scène sans dix répétitions. Un compliment te gêne, son absence te vexe.","expert":"Saturne en Lion, en exil, soumet l’expression personnelle à l’exigence : fierté contenue, créativité disciplinée. La reconnaissance est désirée autant que redoutée."},"roastAngles":{"soft":["Tu ne te montres qu’une fois le travail fait, et c’est pour cela que les regards s’arrêtent."],"cash":["Tu réponds à un compliment par la liste détaillée de ce qui n’allait pas.","Tu refuses le karaoké toute la soirée, puis tu notes chaque chanson comme un jury."],"expert":["En exil en Lion, Saturne retient l’éclat : l’autorité s’y acquiert par le travail, non par la démonstration."]},"roastWeight":1,"avoid":["Parler d’un manque d’amour","Réduire le placement à la timidité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:libra', 'fr', '1', '{"keywords":["équité","engagement","mesure","sens du contrat","réserve relationnelle"],"essence":"Saturne en Balance, signe de son exaltation, place l’exigence sur la relation : sérieux de l’engagement, sens de l’équité, lenteur à s’accorder.","light":["Loyauté dans les engagements pris","Jugement équilibré et impartial","Tact dans les situations tendues"],"shadow":["Peur du désaccord","Lenteur à s’engager","Comptabilité discrète de ce qui est donné et reçu"],"behaviors":["Peser le pour et le contre par écrit","Tenir une parole donnée des années plus tôt","Reformuler une critique jusqu’à la rendre polie","Se souvenir de qui a payé la dernière fois"],"summary":{"soft":"Tu prends les liens au sérieux : une parole donnée, chez toi, pèse lourd. Tu avances lentement vers l’autre, mais tu restes.","cash":"Tu mets six mois à dire oui et dix ans à tenir parole. Tu sais exactement qui a invité qui la dernière fois, mais tu n’en parles jamais.","expert":"Saturne en Balance, en exaltation, donne à l’exigence une forme juste : sens du contrat, impartialité, engagement durable. La prudence relationnelle peut retarder le choix."},"roastAngles":{"soft":["Tu donnes ta parole rarement, et c’est pour cela qu’elle vaut de l’or."],"cash":["Tu fais une liste de pour et de contre pour savoir si tu acceptes un café.","Tu évites une dispute depuis si longtemps qu’elle a pris un abonnement chez toi."],"expert":["Exalté en Balance, Saturne codifie le lien : l’équité y prime sur l’élan."]},"roastWeight":1,"avoid":["Parler de mariage, de séparation ou de droit","Supposer une solitude"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:pisces', 'fr', '1', '{"keywords":["sensibilité contenue","limites","compassion responsable","doute","retrait"],"essence":"Saturne en Poissons place l’exigence sur le monde intérieur : besoin de donner forme au flou, peur du débordement, compassion tenue par le devoir.","light":["Compassion sérieuse, qui agit","Capacité à donner une forme aux rêves","Humilité devant ce qui échappe"],"shadow":["Culpabilité sans objet précis","Difficulté à poser des limites nettes","Retrait silencieux quand tout pèse"],"behaviors":["S’excuser pour une faute commise par quelqu’un d’autre","S’isoler pour retrouver son calme après une journée en groupe","Tenir un carnet pour mettre de l’ordre dans ses rêves","Aider en silence puis disparaître"],"summary":{"soft":"Tu ressens beaucoup et tu cherches où poser tout cela. En donnant une forme à ta sensibilité, tu en fais un abri pour toi et pour les autres.","cash":"Tu t’excuses quand quelqu’un te marche sur le pied. Tu veux sauver tout le monde, mais uniquement à des horaires que tu n’as pas fixés.","expert":"Saturne en Poissons cherche à structurer l’informe : sensibilité disciplinée, sens du sacrifice, besoin de retrait. La difficulté tient à la définition des limites personnelles."},"roastAngles":{"soft":["Tu donnes des contours à la brume, patiemment, jusqu’à ce qu’un paysage apparaisse."],"cash":["Tu dis « pardon » à une porte que tu viens de heurter.","Tu culpabilises d’avoir dit non, puis d’avoir dit oui, puis d’y repenser."],"expert":["Saturne en Poissons impose une forme au diffus : la compassion y devient une responsabilité."]},"roastWeight":1,"avoid":["Parler de sacrifice comme d’un destin","Évoquer des dépendances ou le bien-être médical"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:sagittarius', 'fr', '1', '{"keywords":["convictions","quête de sens","rigueur morale","doute","sérieux"],"essence":"Saturne en Sagittaire place l’exigence sur le sens : besoin de convictions solides, sérieux dans l’étude, crainte de croire à tort.","light":["Pensée construite, qui cherche la cohérence","Intégrité dans les principes","Goût de l’étude longue"],"shadow":["Rigidité des opinions une fois formées","Difficulté à s’accorder l’insouciance","Tendance à faire la morale"],"behaviors":["Lire les sources avant d’avoir un avis","Préparer un voyage avec un dossier complet","Reprendre quelqu’un sur l’emploi d’un mot","Douter d’une bonne nouvelle tant qu’elle n’est pas confirmée"],"summary":{"soft":"Tu as besoin que les choses aient un sens, et tu le cherches avec sérieux. Tes convictions ne sont pas des slogans : tu les as gagnées une à une.","cash":"Tu pars en vacances avec un itinéraire, une bibliographie et un plan B. Ton optimisme demande d’abord à voir les sources.","expert":"Saturne en Sagittaire structure la quête de sens : convictions éprouvées, rigueur morale, goût du savoir approfondi. Le doute méthodique peut tourner au dogmatisme."},"roastAngles":{"soft":["Tu cherches la vérité à pied, sans raccourci, et tu arrives plus loin que prévu."],"cash":["Tu réponds « tout dépend de la définition » à une question sur le dessert.","Tu imprimes le programme du voyage en double, dont un exemplaire plastifié."],"expert":["Saturne en Sagittaire exige des preuves à la conviction : la foi y passe par l’examen."]},"roastWeight":1,"avoid":["Parler de croyances ou d’opinions précises","Supposer des études difficiles"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:scorpio', 'fr', '1', '{"keywords":["maîtrise","contrôle","endurance","méfiance","pudeur de l’intime"],"essence":"Saturne en Scorpion place l’exigence sur la maîtrise de soi : contrôle des émotions fortes, endurance dans l’épreuve, peur de perdre pied.","light":["Résistance hors du commun sous pression","Loyauté profonde une fois la confiance donnée","Lucidité sur les rapports de force"],"shadow":["Méfiance longue à lever","Refus de montrer une faille","Rancune tenue avec méthode"],"behaviors":["Mettre quelqu’un à l’épreuve avant de se confier","Garder un visage impassible sous le choc","Se souvenir précisément d’une trahison ancienne","Tout gérer sans aide plutôt que demander"],"summary":{"soft":"Tu ne donnes pas ta confiance à la légère, et quand tu la donnes, c’est pour de bon. Derrière ta maîtrise, il y a une profondeur que peu de gens ont la chance de voir.","cash":"Tu fais passer des tests aux gens sans leur dire qu’il y a un examen. Tu pardonnes, bien sûr, mais tu classes le dossier par date.","expert":"Saturne en Scorpion concentre l’exigence sur le contrôle émotionnel : endurance, lucidité, méfiance défensive. La crainte de la vulnérabilité structure le rapport à l’intime."},"roastAngles":{"soft":["Tu gardes la porte, c’est vrai, mais ceux qui entrent ne sont jamais mis dehors."],"cash":["Tu dis « j’ai tourné la page » en citant la date, l’heure et la phrase exacte.","Tu laisses quelqu’un faire ses preuves pendant trois ans avant de lui prêter un livre."],"expert":["Saturne en Scorpion verrouille l’accès à l’intime : la confiance s’y obtient par la durée."]},"roastWeight":2,"avoid":["Évoquer la sexualité ou des drames","Parler de vengeance comme d’un trait certain"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:taurus', 'fr', '1', '{"keywords":["sécurité","endurance","sobriété","peur du manque","attachement"],"essence":"Saturne en Taureau place l’exigence sur la sécurité matérielle : besoin de solide, peur du manque, construction lente et tenace.","light":["Endurance remarquable dans l’effort","Sens de la valeur des choses","Fidélité à ce qui a fait ses preuves"],"shadow":["Crainte de manquer même quand tout va bien","Difficulté à s’accorder un plaisir sans raison","Rigidité face au changement d’habitudes"],"behaviors":["Garder un objet « au cas où » pendant dix ans","Comparer longuement avant le moindre achat","Finir le tube jusqu’à la dernière goutte","Refuser de changer de place à table"],"summary":{"soft":"Tu construis ta sécurité avec patience, comme on monte un mur de pierres sèches. Ce besoin de solide n’est pas de l’avarice : c’est une façon de tenir parole au temps.","cash":"Tu gardes tout « au cas où », et le cas où n’arrive jamais. Tu t’offres un plaisir après avoir vérifié trois fois que tu le mérites.","expert":"Saturne en Taureau fixe l’exigence sur les ressources et la stabilité : persévérance, économie, sens du concret. La peur du manque peut rigidifier le rapport au plaisir et à la possession."},"roastAngles":{"soft":["Tu bâtis lentement, mais ce que tu poses reste posé, et chacun s’y appuie volontiers."],"cash":["Tu coupes le tube de dentifrice en deux pour récupérer ce qu’il reste dedans.","Tu hésites deux semaines pour un achat, puis tu gardes le ticket de caisse à vie."],"expert":["Saturne en Taureau thésaurise par précaution : la sécurité s’y mesure à ce qui dure."]},"roastWeight":1,"avoid":["Donner un conseil financier","Parler d’avarice"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:saturn:virgo', 'fr', '1', '{"keywords":["rigueur","devoir","perfectionnisme","méthode","autocritique"],"essence":"Saturne en Vierge place l’exigence sur le travail bien fait : goût de la méthode, sens du devoir, peur de l’erreur.","light":["Fiabilité exemplaire dans l’exécution","Capacité d’analyse patiente","Conscience professionnelle élevée"],"shadow":["Perfectionnisme qui retarde la fin","Autocritique sévère","Inquiétude pour des détails mineurs"],"behaviors":["Vérifier trois fois une pièce jointe","Reprendre en silence le travail d’un autre pour l’améliorer","Dresser la liste de ses propres erreurs après une réussite","Arriver en avance par crainte du retard"],"summary":{"soft":"Tu fais les choses bien parce que tu respectes ce que tu touches. Ton exigence est un soin ; elle mérite seulement de se montrer aussi douce avec toi qu’avec ton travail.","cash":"Tu rends un travail impeccable en t’excusant qu’il ne soit pas mieux. Tu as repéré la faute d’orthographe du menu avant de voir les plats.","expert":"Saturne en Vierge renforce l’analyse et le sens du devoir : méthode, précision, exigence d’utilité. L’autocritique et la crainte de l’erreur peuvent freiner l’achèvement."},"roastAngles":{"soft":["Tu prends soin des détails comme d’un jardin : rien ne pousse par hasard chez toi."],"cash":["Tu rouvres un courriel déjà envoyé pour vérifier que la pièce jointe y est toujours.","Tu refais discrètement le lave-vaisselle chargé par quelqu’un d’autre."],"expert":["Saturne en Vierge soumet tout au contrôle : la valeur d’une tâche s’y juge à son exactitude."]},"roastWeight":2,"avoid":["Parler d’hygiène de vie ou du corps","Qualifier la personne de maniaque"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:aquarius', 'fr', '1', '{"keywords":["indépendance","idéal collectif","originalité","amitié","détachement"],"essence":"Le Soleil en Verseau, signe fixe d’air où il est en exil, fonde l’identité sur l’indépendance d’esprit, l’idéal collectif et le refus des conventions. La personne se définit par ses idées et par sa différence.","light":["Pensée originale, en avance sur son entourage","Sens de l’amitié et du collectif","Tolérance sincère envers toutes les singularités"],"shadow":["Distance affective quand l’émotion devient trop proche","Esprit de contradiction par principe","Certitude têtue d’avoir raison avant tout le monde"],"behaviors":["Contredire une idée dès qu’elle devient majoritaire","Disparaître plusieurs semaines puis revenir comme si de rien n’était","Défendre l’humanité entière et oublier un anniversaire","Analyser une émotion au lieu de la ressentir","Adopter une passion étrange avant qu’elle soit à la mode"],"summary":{"soft":"Tu regardes le monde d’un peu plus haut, là où l’air est libre. Ta différence n’est pas une pose : c’est ta façon d’aimer les gens, tous ensemble.","cash":"Tu aimes l’humanité, c’est avec les gens un par un que ça se complique. Dès que tout le monde aime un truc, tu passes à autre chose.","expert":"Le Soleil en Verseau est en exil : dans ce signe fixe d’air, l’identité se pense à travers le groupe et l’idée. Vous tenez à votre indépendance ; l’affirmation personnelle passe chez vous par la singularité."},"roastAngles":{"soft":["Tu ne rentres dans aucune case, et c’est exactement pour ça qu’on te garde une place à part."],"cash":["Tu réponds “c’est intéressant” à quelqu’un qui pleure, puis tu proposes une théorie.","Tu as disparu trois semaines sans prévenir, et tu reviens avec un lien vers un documentaire."],"expert":["Soleil en Verseau, en exil : fixité d’air. Vous défendez la liberté de tous avec une rigidité remarquable."]},"roastWeight":2,"avoid":["Réduire le placement à la froideur ou à l’excentricité gratuite","Confondre détachement et absence de sentiments"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:aries', 'fr', '1', '{"keywords":["élan","initiative","courage","impatience","franchise"],"essence":"Le Soleil en Bélier, signe cardinal de feu où il est en exaltation, fonde l’identité sur l’élan et l’initiative. La personne se définit par ce qu’elle lance, moins par ce qu’elle termine.","light":["Courage de commencer là où les autres hésitent","Franchise directe, sans calcul ni arrière-pensée","Énergie qui remet un groupe en mouvement"],"shadow":["Impatience face à tout ce qui demande de la durée","Colère vive, vite montée, vite oubliée, mais pas toujours par l’entourage","Difficulté à finir ce qui a perdu l’attrait de la nouveauté"],"behaviors":["Se porter volontaire avant d’avoir entendu la fin de la consigne","Finir les phrases des autres pour gagner du temps","Marcher deux mètres devant le groupe","Transformer un jeu de société en finale de championnat","Lancer un projet le lundi et s’en lasser le jeudi"],"summary":{"soft":"Tu avances comme on ouvre une porte : d’un seul geste, sans attendre la permission. Ta force, c’est d’oser le premier pas quand tout le monde regarde ses chaussures.","cash":"Tu as dit oui avant la fin de la question. Tu réfléchis après, en route, et de préférence en doublant tout le monde.","expert":"Le Soleil en Bélier, en exaltation dans ce signe cardinal de feu, place l’identité dans l’initiative. Vous vous affirmez par l’action directe ; la constance demande un effort conscient."},"roastAngles":{"soft":["Tu fonces d’abord, tu comprends ensuite : c’est ta façon à toi de faire confiance à la vie."],"cash":["Tu appelles ça “décider vite”. Les autres appellent ça “ne pas avoir lu le message jusqu’au bout”.","Ta patience a une durée de vie précise : celle d’un feu rouge, et encore, tu avances déjà."],"expert":["Soleil en Bélier : volonté cardinale, élan immédiat. Vous commencez mieux que vous ne poursuivez."]},"roastWeight":3,"avoid":["Réduire le placement à l’agressivité","Confondre impulsivité et manque de réflexion"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:cancer', 'fr', '1', '{"keywords":["attachement","mémoire","protection","foyer","sensibilité"],"essence":"Le Soleil en Cancer, signe cardinal d’eau, fonde l’identité sur l’attachement, la mémoire et le besoin de protéger. La personne se définit par les siens et par les lieux où elle se sent chez elle.","light":["Sens de l’accueil et attention sincère aux besoins des autres","Mémoire affective fidèle, qui retient les dates et les gestes","Ténacité discrète quand il s’agit de défendre les proches"],"shadow":["Repli dans la coquille à la moindre contrariété","Susceptibilité qui s’exprime par le silence plutôt que par les mots","Difficulté à laisser le passé à sa place"],"behaviors":["Nourrir les invités avant même de leur demander des nouvelles","Conserver des tickets de cinéma et de vieilles cartes d’anniversaire","Bouder en silence en espérant que quelqu’un devine","Quitter une soirée plus tôt pour retrouver son canapé","Citer mot pour mot une phrase blessante vieille de dix ans"],"summary":{"soft":"Tu as le cœur comme une maison : on y entre, on s’y réchauffe, on n’a plus envie de partir. Ta sensibilité est une façon de veiller sur ce qui compte.","cash":"Tu dis “ça va” en rangeant les placards très fort. Tout le monde a compris, sauf la personne concernée.","expert":"Le Soleil en Cancer, signe cardinal d’eau, fonde l’identité sur l’appartenance et la protection. Vous agissez par détours plutôt que de front ; la sécurité affective conditionne chez vous toute initiative."},"roastAngles":{"soft":["Tu gardes tout : les lettres, les souvenirs, les gens. C’est ta manière de dire que rien n’est perdu."],"cash":["Tu te souviens mot pour mot d’une remarque de l’école primaire. Tes clés, en revanche, mystère.","Tu as cuisiné pour douze, on était quatre, et tout le monde est reparti avec une boîte."],"expert":["Soleil en Cancer : cardinalité d’eau. Vous avancez de biais, mais vous ne lâchez jamais ce qui vous est cher."]},"roastWeight":2,"avoid":["Réduire le placement à la fragilité ou aux larmes","Assimiler attachement à la famille et dépendance"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:capricorn', 'fr', '1', '{"keywords":["ambition","responsabilité","persévérance","temps long","pudeur"],"essence":"Le Soleil en Capricorne, signe cardinal de terre, fonde l’identité sur l’ambition, la responsabilité et le temps long. La personne se définit par ce qu’elle accomplit et par les engagements qu’elle tient.","light":["Persévérance face aux objectifs lointains","Sens du devoir et parole tenue","Humour sec, souvent inattendu"],"shadow":["Dureté envers soi, puis envers les autres","Difficulté à se reposer sans culpabilité","Pudeur qui passe pour de la froideur"],"behaviors":["Répondre à un courriel de travail pendant les vacances","Avoir un plan à cinq ans et un plan de secours","Arriver en avance et le faire remarquer","Féliciter par un simple « c’est correct »","Calculer le temps perdu pendant une sieste"],"summary":{"soft":"Tu gravis ta montagne pas à pas, sans bruit, et tu tiens toujours parole. Sous ton sérieux, il y a une tendresse qui se prouve par les actes.","cash":"Tu te reposes avec un objectif et un chronomètre. À huit ans, tu avais déjà un plan de carrière et un avis sur les retardataires.","expert":"Le Soleil en Capricorne, signe cardinal de terre, fonde l’identité sur l’accomplissement et la maîtrise du temps. Vous construisez par étapes ; l’autorité que vous recherchez se gagne chez vous par l’effort."},"roastAngles":{"soft":["Tu portes beaucoup sans te plaindre : pose le sac de temps en temps, le sommet ne bouge pas."],"cash":["Tu as pris un jour de repos, et tu l’as rentabilisé en rangeant le garage et en triant tes factures.","Ton plus grand compliment, c’est “pas mal”. Les gens qui te connaissent en pleurent de joie."],"expert":["Soleil en Capricorne : cardinalité de terre. Vous remettez le plaisir à plus tard avec une constance suspecte."]},"roastWeight":3,"avoid":["Réduire le placement à la froideur ou à l’obsession de l’argent","Présenter l’ambition comme un défaut"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:gemini', 'fr', '1', '{"keywords":["curiosité","parole","vivacité","adaptation","dispersion"],"essence":"Le Soleil en Gémeaux, signe mutable d’air, fonde l’identité sur la curiosité, la parole et la circulation des idées. La personne se définit par ce qu’elle apprend, relie et raconte.","light":["Vivacité d’esprit et sens de la repartie","Capacité à s’adapter à tous les milieux","Talent pour relier des gens et des idées qui s’ignoraient"],"shadow":["Dispersion entre trop de pistes ouvertes à la fois","Avis qui change selon la dernière conversation","Tendance à survoler ce qui demanderait d’approfondir"],"behaviors":["Garder quarante onglets ouverts et en chercher un de plus","Commencer trois livres en parallèle","Répondre à un message pendant une autre conversation","Changer de sujet au milieu de sa propre phrase","Avoir une anecdote sur absolument tout"],"summary":{"soft":"Ton esprit est une fenêtre ouverte : tout y entre, tout y circule. Tu relies les gens et les idées avec une légèreté qui fait du bien.","cash":"Tu as un avis sur tout, et un deuxième avis au cas où. Ta phrase commence quelque part et atterrit dans une autre conversation.","expert":"Le Soleil en Gémeaux, signe mutable d’air, situe l’identité dans l’échange et l’apprentissage. Vous pensez en réseau, par associations rapides ; la profondeur vient par accumulation plutôt que par fixation."},"roastAngles":{"soft":["Tu papillonnes d’une idée à l’autre, et c’est ainsi que tu fais fleurir des jardins entiers."],"cash":["Tu as quarante onglets ouverts, dont un qui fait de la musique, et tu refuses de savoir lequel.","Tu as lu la moitié de l’article, et tu l’expliques déjà à quelqu’un qui l’a écrit."],"expert":["Soleil en Gémeaux : mutabilité d’air. Vous comprenez vite, et vous passez à autre chose plus vite encore."]},"roastWeight":3,"avoid":["Parler de double personnalité ou d’hypocrisie","Confondre curiosité et superficialité"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:leo', 'fr', '1', '{"keywords":["rayonnement","fierté","générosité","créativité","loyauté"],"essence":"Le Soleil en Lion, signe fixe de feu où il est en domicile, fonde l’identité sur le rayonnement, la fierté et le don de soi. La personne a besoin de créer, de se montrer et de compter pour quelqu’un.","light":["Générosité large, qui donne sans compter","Loyauté solide envers les personnes choisies","Chaleur qui met de la fête et du courage dans un groupe"],"shadow":["Fierté qui supporte mal la critique","Besoin d’attention difficile à rassasier","Tendance à tout ramener à sa propre histoire"],"behaviors":["Raconter une anecdote en mimant tous les personnages","Offrir un cadeau trop grand pour l’occasion","Vérifier discrètement qui a applaudi","Se vexer d’un compliment jugé trop court","Organiser l’anniversaire des autres et y briller quand même"],"summary":{"soft":"Tu réchauffes une pièce rien qu’en y entrant. Ta générosité est vraie, et ton besoin d’attention aussi : les deux vont ensemble, comme la flamme et sa lumière.","cash":"Tu donnes tout sans compter, mais tu comptes très bien les applaudissements. Un merci oublié, et c’est rideau.","expert":"Le Soleil en Lion est en domicile : signe fixe de feu, il y exprime pleinement volonté, fierté et créativité. Vous cherchez à rayonner et à donner ; la reconnaissance reste chez vous un besoin structurant."},"roastAngles":{"soft":["Tu brilles sans le faire exprès, et tu offres ta lumière à qui veut bien s’y asseoir."],"cash":["Tu racontes ta journée comme une bande-annonce : avec les voix, les gestes et une pause pour les réactions.","On t’a fait un compliment. Tu as dit “oh, arrête”, puis tu as attendu la suite avec beaucoup de patience."],"expert":["Soleil en Lion, en domicile : fixité de feu. Vous donnez largement, à condition que cela se remarque."]},"roastWeight":3,"avoid":["Réduire le placement à l’égocentrisme","Employer des images de roi ou de reine"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:libra', 'fr', '1', '{"keywords":["relation","équilibre","diplomatie","harmonie","indécision"],"essence":"Le Soleil en Balance, signe cardinal d’air où il est en chute, fonde l’identité sur la relation, l’équilibre et le sens de l’harmonie. La personne se définit volontiers à travers la présence de l’autre.","light":["Diplomatie et art de trouver un terrain d’entente","Sens de la justice et de l’équité","Élégance des manières et goût de l’harmonie"],"shadow":["Indécision prolongée devant un choix simple","Évitement du conflit, au prix de non-dits","Tendance à dire à chacun ce qu’il souhaite entendre"],"behaviors":["Hésiter dix minutes entre deux plats, puis prendre comme le voisin","Répondre « peu importe » en ayant une préférence nette","Donner raison aux deux camps dans la même soirée","Demander pardon quand quelqu’un d’autre bouscule","Solliciter trois avis avant d’acheter un pull"],"summary":{"soft":"Tu cherches l’accord comme d’autres cherchent la lumière. Avec toi, les angles s’arrondissent et chacun se sent écouté.","cash":"Tu dis “comme tu veux” en ayant une préférence très claire. Puis tu attends, avec élégance, que quelqu’un devine.","expert":"Le Soleil en Balance est en chute : dans ce signe cardinal d’air, l’affirmation de soi passe par l’autre. Vous cherchez l’équilibre avant la décision ; trancher vous coûte plus que négocier."},"roastAngles":{"soft":["Tu pèses chaque mot pour ne blesser personne : ta douceur est un vrai travail d’orfèvre."],"cash":["Tu as mis vingt minutes à choisir un plat, et tu as fini par prendre celui de ton voisin de table.","Tu donnes raison à tout le monde, puis tu rentres chez toi avec trois engagements contradictoires."],"expert":["Soleil en Balance, en chute : cardinalité d’air. Vous décidez mieux pour autrui que pour vous-même."]},"roastWeight":2,"avoid":["Réduire le placement à la superficialité ou à la coquetterie","Confondre recherche d’équilibre et absence d’opinion"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:pisces', 'fr', '1', '{"keywords":["empathie","imaginaire","porosité","compassion","rêverie"],"essence":"Le Soleil en Poissons, signe mutable d’eau, fonde l’identité sur l’empathie, l’imaginaire et la porosité au monde. La personne se définit moins par des contours que par ce qu’elle ressent et rêve.","light":["Compassion spontanée pour tout ce qui souffre","Imagination riche et sens artistique","Intuition fine des ambiances et des non-dits"],"shadow":["Limites floues entre ses émotions et celles des autres","Fuite dans le rêve quand le réel se durcit","Difficulté à dire non, puis à tenir le oui"],"behaviors":["Pleurer devant une publicité pour de la lessive","Manquer son arrêt de bus en regardant par la fenêtre","Répondre oui à tout puis disparaître","Égarer ses clés dans sa propre main","Absorber l’humeur de la pièce en y entrant"],"summary":{"soft":"Tu ressens le monde comme une marée : tout te traverse, tout te touche. Ta douceur et ton imagination sont un refuge pour ceux qui t’approchent.","cash":"Tu as dit oui à trois personnes pour samedi, et samedi tu dors. Tu pleures devant une pub, mais c’était une très bonne pub.","expert":"Le Soleil en Poissons, signe mutable d’eau, dilue les contours de l’identité au profit de l’empathie et de l’imaginaire. Vous percevez par imprégnation ; poser des limites demande chez vous un effort délibéré."},"roastAngles":{"soft":["Tu rêves les yeux ouverts, et le monde paraît plus doux à ceux qui marchent près de toi."],"cash":["Tu as manqué ton arrêt parce que tu inventais la vie entière de la personne assise en face.","Tu cherches ton téléphone depuis dix minutes en éclairant la pièce avec ton téléphone."],"expert":["Soleil en Poissons : mutabilité d’eau. Vous comprenez tout le monde, sauf l’idée même d’un horaire."]},"roastWeight":2,"avoid":["Réduire le placement à la naïveté ou à la victimisation","Évoquer une fuite dans des substances"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:sagittarius', 'fr', '1', '{"keywords":["quête de sens","horizon","liberté","optimisme","franchise"],"essence":"Le Soleil en Sagittaire, signe mutable de feu, fonde l’identité sur la quête de sens, l’horizon et la liberté de mouvement. La personne se définit par ce qu’elle explore, croit et transmet.","light":["Optimisme qui redonne de l’élan aux autres","Goût de la vérité et des grandes questions","Ouverture aux cultures, aux idées et aux grands espaces"],"shadow":["Franchise sans filtre, qui touche plus fort que prévu","Engagements plus larges que l’agenda","Fuite devant la routine et les cadres serrés"],"behaviors":["Réserver un billet avant de vérifier son agenda","Donner un avis définitif sur un pays visité quatre jours","Arriver en retard avec une excellente histoire","Dire une vérité à voix haute au pire moment","Transformer une question simple en exposé de philosophie"],"summary":{"soft":"Tu portes l’horizon avec toi : où que tu sois, tu vois plus loin et tu donnes envie de partir. Ta confiance en la vie est contagieuse.","cash":"Tu dis ce que tu penses, puis tu te demandes pourquoi ce silence. Tu as un billet d’avion et aucun plan, et ça te va très bien.","expert":"Le Soleil en Sagittaire, signe mutable de feu, oriente l’identité vers le sens et l’expansion. Vous avez besoin d’un but lointain ; votre franchise procède d’une conviction, rarement d’un calcul."},"roastAngles":{"soft":["Tu crois que tout finit par s’arranger, et à force d’y croire, tu embarques tout le monde."],"cash":["Tu as dit “je dis ça, je dis rien”, puis tu as tout dit, avec des exemples et une conclusion.","Tu donnes des leçons de vie tirées d’un voyage de quatre jours, dont deux passés à l’aéroport."],"expert":["Soleil en Sagittaire : mutabilité de feu. Vous visez loin, quitte à négliger ce qui se trouve à vos pieds."]},"roastWeight":2,"avoid":["Réduire le placement à l’irresponsabilité","Associer le signe à une croyance particulière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:scorpio', 'fr', '1', '{"keywords":["intensité","profondeur","maîtrise","lucidité","secret"],"essence":"Le Soleil en Scorpion, signe fixe d’eau, fonde l’identité sur l’intensité, la profondeur et la maîtrise de soi. La personne veut connaître le dessous des choses et ne s’engage jamais à moitié.","light":["Lucidité qui perçoit ce qui n’est pas dit","Loyauté totale une fois la confiance accordée","Capacité à traverser les crises et à s’y transformer"],"shadow":["Méfiance qui met les autres à l’épreuve","Rancune tenace, soigneusement entretenue","Goût du contrôle et du secret"],"behaviors":["Poser une question dont la réponse est déjà connue","Observer en silence avant de dire un mot","Retrouver n’importe quelle information en trois recherches","Ne rien raconter de soi pendant des mois","Couper les ponts sans préavis ni explication"],"summary":{"soft":"Tu ne fais rien à moitié : ni aimer, ni chercher, ni te taire. Derrière ta réserve, il y a une fidélité rare, offerte à très peu de gens.","cash":"Tu poses la question en connaissant déjà la réponse. C’est un test, et tout le monde le passe sans le savoir.","expert":"Le Soleil en Scorpion, signe fixe d’eau, concentre l’identité sur l’intensité et la maîtrise. Vous sondez avant de vous engager ; votre volonté s’exerce en profondeur, par la persévérance plus que par l’éclat."},"roastAngles":{"soft":["Tu regardes les gens jusqu’au fond, et tu ne pars pas : c’est ta plus grande preuve d’affection."],"cash":["Tu pardonnes, bien sûr. Tu gardes juste la date, l’heure et la phrase exacte, au cas où.","Tu sais tout sur tout le monde, et personne ne connaît ne serait-ce que ton plat préféré."],"expert":["Soleil en Scorpion : fixité d’eau. Vous accordez peu votre confiance, et vous ne la rendez jamais deux fois."]},"roastWeight":3,"avoid":["Réduire le placement à la jalousie ou à la manipulation","Faire du signe une caricature sombre ou dangereuse"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:taurus', 'fr', '1', '{"keywords":["stabilité","constance","sens du concret","plaisir","obstination"],"essence":"Le Soleil en Taureau, signe fixe de terre, ancre l’identité dans la stabilité, les sens et ce qui dure. La personne se construit lentement et tient à ce qu’elle a bâti.","light":["Constance qui mène les choses à terme","Sens du concret et du travail bien fait","Présence calme qui rassure l’entourage"],"shadow":["Résistance au changement, même quand il s’impose","Attachement aux habitudes et aux possessions","Obstination silencieuse, plus longue que n’importe quel argument"],"behaviors":["Commander le même plat dans le même restaurant depuis des années","Refuser de se presser, y compris en retard","Garder un objet parce qu’il peut encore servir","Répondre « on verra » pour dire non","Tester le confort du canapé avant de saluer les invités"],"summary":{"soft":"Tu construis lentement, et ce que tu construis tient debout. Autour de toi, on respire mieux : ta présence a quelque chose d’un jardin où rien ne presse.","cash":"Tu ne changes pas d’avis, tu attends que les autres se fatiguent. Et tu as tout ton temps, surtout s’il y a à manger.","expert":"Le Soleil en Taureau, signe fixe de terre, fonde l’identité sur la durée et la valeur concrète des choses. Vous consolidez plus que vous n’initiez ; votre rythme lent est une méthode, non une inertie."},"roastAngles":{"soft":["Tu prends ton temps comme on laisse mûrir un fruit : rien ne t’oblige à cueillir trop tôt."],"cash":["Tu n’as aucun retard, tu finis ton café. Le monde peut attendre, lui aussi devrait s’asseoir.","On t’a proposé un nouveau restaurant. Tu as souri, puis tu as réservé au même endroit que d’habitude."],"expert":["Soleil en Taureau : fixité et terre. Vous cédez rarement, non par orgueil, mais par besoin de continuité."]},"roastWeight":2,"avoid":["Réduire le placement à la gourmandise ou à la paresse","Présenter la lenteur comme un défaut d’intelligence"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:sun:virgo', 'fr', '1', '{"keywords":["précision","analyse","service","exigence","discrétion"],"essence":"Le Soleil en Vierge, signe mutable de terre, fonde l’identité sur l’utilité, la précision et le souci du détail. La personne se définit par ce qu’elle améliore et par les services qu’elle rend.","light":["Sens de l’analyse et œil pour ce qui cloche","Fiabilité discrète, sans besoin de se faire remarquer","Goût du travail soigné et des solutions pratiques"],"shadow":["Autocritique sévère, rarement satisfaite","Inquiétude pour des détails que personne d’autre ne voit","Tendance à corriger avant de féliciter"],"behaviors":["Relire un message quatre fois avant de l’envoyer","Faire des listes, puis une liste des listes","Redresser un cadre chez les autres","Repérer la faute d’orthographe sur le menu","Refaire discrètement ce qui vient d’être fait"],"summary":{"soft":"Tu prends soin du monde par les détails : un geste juste, un mot précis, une chose remise à sa place. Ta rigueur est une forme de tendresse.","cash":"Tu as repéré la faute sur le menu avant de choisir ton plat. Tu aides tout le monde, avec une légère envie de tout refaire derrière.","expert":"Le Soleil en Vierge, signe mutable de terre, fonde l’identité sur le discernement et le service. Vous analysez avant d’agir ; l’exigence envers vous-même dépasse souvent celle que vous appliquez aux autres."},"roastAngles":{"soft":["Tu ranges, tu tries, tu répares : c’est ta façon de dire aux gens que tu tiens à eux."],"cash":["Tu as fait une liste pour te détendre. Puis tu l’as recopiée au propre, parce qu’elle penchait.","Tu dis “c’est très bien” en remettant la chose exactement comme tu l’aurais faite."],"expert":["Soleil en Vierge : mutabilité de terre. Vous perfectionnez ce qui existe, parfois au détriment de l’élan."]},"roastWeight":3,"avoid":["Réduire le placement à la maniaquerie du ménage","Associer le signe à la froideur ou à la pruderie"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:aquarius', 'fr', '1', '{"keywords":["collectif","réseaux","avant-garde","indépendance d’esprit"],"essence":"Uranus en Verseau se trouve dans le signe qu’il gouverne : le besoin de liberté y prend une dimension collective. Une génération tournée vers les réseaux, les idées neuves et l’égalité ; chez une personne, l’originalité cherche son groupe.","light":["Vision d’ensemble tournée vers ce qui s’invente","Sens de l’amitié et du projet commun","Tolérance réelle pour les parcours atypiques"],"shadow":["Distance affective derrière les grandes idées","Refus par principe de ce qui plaît au plus grand nombre","Entêtement sur une théorie devenue identité"],"behaviors":["Adopter un outil avant tout le monde et s’en lasser dès qu’il devient courant","Avoir beaucoup de connaissances et très peu de confidents","Défendre l’humanité entière en oubliant de répondre à un message"],"summary":{"soft":"Tu penses en « nous ». Tu sens ce qui pourrait changer pour tout le monde, et ta façon de vivre libre laisse de la place aux autres, à leurs bizarreries comme aux tiennes.","cash":"Tu aimes l’humanité en général. Ce sont les gens en particulier, avec leurs appels imprévus, qui te fatiguent.","expert":"Uranus en Verseau est en domicile : ses significations de rupture, de réseau et d’innovation s’y expriment sans filtre. Chez vous, l’indépendance se pense à l’échelle du groupe."},"roastAngles":{"soft":["Tu rêves d’un monde où chacun aurait sa place, même celles et ceux qui ne rentrent dans aucune case."],"cash":["Tu veux appartenir à un groupe, mais seulement à un groupe de gens qui refusent d’appartenir à un groupe.","Dès qu’une chose que tu aimes devient populaire, tu la quittes avec l’air de l’avoir toujours su."],"expert":["Uranus en Verseau, en domicile : idéal collectif affirmé, attachement individuel nettement plus distant."]},"roastWeight":1,"avoid":["Présenter la distance affective comme de la froideur de cœur","Associer le placement à une opinion ou à un camp"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:aries', 'fr', '1', '{"keywords":["impulsion","rupture franche","audace","indépendance"],"essence":"Uranus en Bélier associe le besoin de liberté à l’élan du premier pas : une génération qui préfère ouvrir la voie plutôt que demander la permission. À l’échelle d’une personne, la rupture se décide vite et s’assume seule.","light":["Courage de commencer sans modèle ni filet","Capacité à trancher quand tout le monde hésite","Énergie neuve face aux situations bloquées"],"shadow":["Impatience devant tout ce qui demande de la durée","Ruptures décidées sur un coup de sang","Difficulté à supporter une consigne"],"behaviors":["Quitter une réunion qui tourne en rond","Lancer un projet avant d’avoir fini de l’expliquer","Refuser un conseil pour le principe, puis l’appliquer en douce"],"summary":{"soft":"Tu portes l’élan de celles et ceux qui osent en premier. Quand quelque chose t’enferme, tu sens très vite qu’il faut bouger, et ce réflexe ouvre souvent la route aux autres.","cash":"Ta liberté n’attend pas le feu vert. Tu claques la porte d’abord, tu cherches où dormir ensuite.","expert":"Uranus en Bélier, placement générationnel, lie l’émancipation à l’initiative individuelle. Chez vous, le besoin de rupture s’exprime par l’acte immédiat plutôt que par la négociation."},"roastAngles":{"soft":["Tu as ce courage rare de commencer avant que quelqu’un ait dit que c’était possible."],"cash":["Tu quittes un groupe de discussion comme d’autres claquent une portière.","Le mode d’emploi, tu le lis après, pour vérifier que tu avais raison de t’en passer."],"expert":["Uranus en Bélier : l’indépendance s’y conquiert par l’action, quitte à brûler l’étape de la concertation."]},"roastWeight":1,"avoid":["Réduire le placement à de la colère","Présenter un trait de génération comme un destin personnel"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:cancer', 'fr', '1', '{"keywords":["foyer réinventé","racines mobiles","famille choisie","besoin d’espace"],"essence":"Uranus en Cancer déplace la rupture vers l’intime : foyer, famille, appartenance. Une génération qui redessine les manières d’habiter et de faire tribu ; chez une personne, le besoin de cocon cohabite avec celui de pouvoir en sortir.","light":["Capacité à créer un chez-soi hors des modèles reçus","Liens choisis, entretenus avec inventivité","Sensibilité qui devine ce qui étouffe dans un cadre familial"],"shadow":["Humeur imprévisible dès que l’intimité se resserre","Va-et-vient entre besoin d’attaches et envie de fuir","Susceptibilité face aux traditions imposées"],"behaviors":["Réaménager son salon à chaque changement de saison","Adorer les repas de famille et partir avant le dessert","Appeler « maison » un endroit que personne d’autre n’aurait choisi"],"summary":{"soft":"Tu as besoin d’un nid, mais d’un nid à ta façon. Tu inventes ta propre manière d’appartenir, et tu sais offrir aux tiens un refuge où chacun garde sa liberté.","cash":"Tu réclames un cocon, puis tu étouffes dedans. Résultat : tu déménages souvent, surtout dans ta tête.","expert":"Uranus en Cancer applique sa logique de rupture au registre du foyer et de la filiation. Chez vous, l’émancipation passe par une redéfinition de l’appartenance plus que par un départ."},"roastAngles":{"soft":["Tu construis des foyers qui ressemblent à des ports : on y revient parce qu’on peut en partir."],"cash":["Tu veux qu’on te laisse tranquille, mais tu vérifies quand même que tout le monde est bien rentré.","Les traditions familiales, tu les contestes à table, la bouche pleine du plat traditionnel."],"expert":["Uranus en Cancer : besoin de sécurité affective et besoin d’espace s’y disputent la priorité, par alternance."]},"roastWeight":1,"avoid":["Supposer une histoire familiale difficile","Parler de rupture avec les parents comme d’un fait"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:capricorn', 'fr', '1', '{"keywords":["structures réformées","autorité contestée","ambition autonome","règles réécrites"],"essence":"Uranus en Capricorne s’attaque aux cadres : hiérarchies, institutions, carrières toutes tracées. Une génération qui réforme de l’intérieur ; chez une personne, la liberté se gagne en bâtissant ses propres règles plutôt qu’en fuyant toute règle.","light":["Sens stratégique mis au service du changement","Capacité à moderniser une structure sans la détruire","Discipline personnelle, hors de toute hiérarchie imposée"],"shadow":["Défiance réflexe envers toute autorité","Froideur quand un plan est remis en cause","Tendance à remplacer un cadre rigide par un autre"],"behaviors":["Contester l’organigramme tout en visant le sommet","Monter sa propre structure pour ne plus avoir de supérieur","Rédiger un règlement intérieur pour une colocation de deux personnes"],"summary":{"soft":"Tu sais que la liberté se construit. Plutôt que de tout envoyer promener, tu bâtis patiemment des cadres plus justes, et cette rigueur rend tes changements durables.","cash":"Tu détestes qu’on te donne des ordres, alors tu vises le poste de la personne qui les donne.","expert":"Uranus en Capricorne, signe cardinal de terre, applique la rupture aux structures d’autorité et aux trajectoires sociales. Chez vous, l’émancipation prend la forme d’une réforme méthodique."},"roastAngles":{"soft":["Tu changes les règles en les comprenant mieux que ceux qui les ont écrites."],"cash":["Tu fais la révolution en costume, avec un plan sur cinq ans et un budget prévisionnel.","Tu contestes la hiérarchie, sauf quand elle a le bon goût de te placer tout en haut."],"expert":["Uranus en Capricorne : la liberté y passe par la maîtrise des cadres, non par leur abandon."]},"roastWeight":1,"avoid":["Glisser vers un commentaire sur les institutions ou les opinions","Donner un conseil de carrière"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:gemini', 'fr', '1', '{"keywords":["idées neuves","curiosité électrique","parole libre","zapping"],"essence":"Uranus en Gémeaux électrise la pensée et la parole : une génération qui bouscule les manières d’apprendre, de dire et de relier les idées. Chez une personne, la liberté passe par le droit de changer d’avis et de sujet.","light":["Esprit vif qui relie des idées éloignées","Goût d’apprendre hors des cadres prévus","Parole qui débloque une conversation figée"],"shadow":["Attention qui saute avant d’avoir fini","Opinions changées trop vite pour être suivies","Agitation mentale difficile à couper"],"behaviors":["Ouvrir dix onglets pour répondre à une seule question","Finir les phrases des autres, pas toujours dans le bon sens","Abandonner un livre au milieu pour en commencer un autre"],"summary":{"soft":"Ton esprit a besoin d’air. Tu captes les idées au vol, tu les relies autrement, et ta curiosité ouvre des fenêtres là où les autres voyaient des murs.","cash":"Tu changes d’avis plus vite que de sujet, et tu changes de sujet au milieu de ta propre phrase.","expert":"Uranus en Gémeaux, signe mutable d’air, porte la rupture sur le terrain mental : langage, apprentissages, circulation des idées. Chez vous, l’indépendance est d’abord intellectuelle."},"roastAngles":{"soft":["Tu penses en éclairs, et certains de ces éclairs illuminent vraiment toute la pièce."],"cash":["Tu envoies sept messages d’affilée là où un seul aurait suffi, et le dernier contredit le premier.","Tu défends une idée avec passion le lundi et son contraire, avec la même passion, le jeudi."],"expert":["Uranus en Gémeaux : pensée par associations rapides, brillante dans l’intuition, moins dans la continuité."]},"roastWeight":1,"avoid":["Confondre vivacité d’esprit et superficialité","Évoquer un manque de concentration comme un diagnostic"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:leo', 'fr', '1', '{"keywords":["singularité affichée","création","fierté rebelle","panache"],"essence":"Uranus en Lion relie la liberté au droit d’être unique et de le montrer. Une génération qui revendique l’expression de soi et la création sans tutelle ; chez une personne, l’originalité devient une affaire de fierté.","light":["Créativité qui ose le geste personnel","Chaleur communicative au service d’idées neuves","Courage d’assumer sa différence en public"],"shadow":["Besoin d’attirer les regards jusque dans la dissidence","Orgueil piqué quand l’originalité passe inaperçue","Tendance à confondre liberté et caprice"],"behaviors":["Refuser de s’habiller comme le reste de la soirée, puis guetter les réactions","Signer chaque création, même une liste de courses","Quitter un projet où sa patte ne se voit plus"],"summary":{"soft":"Tu as une façon bien à toi de briller : pas pour écraser, mais pour montrer qu’on a le droit d’être soi. Ta singularité donne de l’élan aux autres.","cash":"Tu veux te distinguer de tout le monde, à condition que tout le monde le remarque.","expert":"Uranus en Lion, signe fixe de feu, attache l’indépendance à l’expression personnelle et à l’acte créateur. Chez vous, la rupture prend volontiers une forme démonstrative."},"roastAngles":{"soft":["Tu oses être toi à voix haute, et ça donne aux autres la permission d’essayer."],"cash":["Tu joues la carte de l’électron libre, mais avec un éclairage de scène soigneusement réglé.","Tu ne suis aucune mode : tu attends juste qu’on te demande d’où vient la tienne."],"expert":["Uranus en Lion : l’originalité s’y vit comme une question d’honneur, et supporte mal l’anonymat."]},"roastWeight":1,"avoid":["Réduire le placement à de l’égocentrisme","Commenter l’apparence ou le style vestimentaire de la personne"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:libra', 'fr', '1', '{"keywords":["liens réinventés","couple hors modèle","équité","indépendance à deux"],"essence":"Uranus en Balance bouscule les codes de la relation : couple, association, contrat. Une génération qui expérimente d’autres façons de s’engager ; chez une personne, le lien n’a de valeur que s’il laisse de l’air.","light":["Sens de l’équité appliqué aux relations","Capacité à inventer des accords sur mesure","Diplomatie au service d’idées nouvelles"],"shadow":["Engagement accepté puis remis en cause d’un coup","Besoin d’espace exprimé trop tard","Indécision entre fusion et distance"],"behaviors":["Renégocier les règles d’une colocation au bout d’une semaine","Vouloir vivre ensemble, mais chacun avec ses clés","Rompre poliment, avec un message très bien tourné"],"summary":{"soft":"Tu crois aux liens qui respirent. Tu cherches une façon d’être à deux où personne ne s’efface, et tu as le talent d’inventer des accords qui n’existaient pas avant toi.","cash":"Tu veux une relation stable, libre, équilibrée et surprenante. Tu attends surtout que l’autre devine dans quel ordre.","expert":"Uranus en Balance, signe cardinal d’air, situe la rupture dans le champ relationnel et contractuel. Chez vous, l’indépendance se négocie au sein du lien plutôt que contre lui."},"roastAngles":{"soft":["Tu inventes des façons d’aimer où chacun garde sa fenêtre ouverte."],"cash":["Tu dis « on fait comme tu veux », puis tu proposes un amendement à chaque point de l’accord.","Tu réclames de l’air dans le couple pile le jour où l’autre commence à s’y sentir bien."],"expert":["Uranus en Balance : l’engagement y reste révocable, et l’équité prime sur la permanence."]},"roastWeight":1,"avoid":["Annoncer une séparation ou juger un choix de vie amoureuse","Présumer de l’orientation ou du modèle de couple"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:pisces', 'fr', '1', '{"keywords":["imaginaire libéré","intuition","frontières dissoutes","rêve en mouvement"],"essence":"Uranus en Poissons fait passer la rupture par l’imaginaire et la sensibilité. Une génération qui dissout les frontières entre les mondes, les arts, les croyances ; chez une personne, la liberté ressemble à une échappée plus qu’à un combat.","light":["Intuitions soudaines, souvent justes","Imagination qui renouvelle les formes","Compassion sans condition d’appartenance"],"shadow":["Évasion quand la réalité demande une décision","Changements flous, annoncés sans être accomplis","Difficulté à tenir une limite claire"],"behaviors":["Disparaître d’une soirée sans dire au revoir","Changer de projet de vie après un rêve marquant","Répondre « on verra » à toute question comportant une date"],"summary":{"soft":"Ta liberté passe par le rêve. Tu captes des choses que personne n’a encore formulées, et ton imagination trouve des passages là où la logique ne voyait qu’un mur.","cash":"Tu ne claques pas la porte : tu t’évapores. On te cherche encore que tu as déjà changé de vie intérieure.","expert":"Uranus en Poissons, signe mutable d’eau, porte la rupture sur le plan de l’imaginaire et de la sensibilité collective. Chez vous, l’émancipation procède par dissolution plus que par affrontement."},"roastAngles":{"soft":["Tu as des éclairs d’intuition qui arrivent de loin, comme des cartes postales sans timbre."],"cash":["Ta façon de rompre avec une situation : ne plus y penser très fort jusqu’à ce qu’elle disparaisse.","Tu as une idée géniale sous la douche et tu l’as oubliée avant d’avoir trouvé la serviette."],"expert":["Uranus en Poissons : l’intuition y devance le raisonnement, et la limite claire s’y perd volontiers."]},"roastWeight":1,"avoid":["Parler de fuite dans des substances ou de fragilité psychique","Viser une croyance ou une spiritualité précise"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:sagittarius', 'fr', '1', '{"keywords":["croyances bousculées","horizon ouvert","liberté de pensée","ailleurs"],"essence":"Uranus en Sagittaire ouvre grand l’horizon : convictions, savoirs, voyages. Une génération qui conteste les vérités reçues et cherche son propre sens ; chez une personne, la liberté se mesure à la distance qu’il reste à parcourir.","light":["Ouverture d’esprit curieuse des autres cultures","Enthousiasme pour les idées qui élargissent le cadre","Franchise dans le débat"],"shadow":["Certitudes neuves défendues avec autant de raideur que les anciennes","Fuite en avant dès que l’engagement se précise","Promesses plus larges que le calendrier"],"behaviors":["Réserver un aller simple sur un coup de tête","Changer de philosophie de vie après un seul documentaire","Contredire le professeur dès la première séance"],"summary":{"soft":"Tu as besoin d’horizon pour respirer. Tu remets en question ce qu’on t’a appris, non par esprit de contradiction, mais parce que tu cherches un sens qui soit vraiment le tien.","cash":"Tu refuses qu’on te dise quoi penser, puis tu expliques à toute la tablée quoi penser. Avec des anecdotes de voyage.","expert":"Uranus en Sagittaire, signe mutable de feu, déplace la rupture vers les croyances et les systèmes de pensée. Chez vous, l’indépendance est d’abord une liberté de conviction et de mouvement."},"roastAngles":{"soft":["Tu cherches ta vérité comme on cherche un pays : en marchant, le nez au vent."],"cash":["Tu as une nouvelle vision du monde à chaque retour de week-end, et un exposé prêt pour le lundi.","Dès qu’on te parle d’engagement, tu regardes les horaires de train. Juste pour voir."],"expert":["Uranus en Sagittaire : contestation des dogmes, parfois remplacés par un dogme de la liberté."]},"roastWeight":1,"avoid":["Viser une croyance ou une confession précise","Annoncer un départ à l’étranger"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:scorpio', 'fr', '1', '{"keywords":["tabous bousculés","vérité crue","intensité","tout ou rien"],"essence":"Uranus en Scorpion porte la rupture vers ce qui se tait : secrets, rapports de force, attachements profonds. Une génération qui brise les non-dits ; chez une personne, la liberté passe par des remises à plat radicales.","light":["Lucidité devant ce que les autres évitent de regarder","Capacité à se réinventer après une crise","Refus des faux-semblants"],"shadow":["Radicalité qui ne laisse aucune porte de sortie","Goût de la provocation sur les sujets sensibles","Méfiance soudaine envers les proches"],"behaviors":["Poser la question que toute la tablée évitait","Supprimer d’un coup des années de photos et de contacts","Disparaître le temps de se transformer, puis revenir sans explication"],"summary":{"soft":"Tu ne fais pas semblant. Quand quelque chose sonne faux, tu préfères tout remettre à plat, et cette exigence de vérité finit souvent par libérer les autres aussi.","cash":"Chez toi, pas de demi-mesure : soit tu gardes un secret pendant dix ans, soit tu le lâches en plein dîner.","expert":"Uranus en Scorpion, signe fixe d’eau où plusieurs auteurs le disent exalté, porte l’émancipation sur les zones de pouvoir et de non-dit. Chez vous, la rupture est totale ou n’est pas."},"roastAngles":{"soft":["Tu oses regarder là où ça dérange, et c’est souvent là que les choses se dénouent."],"cash":["Tu fais le ménage dans tes contacts comme on vide un appartement : rien ne reste, même pas les cadres.","Une conversation légère te met mal à l’aise : tu cherches aussitôt ce qu’elle cache."],"expert":["Uranus en Scorpion : l’exaltation que lui prêtent certains auteurs y donne des ruptures profondes, peu réversibles."]},"roastWeight":1,"avoid":["Tout vocabulaire de sexualité ou de disparition","Dramatiser : intensité ne veut pas dire danger"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:taurus', 'fr', '1', '{"keywords":["valeurs bousculées","matière","lenteur rebelle","autonomie concrète"],"essence":"Uranus en Taureau fait passer le changement par le concret : rapport aux ressources, au confort, au vivant. Une génération qui remet en cause ce qui paraissait solide ; chez une personne, la liberté se construit lentement, puis ne se négocie plus.","light":["Réformes patientes qui tiennent dans la durée","Inventivité pratique, appliquée au quotidien","Fidélité à ses propres valeurs plutôt qu’aux usages"],"shadow":["Résistance obstinée au changement venu des autres","Revirements soudains après une longue immobilité","Attachement au confort présenté comme un principe"],"behaviors":["Garder la même tasse depuis toujours et changer de métier en une semaine","Bricoler une solution maison plutôt qu’acheter celle de tout le monde","Refuser de se presser quand quelqu’un réclame une adaptation rapide"],"summary":{"soft":"Chez toi, la liberté a les pieds sur terre. Tu changes peu, mais quand tu changes, c’est du solide : tu réinventes tranquillement ta façon de vivre, de posséder, de savourer.","cash":"Tu refuses de bouger pendant des lustres, puis tu retournes toute ta vie un mardi matin. Sans prévenir, évidemment.","expert":"Uranus en Taureau, signe fixe de terre, inscrit la rupture dans la matière et les valeurs. Chez vous, l’émancipation avance par longues résistances suivies de bascules nettes."},"roastAngles":{"soft":["Tu fais ta révolution à feu doux, et c’est pour ça qu’elle tient."],"cash":["Tu mets une éternité à changer de canapé et une soirée à changer de vie.","Ton idée de la rébellion : faire exactement pareil, mais à ta façon et à ton rythme."],"expert":["Uranus en Taureau : l’inertie puis la secousse, rarement l’entre-deux. Le changement s’y vit par paliers."]},"roastWeight":1,"avoid":["Parler d’instabilité financière ou donner un conseil d’argent","Réduire le signe à l’entêtement"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:uranus:virgo', 'fr', '1', '{"keywords":["méthode réinventée","précision","travail autrement","esprit critique"],"essence":"Uranus en Vierge porte la rupture dans le quotidien : façons de travailler, d’organiser, de soigner les détails. Une génération qui réforme par la technique et l’analyse ; chez une personne, la liberté passe par une méthode à soi.","light":["Ingéniosité pour améliorer ce qui fonctionne mal","Regard critique qui repère la faille utile","Autonomie dans l’organisation du travail"],"shadow":["Nervosité devant l’imprévu mal rangé","Critique permanente des procédures des autres","Perfectionnisme qui retarde le changement voulu"],"behaviors":["Refaire le tableau de suivi de toute l’équipe sans que personne l’ait demandé","Tester plusieurs applications d’organisation en parallèle","Corriger une notice avant de s’en servir"],"summary":{"soft":"Tu changes le monde par petites touches précises. Là où d’autres rêvent de grand soir, tu améliores un geste, une habitude, un outil, et tout fonctionne mieux.","cash":"Ta révolution tient dans un tableur. Tu ne renverses pas la table : tu la remets d’équerre et tu notes qui l’avait déplacée.","expert":"Uranus en Vierge, signe mutable de terre, oriente l’innovation vers les méthodes, les outils et le travail quotidien. Chez vous, l’indépendance se joue dans l’organisation concrète."},"roastAngles":{"soft":["Tu réinventes le quotidien un détail après l’autre, et le quotidien te dit merci."],"cash":["Tu contestes le règlement, mais avec des notes de bas de page et une proposition de version corrigée.","Tu as une routine très stricte que tu changes entièrement toutes les trois semaines."],"expert":["Uranus en Vierge : l’esprit de réforme s’y exerce par l’analyse, au risque de l’agitation perfectionniste."]},"roastWeight":1,"avoid":["Glisser vers des remarques sur l’hygiène de vie ou le bien-être médical","Réduire le signe à la maniaquerie"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:aquarius', 'fr', '1', '{"keywords":["amitié amoureuse","indépendance","originalité des goûts","distance","liberté mutuelle"],"essence":"Vénus en Verseau aime dans la liberté et la complicité d’esprit : l’affection ressemble à une amitié élective, se méfie de la fusion et s’attache à ce qui sort de l’ordinaire.","light":["Respect de l’indépendance de l’autre","Loyauté de fond, proche de l’amitié","Ouverture aux personnes et aux goûts atypiques"],"shadow":["Distance quand l’émotion devient trop proche","Difficulté avec les démonstrations attendues","Besoin d’espace perçu comme de l’indifférence"],"behaviors":["Nouer d’abord une complicité, s’attacher ensuite","Oublier une date symbolique mais se souvenir d’une théorie évoquée deux ans plus tôt","Préférer une soirée chacun de son côté suivie d’un long débrief","Avoir des goûts que personne d’autre ne partage dans l’entourage"],"summary":{"soft":"Tu aimes en laissant de l’espace, comme on ouvre une fenêtre. Avec toi, chacun peut rester soi-même, et c’est une forme rare de tendresse.","cash":"Tu veux une relation fusionnelle, mais à distance, avec des jours sans nouvelles. Ton « je t’aime bien » est une déclaration majeure.","expert":"Vénus en Verseau, signe d’air fixe, fonde le lien sur l’affinité d’esprit et l’autonomie : vous aimez sans fusion, avec une fidélité de principe plus que d’effusion."},"roastAngles":{"soft":["Tu offres à ceux que tu aimes le plus précieux des cadeaux : la place d’être eux-mêmes."],"cash":["Tu réponds « c’est gentil » à une déclaration, puis tu parles d’un documentaire.","Tu disparais trois jours, puis tu reviens avec un lien d’article et zéro explication."],"expert":["Affect fixe d’air : vous restez fidèle à une personne comme à une idée, de loin et longtemps."]},"roastWeight":2,"avoid":["Présenter la distance comme de la froideur","Dire que ce placement refuse l’attachement"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:aries', 'fr', '1', '{"keywords":["coup de cœur","conquête","spontanéité","impatience affective","franchise amoureuse"],"essence":"Vénus en Bélier est en exil : l’affection s’exprime avec fougue et sans détour, le goût va à la nouveauté et à la conquête, et l’intérêt retombe quand tout devient trop facile.","light":["Spontanéité et franchise des sentiments","Audace pour faire le premier pas","Enthousiasme qui ranime la relation"],"shadow":["Impatience devant la lenteur de l’autre","Intérêt qui faiblit une fois la conquête faite","Tendance à transformer le lien en compétition"],"behaviors":["Faire le premier pas sans attendre de signe","Déclarer sa flamme, puis réfléchir","S’ennuyer dès que la relation ronronne","Acheter sur un coup de tête et s’en lasser en une semaine"],"summary":{"soft":"Tu aimes comme on allume un feu : vite, franchement, de tout ton élan. Avec toi, personne n’a à deviner ce que tu ressens.","cash":"Tu adores courir après quelqu’un. Le problème commence quand la personne s’arrête et se retourne.","expert":"Vénus en Bélier est en exil, en feu cardinal : l’affect y est direct et conquérant ; vous aimez l’élan initial et supportez mal la routine du lien."},"roastAngles":{"soft":["Ton cœur démarre au quart de tour et ne sait pas faire semblant de ralentir."],"cash":["Tu envoies « tu me plais » pendant que les autres hésitent encore sur la ponctuation.","Tu veux une histoire sérieuse, tout de suite, là, avant la fin de la soirée."],"expert":["Vénus en exil : chez vous, l’envie de plaire prend volontiers la forme d’un défi à relever."]},"roastWeight":2,"avoid":["Présenter l’exil comme une incapacité à aimer","Réduire ce placement à de l’inconstance"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:cancer', 'fr', '1', '{"keywords":["tendresse","besoin de sécurité","attachement","protection","nostalgie affective"],"essence":"Vénus en Cancer aime en protégeant : l’affection se montre par le soin, la présence et les attentions du quotidien, et demande en retour un sentiment de sécurité.","light":["Tendresse et dévouement envers les proches","Mémoire des goûts et des dates qui comptent","Capacité à créer un foyer chaleureux"],"shadow":["Susceptibilité quand l’attention se relâche","Tendance à attendre que l’autre devine","Difficulté à tourner la page d’une histoire"],"behaviors":["Préparer le plat préféré de l’autre sans attendre la demande","Garder les tickets de cinéma et les petits mots","Bouder en silence plutôt que formuler un reproche","Réclamer un message à l’arrivée après chaque trajet"],"summary":{"soft":"Tu aimes en prenant soin : un plat, une couverture, un mot au bon moment. Ton affection est un abri, et tu n’oublies rien de ce qui compte pour l’autre.","cash":"Tu dis « fais comme tu veux » et tu notes la réponse. Tu gardes encore le ticket du premier cinéma, plié dans un tiroir.","expert":"Vénus en Cancer, signe d’eau cardinal, exprime l’affection par le soin et la protection ; vous cherchez la sécurité affective et retenez longtemps ce qui a touché le lien."},"roastAngles":{"soft":["Tu aimes comme on borde quelqu’un : avec soin, jusqu’au dernier coin de la couverture."],"cash":["Tu réponds « non non, tout va bien » avec la voix de quelqu’un pour qui rien ne va.","Tu envoies « couvre-toi » à un adulte qui part acheter du pain."],"expert":["Affect d’eau cardinale : vous donnez beaucoup, et tenez un compte discret de la réciprocité."]},"roastWeight":3,"avoid":["Présenter le besoin de sécurité comme de la dépendance","Réduire ce placement à un rôle maternel"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:capricorn', 'fr', '1', '{"keywords":["réserve","engagement durable","pudeur","sens des responsabilités","fidélité"],"essence":"Vénus en Capricorne aime avec sérieux et retenue : l’affection se construit dans la durée, se prouve par des actes et des engagements tenus, et s’exprime peu en paroles.","light":["Fiabilité et constance dans l’engagement","Loyauté qui résiste au temps","Goût sobre, attaché à ce qui dure"],"shadow":["Pudeur qui passe pour de la distance","Difficulté à montrer sa vulnérabilité","Tendance à faire passer le travail avant le lien"],"behaviors":["Montrer son affection en réglant un problème pratique","Mettre des mois à dire ce qui est ressenti","Évaluer le sérieux de l’autre avant de s’attacher","Offrir un cadeau utile, choisi pour durer dix ans"],"summary":{"soft":"Tu aimes sans grands mots, mais on peut compter sur toi, année après année. Ton affection est une demeure solide, bâtie pierre à pierre.","cash":"Tu montres ton amour par ta fiabilité, ce qui est magnifique et totalement invisible. Ta déclaration tient en une ligne, relue deux fois.","expert":"Vénus en Capricorne, signe de terre cardinal, donne un affect réservé et durable : vous aimez par l’engagement tenu et la preuve dans le temps, plus que par l’effusion."},"roastAngles":{"soft":["Ton amour ne fait pas de bruit : il arrive à l’heure, et il reste."],"cash":["Tu dis « je tiens à toi » sur le ton d’une validation de budget annuel.","Tu planifies une soirée romantique avec un ordre du jour et une heure de fin."],"expert":["Affect cardinal de terre : vous traitez l’engagement comme un contrat et l’honorez comme tel."]},"roastWeight":2,"avoid":["Présenter la réserve comme une absence de sentiments","Réduire ce placement à l’intérêt ou au calcul"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:gemini', 'fr', '1', '{"keywords":["séduction par l’esprit","complicité","légèreté","besoin de variété","humour"],"essence":"Vénus en Gémeaux aime par l’échange : l’attirance naît de la conversation, de l’humour et de la curiosité, et l’affection a besoin de variété et de légèreté pour durer.","light":["Complicité et humour dans la relation","Curiosité sincère pour l’autre","Capacité à garder le lien vivant et léger"],"shadow":["Difficulté à supporter les silences et la routine","Papillonnage des goûts et des envies","Tendance à plaisanter pour éviter le sérieux"],"behaviors":["Tomber sous le charme d’une répartie avant tout le reste","Envoyer des messages toute la journée à la personne aimée","Changer de style, de musique favorite et de passion tous les trimestres","Répondre par une blague à une déclaration"],"summary":{"soft":"Chez toi, le cœur passe par les mots : tu aimes rire, apprendre, discuter jusqu’à tard. Ton affection est légère comme une conversation qui ne veut pas finir.","cash":"On te séduit avec une bonne répartie et on te perd avec un silence de dix minutes. Ton grand amour doit d’abord être une bonne conversation.","expert":"Vénus en Gémeaux, signe d’air mutable, fait de l’échange le cœur du lien : vous aimez par la parole et la complicité d’esprit, et la monotonie vous éloigne."},"roastAngles":{"soft":["Tu tombes sous le charme d’une phrase bien tournée comme d’autres d’un regard."],"cash":["Tu réponds « ahah » à « je t’aime », puis tu envoies une image drôle pour compenser.","Tu flirtes par jeux de mots, et tu t’étonnes que la personne ait compris autre chose."],"expert":["Affect d’air mutable : vous vous attachez à qui renouvelle la conversation, plus qu’à qui la rassure."]},"roastWeight":2,"avoid":["Présenter la légèreté comme de l’infidélité","Dire que ce placement ne s’attache pas"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:leo', 'fr', '1', '{"keywords":["générosité","romantisme","besoin d’admiration","loyauté","goût du faste"],"essence":"Vénus en Lion aime avec éclat et générosité : l’affection se déclare, se célèbre et se montre, et attend en retour admiration, loyauté et attentions visibles.","light":["Générosité et chaleur dans l’affection","Loyauté envers la personne choisie","Sens de la fête et du geste romantique"],"shadow":["Besoin d’occuper le centre de l’attention de l’autre","Fierté blessée par l’indifférence","Tendance à la mise en scène des sentiments"],"behaviors":["Offrir un cadeau spectaculaire pour une petite occasion","Attendre un compliment après un effort vestimentaire","Organiser un anniversaire comme une première de gala","Se vexer d’un message resté sans réponse enthousiaste"],"summary":{"soft":"Tu aimes en grand, avec le cœur sur la main. Tu sais faire sentir à quelqu’un qu’il compte, et tu donnes sans compter quand tu as choisi.","cash":"Tu donnes tout, en grand, avec des rubans. En échange tu demandes peu de chose : une admiration constante et sincère.","expert":"Vénus en Lion, signe de feu fixe, donne un affect généreux et démonstratif : vous aimez avec loyauté et panache, et l’indifférence vous atteint plus que le conflit."},"roastAngles":{"soft":["Ton amour arrive toujours avec un peu de lumière en plus, comme un jour de fête."],"cash":["Tu fais un cadeau somptueux, puis tu guettes la réaction comme un jury de concours.","Tu dis « ce n’est rien » en attendant que quelqu’un insiste : c’est énorme."],"expert":["Affect fixe de feu : vous pardonnez une dispute plus aisément qu’un anniversaire oublié."]},"roastWeight":3,"avoid":["Réduire ce placement à de la vanité","Présenter le besoin d’admiration comme de l’égoïsme"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:libra', 'fr', '1', '{"keywords":["harmonie","charme","goût du couple","élégance","évitement du conflit"],"essence":"Vénus en Balance est en domicile : l’affection cherche l’harmonie, l’équité et l’élégance, le lien à deux est une priorité, et tout désaccord ouvert coûte beaucoup.","light":["Charme, tact et art de mettre à l’aise","Sens du partage équitable dans la relation","Goût raffiné, sens des accords et des proportions"],"shadow":["Évitement du conflit jusqu’à l’accumulation","Dépendance au regard et à l’approbation de l’autre","Difficulté à dire non"],"behaviors":["Dire oui pour préserver l’ambiance, puis le regretter","Accorder ses envies à celles de l’autre sans y penser","Soigner la présentation d’une table, d’un message, d’un cadeau","Préférer un compromis tiède à une dispute franche"],"summary":{"soft":"Tu as le don de l’accord : avec toi, les choses s’adoucissent et chacun trouve sa place. Tu aimes à deux, avec élégance et attention.","cash":"Tu détestes tellement les disputes que tu dis oui à tout, puis tu en veux à tout le monde, poliment, avec le sourire.","expert":"Vénus en Balance occupe son domicile d’air cardinal : l’affect y recherche l’accord et la réciprocité ; vous aimez dans le lien à deux et redoutez la dissonance."},"roastAngles":{"soft":["Tu arranges les cœurs comme un bouquet : chaque chose à sa place, rien qui dépasse."],"cash":["Tu réponds « comme tu préfères » alors que tu as une préférence très nette.","Tu trouves du charme à tout le monde, ce qui complique sérieusement le tri."],"expert":["Vénus en domicile : vous cédez sur le fond pour sauver la forme, et le ressentiment s’accumule."]},"roastWeight":3,"avoid":["Présenter le goût de l’harmonie comme de la superficialité","Dire que ce placement ne sait pas vivre en solo"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:pisces', 'fr', '1', '{"keywords":["romantisme","dévouement","compassion","idéalisation","don de soi"],"essence":"Vénus en Poissons est en exaltation : l’affection est sans frontière, tendre et compatissante, portée à idéaliser l’être aimé et à donner sans compter, jusqu’à s’oublier.","light":["Tendresse et compassion sans condition","Sensibilité artistique et romantique","Capacité à pardonner"],"shadow":["Idéalisation de l’autre au mépris des faits","Difficulté à poser des limites","Attirance pour les personnes à sauver"],"behaviors":["Trouver des excuses à quelqu’un qui n’en a pas demandé","Pleurer devant un film, une chanson, une publicité","S’attacher à une histoire possible plus qu’à la personne réelle","Tout donner, puis s’étonner de n’avoir plus rien en réserve"],"summary":{"soft":"Tu aimes sans mesure et sans calcul, avec une tendresse qui comprend tout. Ton cœur voit le meilleur en chacun, et c’est un cadeau rare.","cash":"Tu tombes sous le charme du potentiel des gens. On te dit « c’est compliqué chez moi » et tu entends « défi accepté ».","expert":"Vénus en Poissons est en exaltation, en eau mutable : l’affect y est oblatif et idéalisant ; vous aimez sans réserve et discernez tard les limites du lien."},"roastAngles":{"soft":["Ton cœur est une mer sans digue : tout le monde y trouve un peu de douceur."],"cash":["Tu as déjà imaginé toute l’histoire, emménagement compris, avant le premier café.","Tu pardonnes avant même les excuses, et parfois avant la bêtise."],"expert":["Vénus exaltée : vous prêtez à l’être aimé des qualités que les faits n’ont pas encore confirmées."]},"roastWeight":3,"avoid":["Présenter le dévouement comme de la naïveté","Réduire ce placement au sacrifice"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:sagittarius', 'fr', '1', '{"keywords":["liberté","enthousiasme","goût de l’aventure","franchise","peur de l’enfermement"],"essence":"Vénus en Sagittaire aime dans le mouvement : l’affection est joyeuse, franche et généreuse, attirée par l’ailleurs et la découverte, et se rétracte dès que le lien ressemble à une cage.","light":["Enthousiasme et bonne humeur dans la relation","Franchise sur ce qui est ressenti","Goût de grandir et de découvrir à deux"],"shadow":["Fuite devant les attentes trop précises","Serments lancés dans l’élan du moment","Franchise qui manque parfois de délicatesse"],"behaviors":["Proposer un voyage au deuxième café","Craquer pour un accent, un récit de voyage ou un rire sonore","Répondre « rien ne presse » à toute question sur la suite","Avoir besoin d’air après trois soirées d’affilée à la maison"],"summary":{"soft":"Tu aimes à ciel ouvert : avec joie, curiosité et franchise. Ton affection donne de l’air et l’envie d’aller voir plus loin.","cash":"Tu veux quelqu’un qui te suive au bout du monde et qui ne demande jamais à quelle heure tu rentres.","expert":"Vénus en Sagittaire, signe de feu mutable, associe l’affection à l’expansion : vous aimez qui élargit votre horizon et vivez mal toute attente perçue comme une entrave."},"roastAngles":{"soft":["Ton cœur voyage léger : beaucoup d’élan, peu de bagages, toujours une place à côté."],"cash":["Tu dis « j’ai besoin de liberté » à quelqu’un qui proposait juste un brunch dimanche.","Tu craques pour quelqu’un à l’aéroport, et l’intérêt retombe à la douane."],"expert":["Affect mutable de feu : vous promettez fidélité à l’élan, plus rarement à l’emploi du temps."]},"roastWeight":2,"avoid":["Dire que ce placement est incapable de s’engager","Réduire le besoin d’espace à de l’inconstance"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:scorpio', 'fr', '1', '{"keywords":["intensité","exclusivité","loyauté absolue","jalousie","profondeur du lien"],"essence":"Vénus en Scorpion est en exil : l’affection est intense, exclusive et entière, le lien se veut total, et la confiance se donne rarement mais sans retour.","light":["Loyauté profonde envers la personne aimée","Capacité à s’engager entièrement","Lucidité sur les sentiments, les siens et ceux d’autrui"],"shadow":["Jalousie et besoin de contrôle","Difficulté à pardonner une trahison","Mise à l’épreuve silencieuse de l’autre"],"behaviors":["Tout observer au début d’une relation sans rien montrer","Tester la sincérité de l’autre avant d’accorder sa confiance","Remarquer un prénom nouveau dans une conversation","Rompre net, sans retour, après une déloyauté"],"summary":{"soft":"Tu aimes en profondeur, sans demi-mesure. Quand tu donnes ta confiance, c’est un trésor : tu restes là, même quand tout devient difficile.","cash":"Tu ne tombes pas sous le charme, tu mènes l’enquête. Avec toi c’est tout ou rien, et « rien » vient avec un blocage sur tous les réseaux.","expert":"Vénus en Scorpion est en exil, en eau fixe : l’affect y est absolu et possessif ; vous engagez tout dans le lien et supportez mal la tiédeur comme le partage."},"roastAngles":{"soft":["Ton cœur ne connaît pas la demi-saison : c’est le plein hiver ou le plein été."],"cash":["Tu dis « je ne surveille personne » en connaissant ses horaires par cœur.","Tu as vu qui a aimé sa photo, et à quelle heure. Tu n’as rien dit. Pour l’instant."],"expert":["Vénus en exil : vous n’accordez pas l’affection, vous la confiez sous serment."]},"roastWeight":3,"avoid":["Réduire ce placement à la jalousie","Insister sur une dimension charnelle ou sulfureuse"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:taurus', 'fr', '1', '{"keywords":["plaisir des sens","fidélité","goût du confort","possessivité","gourmandise"],"essence":"Vénus en Taureau est en domicile : l’affection est stable, tactile et fidèle, le goût va au confort, à la bonne table et aux matières agréables, et l’attachement se construit lentement.","light":["Fidélité et constance dans l’attachement","Art de créer du confort et de la douceur","Goût sûr pour la qualité"],"shadow":["Possessivité envers les personnes comme envers les objets","Résistance au changement dans la relation","Tendance à confondre affection et habitude"],"behaviors":["Exprimer son affection par un bon repas plutôt que par un discours","Garder la même adresse favorite pendant des années","Toucher les tissus dans un magasin avant de regarder le prix","Mettre longtemps à s’attacher, et plus longtemps encore à se détacher"],"summary":{"soft":"Tu aimes avec constance et douceur, comme on prend soin d’un jardin. Près de toi, on se sent au chaud et l’on a envie de rester.","cash":"Ta langue de l’amour, c’est le plaid, le fromage et la même série pour la troisième fois. Et personne ne touche à ton dessert.","expert":"Vénus en Taureau occupe son domicile de terre fixe : l’attachement y est durable et sensoriel ; vous aimez par la présence, le confort partagé et la fidélité aux habitudes."},"roastAngles":{"soft":["Ton affection a le goût du pain chaud : simple, généreuse, et l’on y revient toujours."],"cash":["Tu dis « je partage tout » mais ta fourchette monte la garde autour de l’assiette.","Tu as le même parfum, le même canapé et le même plat préféré depuis le lycée."],"expert":["Vénus en domicile : vous jugez la qualité d’un lien à sa durée et à son confort."]},"roastWeight":3,"avoid":["Réduire ce placement au matérialisme","Présenter la fidélité comme de l’immobilisme"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
insert into public.interpretation_kb (key, locale, kb_version, body, review_status) values ('planet_sign:venus:virgo', 'fr', '1', '{"keywords":["pudeur","amour par le service","discernement","exigence","attention aux détails"],"essence":"Vénus en Vierge est en chute : l’affection se prouve par des gestes utiles plutôt que par des déclarations, avec pudeur, discernement et un regard exigeant sur le lien.","light":["Attention concrète aux besoins de l’autre","Fiabilité et constance discrète","Goût de la simplicité soignée"],"shadow":["Tendance à analyser les sentiments au lieu de les dire","Critique du détail qui masque la tendresse","Difficulté à recevoir un compliment"],"behaviors":["Réparer, ranger ou organiser pour dire son affection","Remarquer le petit défaut d’un cadeau avant de dire merci","Répondre à un compliment par une explication technique","Se souvenir de la marque de café et des horaires de chacun"],"summary":{"soft":"Tu aimes sans bruit, par mille gestes précis : un détail réglé, une chose réparée, une attention que personne d’autre n’aurait eue.","cash":"Tu ne dis pas « je t’aime », tu dis « j’ai rangé tes papiers et rempli le frigo ». C’est pareil, en plus utile.","expert":"Vénus en Vierge est en chute, en terre mutable : l’affect s’y exprime par le service et la retenue ; vous aimez avec discernement et l’abandon vous coûte."},"roastAngles":{"soft":["Ta tendresse se cache dans les détails, là où seuls les regards attentifs la trouvent."],"cash":["On te dit « tu me manques » et tu réponds avec un créneau dans l’agenda.","Tu reçois un bouquet et tu recoupes les tiges avant de dire merci."],"expert":["Vénus en chute : chez vous, l’affection se démontre et la déclaration se fait attendre."]},"roastWeight":2,"avoid":["Présenter la chute comme de la froideur","Réduire ce placement à la critique permanente"]}'::jsonb, 'draft_ai') on conflict (key, locale, kb_version) do update set body = excluded.body, updated_at = now() where public.interpretation_kb.review_status = 'draft_ai';
